      body: '【NPV（正味現在価値）法】\nNPV = Σ（年間CF ÷ (1+割引率)^t）- 初期投資額\nNPV > 0 → 投資すべき\nNPV = 0 → IRR（内部収益率）= 割引率\n\n【フリーCF（FCF）の計算】\nFCF = 税引後営業利益（NOPAT）+ 減価償却費 - 設備投資 - 運転資本増加額\n\n【タックスシールド（節税効果）】\n減価償却費は非現金費用であり税計算上の費用になる→税負担が減少。\nタックスシールド効果 = 減価償却費 × 税率\n\nFCF算定での扱い：\n①税引前利益 = 営業CF - 減価償却費\n②税金 = 税引前利益 × 税率\n③FCF = 営業CF - 税金 = 営業CF × (1-税率) + 減価償却費 × 税率\n\n【IRR（内部収益率）】\nNPV = 0になる割引率。資本コストよりIRRが大きければ投資採択。',
