// ============================================================
// localStorage
// ============================================================

const DEFAULT_DATA = {
  xp: 0,
  totalTasks: 0,
  streak: 0,
  lastDate: null,
  completedToday: [],
  history: [],
  weeklyData:      [0, 0, 0, 0, 0, 0, 0],
  weeklyXpData:    [0, 0, 0, 0, 0, 0, 0],
  weeklyXpHistory: [],
  weekStart: '',
  notes: [],
  financeProgress: {},
  caseProgress: {},
  dailyLog: {},
  procedureCase:    null,
  procedureChecked: [],
  dailyMissionBonus: null,
  reviewSchedule: {},
  geminiApiKey: '',
  essayHistory: [],
  stampCalendar: {},
  signalMastery: {},   // { [swId]: { correct, wrong, streak } }
  signalBest: {},      // { attack: 最高スコア, highlight: 最高スコア }
  aiQaHistory: [],  // AI質問履歴
  processProgress: {}, // { [probId]: { attempts, bestSteps } }  bestSteps は 0..4
  writingProgress: {}, // { [probId]: { copied, recalled, bestCoverage } }
};

function loadData() {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    return raw ? { ...DEFAULT_DATA, ...JSON.parse(raw) } : { ...DEFAULT_DATA };
  } catch {
    return { ...DEFAULT_DATA };
  }
}

function saveData(data) {
  try { localStorage.setItem(STORAGE_KEY, JSON.stringify(data)); } catch {}
}

function applyDateReset(d) {
  const today     = todayStr();
  const weekStart = getWeekStart();
  let u = { ...d };

  if (u.lastDate !== today) {
    const yesterday = new Date();
    yesterday.setDate(yesterday.getDate() - 1);
    u.streak = u.lastDate === localDateStr(yesterday) ? (u.streak || 0) + 1 : 0;
    u.completedToday = [];
  }

  if (u.weekStart !== weekStart) {
    const currentWeekXp = (u.weeklyXpData || []).reduce((a, b) => a + b, 0);
    if (currentWeekXp > 0) {
      const wh = [...(u.weeklyXpHistory || []), currentWeekXp];
      u.weeklyXpHistory = wh.slice(-8);
    }
    u.weeklyData   = [0, 0, 0, 0, 0, 0, 0];
    u.weeklyXpData = [0, 0, 0, 0, 0, 0, 0];
    u.weekStart    = weekStart;
  }

  return u;
}

