function QuestTab({ data, onCompleteQuest, onNavigate }) {
  const [timerItem, setTimerItem] = useState(null);

  const level      = getLevel(data.xp);
  const nextLevel  = getNextLevel(data.xp);
  const progress   = getXpProgress(data.xp);
  const todayIndex = getDayIndex();
  const todayDone  = data.completedToday.length;
  const thisWeek   = data.weeklyData.reduce((a, b) => a + b, 0);
  const today      = todayStr();
  const dailyMissions = getDailyMissions(today);

  return (
    <div style={{ padding: '16px 16px 80px' }}>
      {/* Level card */}
      <div style={{
        background: 'linear-gradient(135deg, #0d1a2e, #1a0d2e)',
        border: `1px solid ${C.accent}33`,
        borderRadius: 16, padding: '20px 20px 16px', marginBottom: 16,
      }}>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: 14 }}>
          <div>
            <div style={{ fontSize: 11, color: C.muted, marginBottom: 2 }}>Lv.{level.lv}</div>
            <div style={{ fontSize: 20, fontWeight: 700, color: C.accent }}>{level.name}</div>
          </div>
          <div style={{ textAlign: 'right' }}>
            <div style={{ fontSize: 26, fontWeight: 700, color: C.gold }}>{data.xp}</div>
            <div style={{ fontSize: 11, color: C.muted }}>XP</div>
          </div>
        </div>
        <div style={{ height: 8, background: C.border, borderRadius: 4, overflow: 'hidden' }}>
          <div style={{
            height: '100%', width: `${progress * 100}%`,
            background: `linear-gradient(90deg, ${C.purple}, ${C.accent})`,
            borderRadius: 4, transition: 'width 0.6s ease',
          }} />
        </div>
        {nextLevel ? (
          <div style={{ fontSize: 11, color: C.muted, marginTop: 6, textAlign: 'right' }}>
            あと {nextLevel.xp - data.xp} XP → {nextLevel.name}
          </div>
        ) : (
          <div style={{ fontSize: 11, color: C.gold, marginTop: 6, textAlign: 'right' }}>最高レベル達成！</div>
        )}
      </div>

      {/* Streak badge */}
      {data.streak > 0 && (
        <div style={{
          display: 'inline-flex', alignItems: 'center', gap: 6,
          background: '#1f1508', border: `1px solid ${C.orange}55`,
          borderRadius: 20, padding: '6px 14px', marginBottom: 16,
          fontSize: 14, color: C.orange, fontWeight: 700,
        }}>
          🔥 {data.streak}日連続
        </div>
      )}

      {/* Stats */}
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3,1fr)', gap: 8, marginBottom: 16 }}>
        {[
          { label: '今日完了', value: todayDone,       color: C.accent },
          { label: '累計',    value: data.totalTasks,  color: C.purple },
          { label: '今週',    value: thisWeek,         color: C.gold   },
        ].map(s => (
          <div key={s.label} style={{
            background: C.card, borderRadius: 12, padding: '12px 8px', textAlign: 'center',
          }}>
            <div style={{ fontSize: 24, fontWeight: 700, color: s.color }}>{s.value}</div>
            <div style={{ fontSize: 11, color: C.muted, marginTop: 2 }}>{s.label}</div>
          </div>
        ))}
      </div>

      {/* Daily missions */}
      {(() => {
        const missionsDoneCount = dailyMissions.filter(id => data.completedToday.includes(id)).length;
        const allDone = missionsDoneCount === 3;
        const bonusClaimed = data.dailyMissionBonus === today;
        return (
          <div style={{
            background: allDone ? 'linear-gradient(135deg, #1a1400, #0a1a0a)' : C.card,
            border: `1px solid ${allDone ? C.gold + '88' : C.border}`,
            borderRadius: 14, padding: '14px 16px', marginBottom: 14,
          }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 10 }}>
              <div style={{ fontSize: 13, fontWeight: 700, color: allDone ? C.gold : C.text }}>
                📋 今日のミッション
              </div>
              <div style={{ display: 'flex', alignItems: 'center', gap: 6 }}>
                {[0, 1, 2].map(i => (
                  <div key={i} style={{
                    width: 10, height: 10, borderRadius: '50%',
                    background: i < missionsDoneCount ? C.gold : '#334155',
                    transition: 'background 0.3s',
                  }} />
                ))}
                <span style={{ fontSize: 11, color: allDone ? C.gold : C.muted, marginLeft: 4, fontWeight: 700 }}>
                  {missionsDoneCount}/3
                </span>
              </div>
            </div>
            <div style={{ display: 'flex', flexDirection: 'column', gap: 6 }}>
              {dailyMissions.map(id => {
                const quest = QUESTS.find(q => q.id === id);
                const done = data.completedToday.includes(id);
                return (
                  <div key={id} style={{
                    display: 'flex', alignItems: 'center', gap: 10,
                    opacity: done ? 0.6 : 1,
                  }}>
                    <span style={{ fontSize: 16 }}>{quest.icon}</span>
                    <span style={{
                      fontSize: 13, color: done ? C.muted : C.text,
                      textDecoration: done ? 'line-through' : 'none', flex: 1,
                    }}>{quest.name}</span>
                    {done && <span style={{ fontSize: 14, color: C.green }}>✓</span>}
                    {!done && (
                      <span style={{ fontSize: 11, color: C.muted }}>+{quest.xp} XP</span>
                    )}
                  </div>
                );
              })}
            </div>
            {allDone && (
              <div style={{
                marginTop: 10, paddingTop: 10, borderTop: `1px solid ${C.gold}33`,
                fontSize: 12, color: C.gold, fontWeight: 700, textAlign: 'center',
              }}>
                {bonusClaimed ? '🎉 達成ボーナス +150 XP 受取済み！' : '🎉 3つ完了でボーナス +150 XP！'}
              </div>
            )}
          </div>
        );
      })()}

      {/* Due reviews */}
      {(() => {
        const dueIds = getDueReviews(data.reviewSchedule, today);
        if (dueIds.length === 0) return null;
        const allProblems = [...CASE_STUDY_PROBLEMS, ...FINANCE_PROBLEMS];
        const caseLabels = { case1: '事例I', case2: '事例II', case3: '事例III', case4: '事例IV' };
        return (
          <div style={{
            background: '#1a0e08', border: `1px solid ${C.orange}66`,
            borderRadius: 14, padding: '14px 16px', marginBottom: 14,
          }}>
            <div style={{ fontSize: 13, fontWeight: 700, color: C.orange, marginBottom: 10 }}>
              🔔 今日の復習 <span style={{ fontSize: 11, fontWeight: 400, color: C.muted }}>({dueIds.length}件)</span>
            </div>
            <div style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
              {dueIds.slice(0, 5).map(id => {
                const p = allProblems.find(x => x.id === id);
                if (!p) return null;
                const caseId = p.case || 'case4';
                return (
                  <div key={id} style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
                    <span style={{ fontSize: 18 }}>{p.icon}</span>
                    <div style={{ flex: 1, minWidth: 0 }}>
                      <div style={{ fontSize: 13, color: C.text, fontWeight: 600, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{p.title}</div>
                      <div style={{ fontSize: 11, color: C.muted }}>{caseLabels[caseId]}</div>
                    </div>
                    <button
                      onClick={() => onNavigate('finance', id)}
                      style={{
                        background: `${C.orange}22`, border: `1px solid ${C.orange}`,
                        borderRadius: 8, padding: '4px 10px',
                        fontSize: 12, color: C.orange, fontWeight: 700, cursor: 'pointer',
                      }}
                    >▶ 解く</button>
                  </div>
                );
              })}
              {dueIds.length > 5 && (
                <div style={{ fontSize: 11, color: C.muted, textAlign: 'center' }}>他 {dueIds.length - 5} 件</div>
              )}
            </div>
          </div>
        );
      })()}

      {/* Weekly chart */}
      <WeeklyChart weeklyData={data.weeklyData} todayIndex={todayIndex} />

      {/* Monthly stamp calendar */}
      <MonthlyStampCalendar stampCalendar={data.stampCalendar} />

      {/* Quick actions */}
      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 8, marginBottom: 16 }}>
        <button onClick={() => onNavigate('procedure')} style={{
          background: `${C.purple}22`, border: `1px solid ${C.purple}`,
          borderRadius: 12, padding: '12px 14px',
          color: C.text, cursor: 'pointer', textAlign: 'left',
          fontSize: 14, fontWeight: 600,
        }}>
          📋 手順ガイドを開く
        </button>
        <button onClick={() => onNavigate('reflection')} style={{
          background: `${C.green}22`, border: `1px solid ${C.green}`,
          borderRadius: 12, padding: '12px 14px',
          color: C.text, cursor: 'pointer', textAlign: 'left',
          fontSize: 14, fontWeight: 600,
        }}>
          📝 振り返りを書く
        </button>
      </div>

      {/* Mastery summary */}
      {(() => {
        const caseGroups = [
          { caseId: 'case1', label: '事例I', sub: '人事・組織', problems: CASE_STUDY_PROBLEMS.filter(p => p.case === 'case1'), isCaseStudy: true },
          { caseId: 'case2', label: '事例II', sub: 'マーケ', problems: CASE_STUDY_PROBLEMS.filter(p => p.case === 'case2'), isCaseStudy: true },
          { caseId: 'case3', label: '事例III', sub: '生産', problems: CASE_STUDY_PROBLEMS.filter(p => p.case === 'case3'), isCaseStudy: true },
          { caseId: 'case4', label: '事例IV', sub: '財務', problems: FINANCE_PROBLEMS, isCaseStudy: false },
        ];
        return (
          <div style={{ background: C.card, border: `1px solid ${C.border}`, borderRadius: 14, padding: '14px 16px', marginBottom: 14 }}>
            <div style={{ fontSize: 13, fontWeight: 700, color: C.text, marginBottom: 12 }}>📊 事例別習熟度</div>
            <div style={{ display: 'flex', flexDirection: 'column', gap: 10 }}>
              {caseGroups.map(g => {
                const store = g.isCaseStudy ? data.caseProgress : data.financeProgress;
                const masterCount = g.problems.filter(p => getMastery(store?.[p.id], p.steps.length) === 3).length;
                const total = g.problems.length;
                const ratio = total > 0 ? masterCount / total : 0;
                const allMastered = masterCount === total && total > 0;
                return (
                  <div key={g.caseId}>
                    <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 4 }}>
                      <div style={{ display: 'flex', alignItems: 'center', gap: 6 }}>
                        <span style={{ fontSize: 12, fontWeight: 700, color: allMastered ? C.gold : C.text }}>{g.label}</span>
                        <span style={{ fontSize: 11, color: C.muted }}>{g.sub}</span>
                      </div>
                      <div style={{ display: 'flex', alignItems: 'center', gap: 6 }}>
                        <StarRating mastery={Math.round(ratio * 3)} size={12} />
                        <span style={{ fontSize: 11, color: allMastered ? C.gold : C.muted, fontWeight: allMastered ? 700 : 400 }}>
                          {allMastered ? '全問マスター！' : `${masterCount}/${total}`}
                        </span>
                      </div>
                    </div>
                    <div style={{ height: 4, background: '#1e293b', borderRadius: 2, overflow: 'hidden' }}>
                      <div style={{
                        height: '100%', width: `${ratio * 100}%`,
                        background: allMastered ? C.gold : `linear-gradient(90deg, ${C.purple}, ${C.accent})`,
                        borderRadius: 2, transition: 'width 0.5s ease',
                      }} />
                    </div>
                  </div>
                );
              })}
            </div>
          </div>
        );
      })()}

      {/* Quest list */}
      <div style={{ fontSize: 13, color: C.muted, marginBottom: 8 }}>デイリークエスト</div>
      <div style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
        {QUESTS.map(quest => {
          const done = data.completedToday.includes(quest.id);
          return (
            <div
              key={quest.id}
              onClick={() => !done && setTimerItem(quest)}
              style={{
                background: done ? '#0d1a10' : C.card,
                border: `1px solid ${done ? C.green + '44' : C.border}`,
                borderRadius: 12, padding: '14px 16px',
                display: 'flex', alignItems: 'center', gap: 12,
                cursor: done ? 'default' : 'pointer',
                opacity: done ? 0.65 : 1,
              }}
            >
              <div style={{ fontSize: 22 }}>{quest.icon}</div>
              <div style={{ flex: 1 }}>
                <div style={{ fontSize: 14, fontWeight: 600, color: C.text }}>{quest.name}</div>
                <div style={{ fontSize: 11, color: C.muted }}>▶ {quest.minutes}分 · +{quest.xp} XP</div>
              </div>
              {quest.id === 'jireifolder' && (
                <button onClick={(e) => { e.stopPropagation(); openGoodNotes(); }} style={{
                  background: 'none', border: 'none', fontSize: 18, cursor: 'pointer',
                  padding: '0 4px', color: C.accent,
                }} title="GoodNotesを開く">🔗</button>
              )}
              {quest.id === 'aasvideo' && (
                <a href={AAS_URL} target="_blank" rel="noreferrer"
                   onClick={(e) => e.stopPropagation()} style={{
                  fontSize: 18, padding: '0 4px', color: C.accent, textDecoration: 'none',
                }} title="AASサイトを開く">🔗</a>
              )}
              {done ? (
                <div style={{ fontSize: 20, color: C.green }}>✓</div>
              ) : (
                <div style={{
                  background: `${C.accent}22`, border: `1px solid ${C.accent}`,
                  borderRadius: 8, padding: '3px 9px',
                  fontSize: 12, color: C.accent, fontWeight: 700,
                }}>
                  +{quest.xp}
                </div>
              )}
            </div>
          );
        })}
      </div>

      {timerItem && (
        <TimerModal
          item={timerItem}
          onClose={() => setTimerItem(null)}
          onComplete={(elapsed) => { onCompleteQuest(timerItem, elapsed); setTimerItem(null); }}
        />
      )}
    </div>
  );
}

// ============================================================
// ProcedureTab
// ============================================================

function ProcedureTab({ data, onCompleteCase, onNavigate, onUpdateProcedure }) {
  const [timerItem, setTimerItem] = useState(null);

  const selectedCase = data.procedureCase || null;
  const checkedSteps = data.procedureChecked || [];
  const allDone      = checkedSteps.length === STEPS.length;

  function setSelectedCase(c) {
    onUpdateProcedure({ procedureCase: c, procedureChecked: [] });
  }

  function goBack() {
    onUpdateProcedure({ procedureCase: null, procedureChecked: [] });
  }

  function toggleStep(id) {
    const next = checkedSteps.includes(id)
      ? checkedSteps.filter(x => x !== id)
      : [...checkedSteps, id];
    onUpdateProcedure({ procedureChecked: next });
  }

  function handleComplete() {
    onCompleteCase(selectedCase);
    onUpdateProcedure({ procedureCase: null, procedureChecked: [] });
    onNavigate('reflection');
  }

  if (!selectedCase) {
    return (
      <div style={{ padding: '16px 16px 80px' }}>
        <div style={{ fontSize: 18, fontWeight: 700, color: C.text, marginBottom: 6 }}>事例を選択</div>
        <div style={{ fontSize: 13, color: C.muted, marginBottom: 20 }}>
          どの事例の手順ガイドを使いますか？
        </div>
        <div style={{ display: 'flex', flexDirection: 'column', gap: 12 }}>
          {CASES.map(c => (
            <button
              key={c.id}
              onClick={() => setSelectedCase(c)}
              style={{
                background: C.card, border: `1px solid ${C.accent}44`,
                borderRadius: 14, padding: '18px 20px',
                color: C.text, cursor: 'pointer', textAlign: 'left',
                fontSize: 16, fontWeight: 600,
                display: 'flex', justifyContent: 'space-between', alignItems: 'center',
              }}
            >
              {c.full}
              <span style={{ color: C.accent, fontSize: 20 }}>›</span>
            </button>
          ))}
        </div>
      </div>
    );
  }

  return (
    <div style={{ padding: '16px 16px 80px' }}>
      {/* Back header */}
      <div style={{ display: 'flex', alignItems: 'center', gap: 12, marginBottom: 16 }}>
        <button
          onClick={goBack}
          style={{ background: 'none', border: 'none', color: C.accent, cursor: 'pointer', fontSize: 22, padding: 0 }}
        >
          ←
        </button>
        <div>
          <div style={{ fontSize: 16, fontWeight: 700, color: C.text }}>{selectedCase.full}</div>
          <div style={{ fontSize: 12, color: C.muted }}>{checkedSteps.length}/{STEPS.length} 完了</div>
        </div>
      </div>

      {/* Progress bar */}
      <div style={{ height: 4, background: C.border, borderRadius: 2, marginBottom: 20 }}>
        <div style={{
          height: '100%', width: `${(checkedSteps.length / STEPS.length) * 100}%`,
          background: C.green, borderRadius: 2, transition: 'width 0.3s',
        }} />
      </div>

      {/* Steps */}
      <div style={{ display: 'flex', flexDirection: 'column', gap: 10 }}>
        {STEPS.map(step => {
          const done = checkedSteps.includes(step.id);
          const pc   = PHASE_COLORS[step.phase] || C.muted;
          return (
            <div key={step.id} style={{
              background: done ? '#0d1a10' : C.card,
              border: `1px solid ${done ? C.green + '44' : C.border}`,
              borderRadius: 12, padding: '14px 16px',
            }}>
              <div style={{ display: 'flex', alignItems: 'center', gap: 12 }}>
                <div
                  onClick={() => toggleStep(step.id)}
                  style={{
                    width: 34, height: 34, borderRadius: '50%',
                    background: done ? C.green : pc + '22',
                    border: `2px solid ${done ? C.green : pc}`,
                    display: 'flex', alignItems: 'center', justifyContent: 'center',
                    cursor: 'pointer', flexShrink: 0,
                    fontSize: done ? 14 : 13, fontWeight: 700,
                    color: done ? '#fff' : pc,
                  }}
                >
                  {done ? '✓' : step.id}
                </div>
                <div style={{ flex: 1, minWidth: 0 }}>
                  <div style={{ marginBottom: 3 }}>
                    <span style={{
                      fontSize: 10, fontWeight: 700, color: pc,
                      background: pc + '22', borderRadius: 4, padding: '1px 6px',
                    }}>{step.phase}</span>
                  </div>
                  <div style={{ fontSize: 15, fontWeight: 600, color: C.text }}>{step.title}</div>
                  <div style={{ fontSize: 11, color: C.muted, marginTop: 2 }}>{step.hint}</div>
                </div>
                <button
                  onClick={() => setTimerItem(step)}
                  style={{
                    background: pc + '22', border: `1px solid ${pc}`,
                    borderRadius: 8, padding: '6px 10px',
                    color: pc, cursor: 'pointer',
                    fontSize: 12, fontWeight: 700, whiteSpace: 'nowrap', flexShrink: 0,
                  }}
                >
                  ▶ {step.minutes}分
                </button>
              </div>
            </div>
          );
        })}
      </div>

      {allDone && (
        <button
          onClick={handleComplete}
          style={{
            width: '100%', marginTop: 20, padding: 16,
            background: `linear-gradient(135deg, ${C.purple}, ${C.accent})`,
            border: 'none', borderRadius: 14,
            color: '#fff', fontWeight: 700, fontSize: 16, cursor: 'pointer',
          }}
        >
          🎉 事例クリア！ +100 XP
        </button>
      )}

      {timerItem && (
        <TimerModal
          item={timerItem}
          onClose={() => setTimerItem(null)}
          onComplete={() => { toggleStep(timerItem.id); setTimerItem(null); }}
        />
      )}
    </div>
  );
}

// ============================================================
// ReflectionTab
// ============================================================

function ReflectionTab({ data, onSaveNote, aiQaHistory, onUpdateMemo, onDeleteQa }) {
  const [reflMode,      setReflMode]      = useState('notes'); // 'notes' | 'ai'
  const [selectedCase,  setSelectedCase]  = useState(null);
  const [date,          setDate]          = useState(todayStr());
  const [good,          setGood]          = useState('');
  const [improve,       setImprove]       = useState('');
  const [keywords,      setKeywords]      = useState('');
  const [nextAction,    setNextAction]    = useState('');
  const [saved,         setSaved]         = useState(false);
  const [selectedNote,  setSelectedNote]  = useState(null);
  const qaList = aiQaHistory || [];

  function handleSave() {
    if (!selectedCase) return;
    onSaveNote({
      id: Date.now(),
      caseName: selectedCase.full,
      date, good, improve, keywords, nextAction,
      time: formatDateTime(),
    });
    setGood(''); setImprove(''); setKeywords(''); setNextAction('');
    setSaved(true);
    setTimeout(() => setSaved(false), 2000);
  }

  function handleDelete(id) {
    onSaveNote(null, id);
    setSelectedNote(null);
  }

  if (selectedNote) {
    return (
      <div style={{ padding: '16px 16px 80px' }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: 12, marginBottom: 20 }}>
          <button
            onClick={() => setSelectedNote(null)}
            style={{ background: 'none', border: 'none', color: C.accent, cursor: 'pointer', fontSize: 22, padding: 0 }}
          >←</button>
          <div>
            <div style={{ fontSize: 16, fontWeight: 700, color: C.text }}>{selectedNote.caseName}</div>
            <div style={{ fontSize: 12, color: C.muted }}>{selectedNote.date} · {selectedNote.time}</div>
          </div>
        </div>
        {[
          { label: 'よかった点',    value: selectedNote.good,       color: C.green  },
          { label: '改善点',        value: selectedNote.improve,    color: C.orange },
          { label: '重要キーワード', value: selectedNote.keywords,   color: C.accent },
          { label: '次回やること',  value: selectedNote.nextAction, color: C.purple },
        ].filter(f => f.value).map(f => (
          <div key={f.label} style={{
            background: f.color + '11', border: `1px solid ${f.color}33`,
            borderRadius: 12, padding: 16, marginBottom: 12,
          }}>
            <div style={{ fontSize: 11, fontWeight: 700, color: f.color, marginBottom: 6 }}>{f.label}</div>
            <div style={{ fontSize: 14, color: C.text, whiteSpace: 'pre-wrap', lineHeight: 1.6 }}>{f.value}</div>
          </div>
        ))}
        <button
          onClick={() => handleDelete(selectedNote.id)}
          style={{
            width: '100%', marginTop: 12, padding: 14,
            background: C.red + '22', border: `1px solid ${C.red}`,
            borderRadius: 12, color: C.red, cursor: 'pointer',
            fontWeight: 700, fontSize: 14,
          }}
        >
          削除
        </button>
      </div>
    );
  }

  const ta = {
    width: '100%', padding: 12, background: '#1f2937',
    border: '1px solid #374151', borderRadius: 8,
    color: C.text, fontSize: 14, resize: 'vertical',
    minHeight: 80, fontFamily: 'inherit', boxSizing: 'border-box',
    outline: 'none',
  };

  return (
    <div style={{ padding: '16px 16px 80px' }}>
      {/* モード切り替え */}
      <div style={{ display: 'flex', gap: 8, marginBottom: 16 }}>
        <button
          onClick={() => setReflMode('notes')}
          style={{
            flex: 1, padding: '10px 8px', borderRadius: 10, border: 'none',
            background: reflMode === 'notes' ? C.accent : C.card,
            color: reflMode === 'notes' ? '#000' : C.muted,
            fontWeight: reflMode === 'notes' ? 700 : 400,
            cursor: 'pointer', fontSize: 13,
          }}
        >📝 振り返りノート</button>
        <button
          onClick={() => setReflMode('ai')}
          style={{
            flex: 1, padding: '10px 8px', borderRadius: 10, border: 'none',
            background: reflMode === 'ai' ? C.accent : C.card,
            color: reflMode === 'ai' ? '#000' : C.muted,
            fontWeight: reflMode === 'ai' ? 700 : 400,
            cursor: 'pointer', fontSize: 13,
          }}
        >🤖 AI質問履歴 ({qaList.length})</button>
      </div>

      {reflMode === 'ai' ? (
        qaList.length === 0 ? (
          <div style={{ textAlign: 'center', padding: '60px 20px', color: C.muted, fontSize: 14 }}>
            まだAI質問履歴がありません
          </div>
        ) : (
          <div>
            {[...qaList].reverse().map(item => (
              <AiQaHistoryCard
                key={item.id}
                item={item}
                sameRefCount={item.refId ? qaList.filter(x => x.refId === item.refId).length : 1}
                onUpdateMemo={onUpdateMemo}
                onDeleteQa={onDeleteQa}
              />
            ))}
          </div>
        )
      ) : (
      <>
      <div style={{ fontSize: 13, color: C.muted, marginBottom: 8 }}>事例を選択</div>
      <div style={{ display: 'flex', gap: 6, marginBottom: 16 }}>
        {CASES.map(c => (
          <button
            key={c.id}
            onClick={() => setSelectedCase(c)}
            style={{
              flex: 1, padding: '8px 4px', borderRadius: 8, border: 'none',
              background: selectedCase?.id === c.id ? C.accent : C.card,
              color: selectedCase?.id === c.id ? '#000' : C.muted,
              fontWeight: selectedCase?.id === c.id ? 700 : 400,
              cursor: 'pointer', fontSize: 12,
            }}
          >
            {c.name}
          </button>
        ))}
      </div>

      <div style={{ marginBottom: 14 }}>
        <div style={{ fontSize: 13, color: C.muted, marginBottom: 6 }}>解いた日付</div>
        <input
          type="date" value={date} onChange={e => setDate(e.target.value)}
          style={{
            background: '#1f2937', border: '1px solid #374151',
            borderRadius: 8, padding: '8px 12px', color: C.text,
            fontSize: 14, width: '100%', boxSizing: 'border-box', outline: 'none',
          }}
        />
      </div>

      {[
        { label: '✅ よかった点',    value: good,       setter: setGood,       color: C.green  },
        { label: '🔧 改善点',        value: improve,    setter: setImprove,    color: C.orange },
        { label: '🔑 重要キーワード', value: keywords,   setter: setKeywords,   color: C.accent },
        { label: '🎯 次回やること',  value: nextAction, setter: setNextAction, color: C.purple },
      ].map(f => (
        <div key={f.label} style={{ marginBottom: 14 }}>
          <div style={{ fontSize: 13, color: f.color, fontWeight: 600, marginBottom: 6 }}>{f.label}</div>
          <textarea
            value={f.value}
            onChange={e => f.setter(e.target.value)}
            style={ta}
            placeholder={`${f.label}を入力...`}
          />
        </div>
      ))}

      <button
        onClick={handleSave}
        disabled={!selectedCase}
        style={{
          width: '100%', padding: 14,
          background: selectedCase
            ? `linear-gradient(135deg, ${C.purple}, ${C.accent})`
            : C.muted + '44',
          border: 'none', borderRadius: 12,
          color: selectedCase ? '#fff' : C.muted,
          fontWeight: 700, fontSize: 15,
          cursor: selectedCase ? 'pointer' : 'not-allowed',
        }}
      >
        {saved ? '✓ 保存しました' : '保存'}
      </button>

      {data.notes.length > 0 && (
        <>
          <div style={{ fontSize: 13, color: C.muted, margin: '20px 0 8px' }}>
            保存済みノート ({data.notes.length})
          </div>
          <div style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
            {[...data.notes].reverse().map(note => (
              <div
                key={note.id}
                onClick={() => setSelectedNote(note)}
                style={{
                  background: C.card, border: `1px solid ${C.border}`,
                  borderRadius: 12, padding: '12px 16px',
                  cursor: 'pointer', display: 'flex', justifyContent: 'space-between', alignItems: 'center',
                }}
              >
                <div>
                  <div style={{ fontSize: 14, fontWeight: 600, color: C.text }}>{note.caseName}</div>
                  <div style={{ fontSize: 12, color: C.muted }}>{note.date}</div>
                </div>
                <span style={{ color: C.accent, fontSize: 18 }}>›</span>
              </div>
            ))}
          </div>
        </>
      )}
      </>
      )}
    </div>
  );
}

// ============================================================
// AiQaHistoryCard
// ============================================================

function AiQaHistoryCard({ item, sameRefCount = 1, onUpdateMemo, onDeleteQa }) {
  const [open, setOpen] = useState(false);
  const [memo, setMemo] = useState(item.memo || '');

  return (
    <div style={{ background: C.card, border: `1px solid ${C.border}`, borderRadius: 12, marginBottom: 10, overflow: 'hidden' }}>
      <button
        onClick={() => setOpen(o => !o)}
        style={{ display: 'block', width: '100%', textAlign: 'left', background: 'none', border: 'none', padding: '14px 16px', cursor: 'pointer' }}
      >
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', gap: 8 }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: 8, minWidth: 0, flex: 1 }}>
            <span style={{ fontSize: 11, padding: '2px 7px', borderRadius: 6, background: C.purple + '22', color: C.purple, fontWeight: 700, flexShrink: 0 }}>
              {item.source}
            </span>
            {item.wasCorrect !== undefined && (
              <span style={{
                fontSize: 11, padding: '2px 7px', borderRadius: 6, flexShrink: 0, fontWeight: 700,
                background: (item.wasCorrect ? C.green : C.red) + '22',
                color: item.wasCorrect ? C.green : C.red,
              }}>{item.wasCorrect ? '正解' : '不正解'}</span>
            )}
            {sameRefCount > 1 && (
              <span style={{ fontSize: 11, padding: '2px 7px', borderRadius: 6, background: C.gold + '22', color: C.gold, fontWeight: 700, flexShrink: 0 }}>
                同じ問題で{sameRefCount}件
              </span>
            )}
            <span style={{ fontSize: 11, color: C.muted, flexShrink: 0 }}>{item.date}</span>
            <span style={{
              fontSize: 13, color: C.text, overflow: 'hidden', textOverflow: 'ellipsis',
              whiteSpace: 'nowrap', minWidth: 0,
            }}>{item.userQuestion}</span>
          </div>
          <span style={{ color: C.muted, fontSize: 12, flexShrink: 0 }}>{open ? '▲' : '▼'}</span>
        </div>
      </button>
      {open && (
        <div style={{ padding: '0 16px 16px' }}>
          {item.questionText && (
            <div style={{ fontSize: 13, color: C.text, marginBottom: 8, lineHeight: 1.6 }}>{item.questionText}</div>
          )}
          <div style={{ fontSize: 12, color: C.red, marginBottom: 6 }}>
            <span style={{ fontWeight: 700 }}>あなたの解答：</span>{item.myAnswer}
          </div>
          <div style={{ fontSize: 12, color: C.green, marginBottom: 6 }}>
            <span style={{ fontWeight: 700 }}>正解：</span>{item.correctAnswer}
          </div>
          <div style={{ fontSize: 12, color: C.accent, marginBottom: 8 }}>
            <span style={{ fontWeight: 700 }}>質問：</span>{item.userQuestion}
          </div>
          <div style={{
            background: C.bg, borderRadius: 8, padding: '10px 12px', marginBottom: 10,
            fontSize: 13, color: C.text, whiteSpace: 'pre-wrap', lineHeight: 1.8,
          }}>
            {item.aiAnswer}
          </div>
          <textarea
            value={memo}
            onChange={e => setMemo(e.target.value)}
            onBlur={() => onUpdateMemo(item.id, memo)}
            placeholder="自分用のメモ..."
            rows={2}
            style={{
              width: '100%', padding: 10, background: '#1f2937', border: '1px solid #374151',
              borderRadius: 8, color: C.text, fontSize: 13, resize: 'vertical',
              fontFamily: 'inherit', boxSizing: 'border-box', outline: 'none', marginBottom: 8,
            }}
          />
          <button
            onClick={() => onDeleteQa(item.id)}
            style={{
              background: 'none', border: 'none', color: C.red,
              fontSize: 12, cursor: 'pointer', padding: 0,
            }}
          >削除</button>
        </div>
      )}
    </div>
  );
}

// ============================================================
// HistoryTab
// ============================================================

function HistoryTab({ data }) {
  const [histView, setHistView]   = useState('calendar');
  const [calMode, setCalMode]     = useState('month');
  const [calMonth, setCalMonth]   = useState(new Date());
  const [selectedDay, setSelectedDay] = useState(null);

  const history         = data.history || [];
  const recent          = [...history].slice(-40).reverse();
  const totalSeconds    = history.reduce((sum, item) => sum + (item.elapsed || 0), 0);
  const caseClears      = history.filter(item => (item.name || '').includes('クリア')).length;
  const weeklyXpHistory = data.weeklyXpHistory || [];
  const currentWeekXp   = (data.weeklyXpData || []).reduce((a, b) => a + b, 0);
  const chartWeeks      = [...weeklyXpHistory.slice(-4), currentWeekXp];
  const maxWkXp         = Math.max(...chartWeeks, 1);
  const showChart       = chartWeeks.some(v => v > 0);
  const dailyLog        = data.dailyLog || {};
  const todayKey        = todayStr();

  function getDayColor(dateKey) {
    const e = dailyLog[dateKey];
    if (!e || e.tasks === 0) return '#1e293b';
    if (e.tasks <= 2) return C.purple + '66';
    if (e.tasks <= 5) return C.purple;
    if (e.tasks <= 9) return C.accent + 'aa';
    return C.gold;
  }

  // Monthly calendar grid
  const year  = calMonth.getFullYear();
  const month = calMonth.getMonth();
  const firstDay    = new Date(year, month, 1).getDay();
  const daysInMonth = new Date(year, month + 1, 0).getDate();
  const calDays = [];
  for (let i = 0; i < firstDay; i++) calDays.push(null);
  for (let d = 1; d <= daysInMonth; d++) {
    const dk = `${year}-${String(month + 1).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
    calDays.push({ dateKey: dk, day: d });
  }

  // Year heatmap: 53 weeks ending at today
  function getYearGrid() {
    const today = new Date();
    const start = new Date(today);
    start.setDate(today.getDate() - today.getDay() - 52 * 7);
    const weeks = [];
    let cur = new Date(start);
    while (cur <= today || weeks.length < 53) {
      const week = [];
      for (let d = 0; d < 7; d++) {
        week.push(cur <= today ? new Date(cur) : null);
        cur.setDate(cur.getDate() + 1);
      }
      weeks.push(week);
      if (cur > today && week.every(x => x === null || localDateStr(x) >= todayKey)) break;
    }
    return weeks;
  }

  function getMonthLabels(weeks) {
    const labels = []; let lastM = -1;
    weeks.forEach((week, wi) => {
      const first = week.find(Boolean);
      if (first) { const m = first.getMonth(); if (m !== lastM) { labels.push({ wi, label: `${m + 1}月` }); lastM = m; } }
    });
    return labels;
  }

  const yearWeeks = calMode === 'year' ? getYearGrid() : [];

  return (
    <div style={{ padding: '16px 16px 80px' }}>
      {/* View toggle */}
      <div style={{ display: 'flex', gap: 6, marginBottom: 16 }}>
        {[{ id: 'calendar', label: '📅 カレンダー' }, { id: 'stats', label: '📊 統計' }, { id: 'list', label: '📋 履歴' }].map(v => (
          <button key={v.id} onClick={() => setHistView(v.id)} style={{
            flex: 1, padding: '8px 0', borderRadius: 20, border: 'none',
            background: histView === v.id ? C.accent : C.card,
            color: histView === v.id ? '#000' : C.muted,
            fontWeight: histView === v.id ? 700 : 400,
            cursor: 'pointer', fontSize: 12,
          }}>{v.label}</button>
        ))}
      </div>

      {/* ---- CALENDAR VIEW ---- */}
      {histView === 'calendar' && (
        <div>
          <div style={{ display: 'flex', gap: 6, marginBottom: 14, justifyContent: 'center' }}>
            {[{ id: 'month', label: '月' }, { id: 'year', label: '年' }].map(m => (
              <button key={m.id} onClick={() => { setCalMode(m.id); setSelectedDay(null); }} style={{
                padding: '5px 24px', borderRadius: 20, border: 'none',
                background: calMode === m.id ? C.purple : C.card,
                color: calMode === m.id ? '#fff' : C.muted,
                fontWeight: calMode === m.id ? 700 : 400,
                cursor: 'pointer', fontSize: 13,
              }}>{m.label}</button>
            ))}
          </div>

          {/* Monthly calendar */}
          {calMode === 'month' && (
            <div style={{ background: C.card, border: `1px solid ${C.border}`, borderRadius: 14, padding: 16 }}>
              <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: 12 }}>
                <button onClick={() => { const d = new Date(calMonth); d.setMonth(d.getMonth() - 1); setCalMonth(d); setSelectedDay(null); }}
                  style={{ background: 'none', border: 'none', color: C.accent, cursor: 'pointer', fontSize: 20, padding: '0 8px' }}>◀</button>
                <div style={{ fontSize: 16, fontWeight: 700, color: C.text }}>{year}年{month + 1}月</div>
                <button onClick={() => { const d = new Date(calMonth); d.setMonth(d.getMonth() + 1); setCalMonth(d); setSelectedDay(null); }}
                  style={{ background: 'none', border: 'none', color: C.accent, cursor: 'pointer', fontSize: 20, padding: '0 8px' }}>▶</button>
              </div>

              <div style={{ display: 'grid', gridTemplateColumns: 'repeat(7, 1fr)', gap: 2, marginBottom: 4 }}>
                {['日','月','火','水','木','金','土'].map((d, i) => (
                  <div key={d} style={{ textAlign: 'center', fontSize: 10, padding: '2px 0',
                    color: i === 0 ? '#ef4444' : i === 6 ? '#60a5fa' : C.muted }}>{d}</div>
                ))}
              </div>

              <div style={{ display: 'grid', gridTemplateColumns: 'repeat(7, 1fr)', gap: 2 }}>
                {calDays.map((cell, i) => {
                  if (!cell) return <div key={i} />;
                  const { dateKey, day } = cell;
                  const isToday    = dateKey === todayKey;
                  const isSelected = selectedDay === dateKey;
                  const e = dailyLog[dateKey];
                  return (
                    <div key={i} onClick={() => setSelectedDay(isSelected ? null : dateKey)} style={{
                      aspectRatio: '1', borderRadius: 8,
                      background: getDayColor(dateKey),
                      border: `1.5px solid ${isSelected ? C.gold : isToday ? C.accent : 'transparent'}`,
                      display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center',
                      cursor: 'pointer',
                    }}>
                      <div style={{ fontSize: 11, color: isToday ? C.accent : C.text, fontWeight: isToday ? 700 : 400 }}>{day}</div>
                      {e && e.tasks > 0 && <div style={{ fontSize: 8, color: '#fff', opacity: 0.85 }}>{e.tasks}</div>}
                    </div>
                  );
                })}
              </div>

              {selectedDay && (() => {
                const e = dailyLog[selectedDay];
                const [, m, d] = selectedDay.split('-');
                return (
                  <div style={{ marginTop: 12, padding: '10px 14px', background: C.purple + '22', border: `1px solid ${C.purple}55`, borderRadius: 10 }}>
                    {e && e.tasks > 0 ? (
                      <>
                        <div style={{ fontSize: 13, fontWeight: 700, color: C.text, marginBottom: 6 }}>{parseInt(m)}月{parseInt(d)}日</div>
                        <div style={{ display: 'flex', gap: 16 }}>
                          <div style={{ fontSize: 13, color: C.accent }}>✓ {e.tasks} タスク</div>
                          <div style={{ fontSize: 13, color: C.gold }}>＋{e.xp} XP</div>
                        </div>
                      </>
                    ) : (
                      <div style={{ fontSize: 13, color: C.muted }}>{parseInt(m)}月{parseInt(d)}日 — 活動なし</div>
                    )}
                  </div>
                );
              })()}
            </div>
          )}

          {/* Year heatmap */}
          {calMode === 'year' && (
            <div style={{ background: C.card, border: `1px solid ${C.border}`, borderRadius: 14, padding: 16 }}>
              <div style={{ fontSize: 13, fontWeight: 700, color: C.text, marginBottom: 12 }}>過去1年の学習記録</div>
              <div style={{ overflowX: 'auto', paddingBottom: 4 }}>
                {(() => {
                  const CELL = 11; const GAP = 2;
                  const monthLabels = getMonthLabels(yearWeeks);
                  return (
                    <div style={{ display: 'inline-flex', gap: 0 }}>
                      {/* Day labels */}
                      <div style={{ display: 'flex', flexDirection: 'column', gap: GAP, marginTop: 16, marginRight: 4 }}>
                        {['日','月','火','水','木','金','土'].map((l, i) => (
                          <div key={i} style={{ height: CELL, fontSize: 8, color: C.muted, lineHeight: `${CELL}px` }}>
                            {i % 2 === 1 ? l : ''}
                          </div>
                        ))}
                      </div>
                      {/* Weeks */}
                      <div>
                        <div style={{ display: 'flex', gap: GAP, marginBottom: 2, height: 14 }}>
                          {yearWeeks.map((_, wi) => {
                            const ml = monthLabels.find(m => m.wi === wi);
                            return (
                              <div key={wi} style={{ width: CELL, fontSize: 8, color: C.muted, overflow: 'visible', whiteSpace: 'nowrap' }}>
                                {ml ? ml.label : ''}
                              </div>
                            );
                          })}
                        </div>
                        <div style={{ display: 'flex', gap: GAP }}>
                          {yearWeeks.map((week, wi) => (
                            <div key={wi} style={{ display: 'flex', flexDirection: 'column', gap: GAP }}>
                              {week.map((date, di) => {
                                if (!date) return <div key={di} style={{ width: CELL, height: CELL }} />;
                                const dk = localDateStr(date);
                                const isToday = dk === todayKey;
                                return (
                                  <div key={di} onClick={() => setSelectedDay(selectedDay === dk ? null : dk)} style={{
                                    width: CELL, height: CELL, borderRadius: 2,
                                    background: getDayColor(dk),
                                    border: isToday ? `1px solid ${C.accent}` : selectedDay === dk ? `1px solid ${C.gold}` : 'none',
                                    cursor: 'pointer',
                                  }} />
                                );
                              })}
                            </div>
                          ))}
                        </div>
                      </div>
                    </div>
                  );
                })()}
              </div>

              {/* Legend */}
              <div style={{ display: 'flex', alignItems: 'center', gap: 6, marginTop: 10 }}>
                <div style={{ fontSize: 10, color: C.muted }}>少</div>
                {['#1e293b', C.purple + '66', C.purple, C.accent + 'aa', C.gold].map((c, i) => (
                  <div key={i} style={{ width: 11, height: 11, borderRadius: 2, background: c }} />
                ))}
                <div style={{ fontSize: 10, color: C.muted }}>多</div>
              </div>

              {selectedDay && dailyLog[selectedDay] && (() => {
                const e = dailyLog[selectedDay];
                const [, m, d] = selectedDay.split('-');
                return (
                  <div style={{ marginTop: 10, padding: '8px 12px', background: C.purple + '22', border: `1px solid ${C.purple}55`, borderRadius: 10 }}>
                    <div style={{ display: 'flex', gap: 16, alignItems: 'center' }}>
                      <div style={{ fontSize: 12, color: C.muted }}>{parseInt(m)}月{parseInt(d)}日</div>
                      <div style={{ fontSize: 12, color: C.accent }}>✓ {e.tasks} タスク</div>
                      <div style={{ fontSize: 12, color: C.gold }}>＋{e.xp} XP</div>
                    </div>
                  </div>
                );
              })()}
            </div>
          )}
        </div>
      )}

      {/* ---- STATS VIEW ---- */}
      {histView === 'stats' && (
        <div style={{ background: C.card, border: `1px solid ${C.border}`, borderRadius: 14, padding: 16 }}>
          <div style={{ fontSize: 13, fontWeight: 700, color: C.text, marginBottom: 14 }}>📊 学習統計</div>
          <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 10, marginBottom: showChart ? 16 : 0 }}>
            <div style={{ background: C.accent + '11', border: `1px solid ${C.accent}33`, borderRadius: 10, padding: '10px 12px' }}>
              <div style={{ fontSize: 10, color: C.muted, marginBottom: 4 }}>⏱ 総学習時間</div>
              <div style={{ fontSize: 18, fontWeight: 700, color: C.accent }}>{totalSeconds > 0 ? formatStudyTime(totalSeconds) : '—'}</div>
            </div>
            <div style={{ background: C.gold + '11', border: `1px solid ${C.gold}33`, borderRadius: 10, padding: '10px 12px' }}>
              <div style={{ fontSize: 10, color: C.muted, marginBottom: 4 }}>🎯 事例クリア</div>
              <div style={{ fontSize: 18, fontWeight: 700, color: C.gold }}>{caseClears}回</div>
            </div>
          </div>
          {showChart && (
            <>
              <div style={{ fontSize: 11, color: C.muted, marginBottom: 8 }}>週別XP推移</div>
              <div style={{ display: 'flex', alignItems: 'flex-end', gap: 6, height: 64 }}>
                {chartWeeks.map((xp, i) => {
                  const isCurrent = i === chartWeeks.length - 1;
                  const label = isCurrent ? '今週' : `${chartWeeks.length - 1 - i}週前`;
                  return (
                    <div key={i} style={{ flex: 1, display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 2 }}>
                      <div style={{ fontSize: 9, color: C.muted, minHeight: 12 }}>{xp > 0 ? xp : ''}</div>
                      <div style={{
                        width: '100%', height: `${Math.max((xp / maxWkXp) * 40, 3)}px`,
                        background: isCurrent ? `linear-gradient(180deg, ${C.accent}, ${C.purple})` : C.muted + '55',
                        borderRadius: 3,
                      }} />
                      <div style={{ fontSize: 9, color: isCurrent ? C.accent : C.muted, fontWeight: isCurrent ? 700 : 400 }}>{label}</div>
                    </div>
                  );
                })}
              </div>
            </>
          )}
        </div>
      )}

      {/* ---- LIST VIEW ---- */}
      {histView === 'list' && (
        recent.length === 0 ? (
          <div style={{ padding: '60px 0', textAlign: 'center', color: C.muted }}>
            <div style={{ fontSize: 48, marginBottom: 12 }}>📜</div>
            <div style={{ fontSize: 16 }}>まだ履歴がありません</div>
            <div style={{ fontSize: 13, marginTop: 8 }}>クエストを完了すると表示されます</div>
          </div>
        ) : (
          <>
            <div style={{ fontSize: 13, color: C.muted, marginBottom: 12 }}>完了タスク（最新{recent.length}件）</div>
            <div style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
              {recent.map((item, i) => (
                <div key={i} style={{
                  background: C.card, border: `1px solid ${C.border}`,
                  borderRadius: 12, padding: '12px 16px',
                  display: 'flex', alignItems: 'center', gap: 12,
                }}>
                  <div style={{ fontSize: 22 }}>{item.icon || '✅'}</div>
                  <div style={{ flex: 1 }}>
                    <div style={{ fontSize: 14, fontWeight: 600, color: C.text }}>{item.name}</div>
                    <div style={{ fontSize: 12, color: C.muted }}>{item.time}{item.elapsed ? ` · ${formatStudyTime(item.elapsed)}` : ''}</div>
                  </div>
                  <div style={{ fontSize: 13, fontWeight: 700, color: C.gold, background: C.gold + '22', borderRadius: 8, padding: '3px 8px' }}>
                    +{item.xp}
                  </div>
                </div>
              ))}
            </div>
          </>
        )
      )}
    </div>
  );
}

// ============================================================
// HistoryEssayCard
// ============================================================

function HistoryEssayCard({ item, scoreColor, caseColors, caseProblemMap }) {
  const [open, setOpen] = useState(false);
  return (
    <div style={{ background: '#111827', border: '1px solid #1f2937', borderRadius: 12, marginBottom: 10, overflow: 'hidden' }}>
      <button
        onClick={() => setOpen(o => !o)}
        style={{ display: 'block', width: '100%', textAlign: 'left', background: 'none', border: 'none', padding: '14px 16px', cursor: 'pointer' }}
      >
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: 8, flexWrap: 'wrap' }}>
            <span style={{ fontSize: 11, padding: '2px 7px', borderRadius: 6, background: `${caseColors[item.caseId] || '#7c3aed'}22`, color: caseColors[item.caseId] || '#7c3aed', fontWeight: 700 }}>
              {caseProblemMap[item.caseId] || item.caseId}
            </span>
            <span style={{ fontSize: 13, fontWeight: 600, color: '#e2e8f0' }}>{item.title}</span>
          </div>
          <div style={{ display: 'flex', alignItems: 'center', gap: 8, flexShrink: 0 }}>
            <span style={{ fontSize: 14, fontWeight: 700, color: scoreColor }}>{item.score}/10</span>
            <span style={{ fontSize: 11, color: '#64748b' }}>{item.date}</span>
            <span style={{ color: '#64748b', fontSize: 12 }}>{open ? '▲' : '▼'}</span>
          </div>
        </div>
      </button>
      {open && (
        <div style={{ padding: '0 16px 16px' }}>
          <div style={{ background: '#0a0e1a', borderRadius: 8, padding: '10px 12px', marginBottom: 10, fontSize: 13, color: '#e2e8f0', lineHeight: 1.6, whiteSpace: 'pre-wrap' }}>
            {item.answer}
          </div>
          {item.good && (
            <div style={{ fontSize: 12, color: '#10b981', marginBottom: 6 }}>
              <span style={{ fontWeight: 700 }}>✓ 良かった点：</span>{item.good}
            </div>
          )}
          {item.improve && (
            <div style={{ fontSize: 12, color: '#f59e0b', marginBottom: 6 }}>
              <span style={{ fontWeight: 700 }}>△ 改善点：</span>{item.improve}
            </div>
          )}
          {item.hint && (
            <div style={{ fontSize: 12, color: '#a78bfa' }}>
              <span style={{ fontWeight: 700 }}>💡 ポイント：</span>{item.hint}
            </div>
          )}
        </div>
      )}
    </div>
  );
}

// ============================================================
// AiQuestionModal
// ============================================================

function AiQuestionModal({ context, apiKey, onSave, onClose }) {
  const [showReview, setShowReview] = useState(true);
  const [question, setQuestion]     = useState('');
  const [answer, setAnswer]         = useState('');
  const [loading, setLoading]       = useState(false);
  const [error, setError]           = useState('');

  const wasCorrect = !!context.wasCorrect;

  const quickQuestions = wasCorrect ? [
    '他の選択肢がなぜ誤りなのか教えて',
    'この論点を本試験の答案でどう書けばいい？',
    '関連して押さえておくべき論点は？',
  ] : [
    'なぜこの選択肢が正解なのか、根拠を詳しく教えて',
    '私が選んだ選択肢は何が間違っているの？',
    '本試験で似た論点が出たらどう判断すればいい？',
  ];

  function insertQuickQuestion(q) {
    setQuestion(prev => (prev.trim() ? `${prev}\n${q}` : q));
  }

  async function askAi() {
    if (!question.trim() || !apiKey) return;
    setLoading(true);
    setError('');
    setAnswer('');
    const resultLine = wasCorrect
      ? '受験者はこの問題に正解しています。理解をさらに深められるよう答えてください。'
      : '受験者はこの問題に不正解でした。なぜ間違えたのかを解きほぐすように答えてください。';
    const prompt = `あなたは中小企業診断士2次試験の指導講師です。受験者から問題についての質問が来ています。簡潔に、しかし本質が分かるように日本語で答えてください。
${resultLine}

【問題】${context.questionText}
【受験者の解答】${context.myAnswer}
【正解】${context.correctAnswer}
【正誤】${wasCorrect ? '正解' : '不正解'}
【解説】${context.explanation}
【受験者の質問】${question}

300字程度で回答してください。markdownの記号（**や#）は使わないでください。`;
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), 30000);
    try {
      const res = await fetch(
        `https://generativelanguage.googleapis.com/v1beta/models/gemini-2.5-flash:generateContent?key=${apiKey}`,
        {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ contents: [{ parts: [{ text: prompt }] }] }),
          signal: controller.signal,
        }
      );
      clearTimeout(timer);
      if (!res.ok) {
        const errText = await res.text().catch(() => '');
        const errBody = (() => { try { return JSON.parse(errText); } catch { return null; } })();
        const msg = errBody?.error?.message || `HTTP ${res.status}`;
        setError(`APIエラー: ${msg}`);
        setLoading(false);
        return;
      }
      const json = await res.json();
      const text = json?.candidates?.[0]?.content?.parts?.[0]?.text || '';
      setAnswer(text);
    } catch (e) {
      clearTimeout(timer);
      const msg = e.name === 'AbortError' ? 'タイムアウト（30秒）しました。再度お試しください。' : `ネットワークエラー: ${e.message}`;
      setError(msg);
    }
    setLoading(false);
  }

  return (
    <div style={{
      position: 'fixed', inset: 0, background: 'rgba(0,0,0,0.85)', zIndex: 2000,
      display: 'flex', alignItems: 'flex-start', justifyContent: 'center',
      overflowY: 'auto', padding: '24px 16px',
    }}>
      <div style={{
        background: C.card, border: `1px solid ${C.border}`, borderRadius: 16,
        padding: 20, width: '100%', maxWidth: 440,
      }}>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 16 }}>
          <div style={{ fontSize: 16, fontWeight: 700, color: C.text }}>🤖 AIに質問する</div>
          <button onClick={onClose} style={{ background: 'none', border: 'none', color: C.muted, fontSize: 22, cursor: 'pointer', padding: 0 }}>×</button>
        </div>

        {/* 問題のふりかえり（折りたたみ） */}
        <div style={{ background: C.bg, border: `1px solid ${C.border}`, borderRadius: 12, marginBottom: 16, overflow: 'hidden' }}>
          <button
            onClick={() => setShowReview(s => !s)}
            style={{ display: 'block', width: '100%', textAlign: 'left', background: 'none', border: 'none', padding: '12px 14px', cursor: 'pointer', color: C.text, fontSize: 13, fontWeight: 700 }}
          >
            問題のふりかえり {showReview ? '▲' : '▼'}
          </button>
          {showReview && (
            <div style={{ padding: '0 14px 14px', fontSize: 13, lineHeight: 1.6 }}>
              <div style={{ color: C.text, marginBottom: 8 }}>{context.questionText}</div>
              <div style={{ color: wasCorrect ? C.green : C.red, marginBottom: 6 }}>
                <span style={{ fontWeight: 700 }}>あなたの解答（{wasCorrect ? '正解' : '不正解'}）：</span>{context.myAnswer}
              </div>
              {!wasCorrect && (
                <div style={{ color: C.green, marginBottom: 6 }}><span style={{ fontWeight: 700 }}>正解：</span>{context.correctAnswer}</div>
              )}
              {context.explanation && (
                <div style={{ color: C.muted }}><span style={{ fontWeight: 700, color: C.text }}>解説：</span>{context.explanation}</div>
              )}
            </div>
          )}
        </div>

        {!apiKey ? (
          <div style={{
            background: C.orange + '11', border: `1px solid ${C.orange}44`, borderRadius: 10,
            padding: 14, fontSize: 13, color: C.orange, textAlign: 'center',
          }}>
            📝 論述タブでGeminiのAPIキーを設定してください
          </div>
        ) : (
          <>
            <textarea
              value={question}
              onChange={e => setQuestion(e.target.value)}
              rows={4}
              placeholder="例）なぜBではなくCが正解なのか、与件文のどこを根拠にすればいいですか？"
              style={{
                width: '100%', padding: 12, background: '#1f2937', border: '1px solid #374151',
                borderRadius: 8, color: C.text, fontSize: 14, resize: 'vertical',
                fontFamily: 'inherit', boxSizing: 'border-box', outline: 'none', marginBottom: 10,
              }}
            />

            {/* よく使う質問（textareaに追記） */}
            <div style={{ fontSize: 11, color: C.muted, marginBottom: 6 }}>よく使う質問 ↓</div>
            <div style={{ display: 'flex', flexDirection: 'column', gap: 6, marginBottom: 10 }}>
              {quickQuestions.map((q, i) => (
                <button
                  key={i}
                  onClick={() => insertQuickQuestion(q)}
                  style={{
                    background: C.accent + '11', border: `1px solid ${C.accent}33`, borderRadius: 8,
                    padding: '7px 10px', color: C.accent, fontSize: 11, textAlign: 'left', cursor: 'pointer',
                  }}
                >{q}</button>
              ))}
            </div>

            <div style={{ fontSize: 11, color: C.muted, marginBottom: 8 }}>自由に日本語で質問できます</div>

            <button
              onClick={askAi}
              disabled={loading || !question.trim()}
              style={{
                width: '100%', padding: 12, borderRadius: 10, border: 'none',
                background: (loading || !question.trim()) ? C.muted + '44' : `linear-gradient(135deg, ${C.purple}, ${C.accent})`,
                color: (loading || !question.trim()) ? C.muted : '#fff',
                fontWeight: 700, fontSize: 14,
                cursor: (loading || !question.trim()) ? 'not-allowed' : 'pointer',
              }}
            >
              {loading ? '考え中...' : '質問する'}
            </button>

            {error && (
              <div style={{ marginTop: 12, fontSize: 13, color: C.red }}>{error}</div>
            )}

            {answer && (
              <>
                <div style={{
                  marginTop: 14, background: C.purple + '11', border: `1px solid ${C.purple}33`,
                  borderRadius: 10, padding: 14, fontSize: 13, color: C.text,
                  whiteSpace: 'pre-wrap', lineHeight: 1.8,
                }}>
                  {answer}
                </div>
                <button
                  onClick={() => { onSave({ userQuestion: question, aiAnswer: answer, wasCorrect }); onClose(); }}
                  style={{
                    width: '100%', marginTop: 12, padding: 12, borderRadius: 10,
                    background: C.gold + '22', border: `1px solid ${C.gold}`,
                    color: C.gold, fontWeight: 700, fontSize: 13, cursor: 'pointer',
                  }}
                >📌 メモに保存</button>
              </>
            )}
          </>
        )}
      </div>
    </div>
  );
}

// ============================================================
// PastQaPanel（同じ問題について過去に聞いたAI質問の一覧）
// ============================================================

function PastQaPanel({ refId, history }) {
  const [open, setOpen] = useState(false);
  const past = (history || []).filter(x => x.refId === refId);
  if (past.length === 0) return null;

  return (
    <div style={{ background: C.gold + '11', border: `1px solid ${C.gold}44`, borderRadius: 10, marginBottom: 10, overflow: 'hidden' }}>
      <button
        onClick={() => setOpen(o => !o)}
        style={{ display: 'block', width: '100%', textAlign: 'left', background: 'none', border: 'none', padding: '10px 12px', cursor: 'pointer', color: C.gold, fontSize: 12, fontWeight: 700 }}
      >
        📌 この問題の過去メモ ({past.length}件) {open ? '▲' : '▼'}
      </button>
      {open && (
        <div style={{ padding: '0 12px 12px' }}>
          {[...past].reverse().map(m => (
            <div key={m.id} style={{ marginBottom: 8, paddingBottom: 8, borderBottom: `1px solid ${C.border}` }}>
              <div style={{ fontSize: 11, color: C.muted, marginBottom: 3 }}>{m.date}</div>
              <div style={{ fontSize: 12, color: C.accent, marginBottom: 3 }}><span style={{ fontWeight: 700 }}>質問：</span>{m.userQuestion}</div>
              <div style={{ fontSize: 12, color: C.text, whiteSpace: 'pre-wrap', lineHeight: 1.6, marginBottom: 3 }}>{m.aiAnswer}</div>
              {m.memo && (
                <div style={{ fontSize: 12, color: C.gold }}><span style={{ fontWeight: 700 }}>メモ：</span>{m.memo}</div>
              )}
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

// ============================================================
// FinanceTab
// ============================================================

function FinanceTab({ data, onFinanceComplete, onCaseStudyComplete, onExamComplete, onDrillComplete, onEssayComplete, onSaveApiKey, onSaveEssayHistory, onSignalComplete, onProcessComplete, onWritingComplete, onSaveAiQa, pendingProblem, onClearPending }) {
  const [view, setView]                   = useState('list');
  const [tabMode, setTabMode]             = useState('study');
  const [selectedCase, setSelectedCase]   = useState('case4');
  const [filterType, setFilterType]           = useState('all');
  const [filterDifficulty, setFilterDifficulty] = useState('all');
  const [activeProblem, setActiveProblem] = useState(null);
  const [currentStep, setCurrentStep]     = useState(0);
  const [selectedChoice, setSelectedChoice] = useState(null);
  const [showExplanation, setShowExplanation] = useState(false);
  const [stepResults, setStepResults]     = useState([]);
  const [solverDone, setSolverDone]       = useState(false);
  // 模擬試験
  const [examPhase, setExamPhase]         = useState('setup');
  const [examConfig, setExamConfig]       = useState({ cases: ['case1','case2','case3','case4'], perCase: 2, timeLimit: 80 });
  const [examProblems, setExamProblems]   = useState([]);
  const [examIdx, setExamIdx]             = useState(0);
  const [examAnswers, setExamAnswers]     = useState([]);
  const [examTimeLeft, setExamTimeLeft]   = useState(null);
  const [examChoice, setExamChoice]       = useState(null);
  const [examShowExp, setExamShowExp]     = useState(false);
  const examTimerRef = useRef(null);
  // テキストモード
  const [expandedTopic, setExpandedTopic] = useState(null);
  const [cardSession, setCardSession]     = useState(null);
  // 即トレ
  const [drillPhase, setDrillPhase]       = useState('setup');
  const [drillConfig, setDrillConfig]     = useState({ scope: 'weak', cases: ['case1','case2','case3','case4'] });
  const [drillQueue, setDrillQueue]       = useState([]);
  const [drillIdx, setDrillIdx]           = useState(0);
  const [drillScore, setDrillScore]       = useState({ correct: 0, total: 0, streak: 0 });
  const [drillChoice, setDrillChoice]     = useState(null);
  const [drillShowExp, setDrillShowExp]   = useState(false);
  // 論述
  const [essayProblem, setEssayProblem]   = useState(null);
  const [essayAnswer, setEssayAnswer]     = useState('');
  const [essayFeedback, setEssayFeedback] = useState(null);
  const [essayLoading, setEssayLoading]   = useState(false);
  const [essayApiInput, setEssayApiInput] = useState('');
  const [essayView, setEssayView]         = useState('list'); // 'list' | 'history'
  // シグナルワード演習
  const [sigPhase, setSigPhase]           = useState('menu');  // 'menu'|'quiz'|'result'
  const [sigMode, setSigMode]             = useState('quiz');  // 'quiz'|'attack'|'highlight'
  const [sigCases, setSigCases]           = useState(['case1','case2','case3']);
  const [sigQueue, setSigQueue]           = useState([]);
  const [sigIdx, setSigIdx]               = useState(0);
  const [sigChoice, setSigChoice]         = useState(null);
  const [sigScore, setSigScore]           = useState({ correct: 0, total: 0, streak: 0, maxStreak: 0 });
  const [sigResults, setSigResults]       = useState([]);
  const [sigTimeLeft, setSigTimeLeft]     = useState(null);
  const [sigKwPick, setSigKwPick]         = useState([]);   // 即答：選択中のキーワード
  const sigTimerRef = useRef(null);
  // プロセス演習
  const [procPhase, setProcPhase]         = useState('menu');   // 'menu'|'running'|'result'
  const [procCases, setProcCases]         = useState(['case1','case2','case3']);
  const [procQueue, setProcQueue]         = useState([]);
  const [procIdx, setProcIdx]             = useState(0);
  const [procStep, setProcStep]           = useState(1);        // 1..4
  const [procPick, setProcPick]           = useState(null);     // Step1/3: number, Step2: string[], Step4: string[]
  const [procRevealed, setProcRevealed]   = useState(false);
  const [procScore, setProcScore]         = useState({ correct: 0, total: 0, perfect: 0 });
  const [procResults, setProcResults]     = useState([]);       // [{ id, steps: [bool,bool,bool,bool] }]
  const [procStepFlags, setProcStepFlags] = useState([]);       // 現在の問題の各ステップ正誤
  const [procFreeInput, setProcFreeInput] = useState(false);
  const [procBlankIdx, setProcBlankIdx]   = useState(0);        // Step4 チップモードで次に埋める空欄
  // 写経（写し書き／記憶で書く）
  const [wrPhase, setWrPhase]   = useState('menu');   // 'menu'|'copy'|'recall'|'result'
  const [wrCases, setWrCases]   = useState(['case1','case2','case3']);
  const [wrProb, setWrProb]     = useState(null);
  const [wrText, setWrText]     = useState('');
  const [wrHint, setWrHint]     = useState(0);        // 0..3 開示済みヒント段階
  const [wrResult, setWrResult] = useState(null);
  // AIに質問
  const [aiQaContext, setAiQaContext]     = useState(null);

  function resetSolver() {
    setCurrentStep(0);
    setSelectedChoice(null);
    setShowExplanation(false);
    setStepResults([]);
    setSolverDone(false);
  }

  // pendingProblem から自動で問題を開く
  useEffect(() => {
    if (!pendingProblem) return;
    const allProblems = [...CASE_STUDY_PROBLEMS, ...FINANCE_PROBLEMS];
    const p = allProblems.find(x => x.id === pendingProblem);
    if (p) {
      setTabMode('study');
      if (p.case && p.case !== 'case4') setSelectedCase(p.case);
      else setSelectedCase('case4');
      startProblem(p);
    }
    onClearPending();
  }, [pendingProblem]); // eslint-disable-line

  async function gradeEssay() {
    if (!essayAnswer.trim() || !essayProblem) return;
    setEssayLoading(true);
    setEssayFeedback(null);
    const apiKey = data.geminiApiKey || '';
    const prompt = `あなたは中小企業診断士2次試験の採点者です。以下の問題と採点キーワードをもとに、受験者の答案を採点してください。

【問題】
${essayProblem.question}

【採点キーワード（これらが含まれているか確認）】
${essayProblem.keywords.join('、')}

【受験者の答案】
${essayAnswer}

必ず以下のJSON形式のみで回答してください。説明文やコードブロックは不要です:
{"score":7,"good":"良かった点のテキスト","improve":"改善点のテキスト","hint":"解答のポイントのテキスト"}
scoreは0〜10の整数。`;
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), 30000);
    try {
      const res = await fetch(
        `https://generativelanguage.googleapis.com/v1beta/models/gemini-2.5-flash:generateContent?key=${apiKey}`,
        {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ contents: [{ parts: [{ text: prompt }] }] }),
          signal: controller.signal,
        }
      );
      clearTimeout(timer);
      if (!res.ok) {
        const errText = await res.text().catch(() => '');
        const errBody = (() => { try { return JSON.parse(errText); } catch { return null; } })();
        const msg = errBody?.error?.message || `HTTP ${res.status}`;
        setEssayFeedback({ score: 0, good: '', improve: '', hint: `APIエラー: ${msg}` });
        setEssayLoading(false);
        return;
      }
      const json = await res.json();
      const text = json?.candidates?.[0]?.content?.parts?.[0]?.text || '';
      const match = text.match(/\{[\s\S]*?\}/);
      if (match) {
        try {
          const fb = JSON.parse(match[0]);
          setEssayFeedback(fb);
          onEssayComplete(fb.score || 0);
          onSaveEssayHistory({
            id: Date.now(),
            problemId: essayProblem.id,
            title: essayProblem.title,
            caseId: essayProblem.case,
            answer: essayAnswer,
            score: fb.score || 0,
            good: fb.good || '',
            improve: fb.improve || '',
            hint: fb.hint || '',
            date: new Date().toLocaleDateString('ja-JP', { month: 'numeric', day: 'numeric', hour: '2-digit', minute: '2-digit' }),
          });
        } catch {
          setEssayFeedback({ score: 0, good: '', improve: '', hint: `JSON解析エラー。Geminiの返答: ${text.slice(0, 200)}` });
        }
      } else {
        setEssayFeedback({ score: 0, good: '', improve: '', hint: `レスポンスを解析できませんでした。Geminiの返答: ${text.slice(0, 200)}` });
      }
    } catch (e) {
      clearTimeout(timer);
      const msg = e.name === 'AbortError' ? 'タイムアウト（30秒）しました。再度お試しください。' : `ネットワークエラー: ${e.message}`;
      setEssayFeedback({ score: 0, good: '', improve: '', hint: msg });
    }
    setEssayLoading(false);
  }

  function shuffleProblem(problem) {
    const steps = problem.steps.map(step => {
      const items = step.choices.map((c, i) => ({ c, isCorrect: i === step.correct }));
      for (let i = items.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        [items[i], items[j]] = [items[j], items[i]];
      }
      return { ...step, choices: items.map(x => x.c), correct: items.findIndex(x => x.isCorrect) };
    });
    return { ...problem, steps };
  }

  function startProblem(problem) {
    setActiveProblem(shuffleProblem(problem));
    resetSolver();
    setView('solver');
  }

  function handleChoiceSelect(idx) {
    if (selectedChoice !== null) return;
    setSelectedChoice(idx);
    setShowExplanation(true);
  }

  function handleNext() {
    const isCorrect = selectedChoice === activeProblem.steps[currentStep].correct;
    const newResults = [...stepResults, isCorrect];
    if (currentStep + 1 >= activeProblem.steps.length) {
      setStepResults(newResults);
      setSolverDone(true);
      if (activeProblem.case && activeProblem.case !== 'case4') {
        onCaseStudyComplete(activeProblem.id, newResults.filter(Boolean).length, activeProblem.steps.length);
      } else {
        onFinanceComplete(activeProblem.id, newResults.filter(Boolean).length, activeProblem.steps.length);
      }
    } else {
      setStepResults(newResults);
      setCurrentStep(s => s + 1);
      setSelectedChoice(null);
      setShowExplanation(false);
    }
  }

  function getProblemProgress(problemId, isCaseStudy) {
    const store = isCaseStudy ? data.caseProgress : data.financeProgress;
    return store?.[problemId] || { attempts: 0, bestCorrect: 0, completed: false };
  }

  // 模擬試験ヘルパー
  function shuffleArray(arr) {
    const a = [...arr];
    for (let i = a.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [a[i], a[j]] = [a[j], a[i]];
    }
    return a;
  }

  function buildExamProblems(config) {
    let problems = [];
    config.cases.forEach(caseId => {
      const pool = caseId === 'case4'
        ? FINANCE_PROBLEMS
        : CASE_STUDY_PROBLEMS.filter(p => p.case === caseId);
      const n = config.perCase === 'all' ? pool.length : Math.min(config.perCase, pool.length);
      shuffleArray(pool).slice(0, n).forEach(p => problems.push(shuffleProblem(p)));
    });
    return problems;
  }

  function buildDrillQueue(config) {
    const allProbs = config.cases.flatMap(caseId =>
      caseId === 'case4'
        ? FINANCE_PROBLEMS
        : CASE_STUDY_PROBLEMS.filter(p => p.case === caseId)
    );
    const store = { ...data.caseProgress, ...data.financeProgress };
    const weak = allProbs.filter(p => {
      const prog = store[p.id];
      return prog && prog.attempts > 0 && prog.bestCorrect < p.steps.length;
    });
    const pool = (config.scope === 'weak' && weak.length > 0) ? weak : allProbs;
    const items = pool.flatMap(p =>
      p.steps.map((step, stepIdx) => ({ problem: p, step, stepIdx }))
    );
    return shuffleArray(items).slice(0, 10);
  }

  function startDrill() {
    const queue = buildDrillQueue(drillConfig);
    setDrillQueue(queue);
    setDrillIdx(0);
    setDrillScore({ correct: 0, total: 0, streak: 0 });
    setDrillChoice(null);
    setDrillShowExp(false);
    setDrillPhase('drilling');
  }

  function handleDrillAnswer(choiceIdx) {
    if (drillChoice !== null) return;
    const item = drillQueue[drillIdx];
    const isCorrect = choiceIdx === item.step.correct;
    const newStreak = isCorrect ? drillScore.streak + 1 : 0;
    setDrillScore(s => ({ correct: s.correct + (isCorrect ? 1 : 0), total: s.total + 1, streak: newStreak }));
    setDrillChoice(choiceIdx);
    setDrillShowExp(true);
  }

  function nextDrillQuestion() {
    if (drillScore.streak >= 3) { setDrillPhase('clear'); return; }
    if (drillIdx + 1 >= drillQueue.length) { setDrillPhase('result'); return; }
    setDrillIdx(i => i + 1);
    setDrillChoice(null);
    setDrillShowExp(false);
  }

  // ===== シグナルワード演習 =====

  // 出題キューを生成。quiz/attack は4択、highlight は与件文タップ
  function buildSignalQueue(mode, cases) {
    const pool = SIGNAL_WORDS.filter(w => cases.includes(w.case));
    if (pool.length === 0) return [];
    const shuffled = shuffleArray(pool);
    // 即答は10問、タイムアタックとハイライトは時間/全問尽きるまで回すので多めに
    const count = mode === 'quiz' ? Math.min(10, shuffled.length) : shuffled.length;

    // 全シグナルの解答キーワードを語単位で集めておく（即答の誤答肢の母集団）
    const allKw = [...new Set(SIGNAL_WORDS.flatMap(x => x.direction.split('・')))];

    return shuffled.slice(0, count).map(w => {
      if (mode === 'highlight') return { word: w, choices: null, correct: w.answerIdx };

      if (mode === 'quiz') {
        // 即答＝キーワード群から関連する語をすべて選ぶ形式
        const kwAnswer = w.direction.split('・');
        // 正解語と同義グループの語は誤答にしない（実質同じなのに不正解を防ぐ）
        const banned = new Set(kwAnswer.map(SIGNAL_KW_KEY));
        const distractors = shuffleArray(allKw.filter(k => !banned.has(SIGNAL_KW_KEY(k))))
          .slice(0, Math.max(4, 9 - kwAnswer.length));
        return { word: w, choices: null, kwAnswer, kwPool: shuffleArray([...kwAnswer, ...distractors]) };
      }

      // タイムアタックは4択のまま。ただし正解と語が2つ以上かぶる方向性は誤答にしない
      const ansKeys = new Set(w.direction.split('・').map(SIGNAL_KW_KEY));
      const overlap = x => x.direction.split('・').filter(k => ansKeys.has(SIGNAL_KW_KEY(k))).length;
      let cands = pool.filter(x => x.id !== w.id && overlap(x) < 2);
      if (cands.length < 3) cands = SIGNAL_WORDS.filter(x => x.id !== w.id && overlap(x) < 2);
      const distractors = shuffleArray(cands).slice(0, 3).map(x => x.direction);
      const choices = shuffleArray([w.direction, ...distractors]);
      return { word: w, choices, correct: choices.indexOf(w.direction) };
    });
  }

  function startSignal(mode) {
    const queue = buildSignalQueue(mode, sigCases);
    if (queue.length === 0) return;
    if (sigTimerRef.current) clearInterval(sigTimerRef.current);
    setSigMode(mode);
    setSigQueue(queue);
    setSigIdx(0);
    setSigChoice(null);
    setSigKwPick([]);
    setSigScore({ correct: 0, total: 0, streak: 0, maxStreak: 0 });
    setSigResults([]);
    setSigPhase('quiz');
    if (mode === 'attack') {
      setSigTimeLeft(60);
      sigTimerRef.current = setInterval(() => {
        setSigTimeLeft(t => {
          if (t <= 1) { clearInterval(sigTimerRef.current); finishSignal(); return 0; }
          return t - 1;
        });
      }, 1000);
    } else {
      setSigTimeLeft(null);
    }
  }

  function finishSignal() {
    if (sigTimerRef.current) clearInterval(sigTimerRef.current);
    setSigPhase('result');
  }

  // 採点結果をスコアに反映する（即答・タイムアタック・ハイライト共通）
  function recordSignalResult(item, ok) {
    const streak = ok ? sigScore.streak + 1 : 0;
    setSigScore(s => ({
      correct: s.correct + (ok ? 1 : 0),
      total: s.total + 1,
      streak,
      maxStreak: Math.max(s.maxStreak, streak),
    }));
    setSigResults(r => [...r, { id: item.word.id, ok }]);
  }

  function handleSignalAnswer(choiceIdx) {
    if (sigChoice !== null) return;
    const item = sigQueue[sigIdx];
    const ok = choiceIdx === item.correct;
    setSigChoice(choiceIdx);
    recordSignalResult(item, ok);
    // タイムアタックはテンポ重視で自動送り
    if (sigMode === 'attack') setTimeout(() => nextSignal(), ok ? 450 : 900);
  }

  // 即答：選んだキーワード集合が正解と完全一致で正解
  function submitSignalKeywords() {
    if (sigChoice !== null) return;
    const item = sigQueue[sigIdx];
    const a = [...sigKwPick].sort();
    const b = [...item.kwAnswer].sort();
    const ok = a.length === b.length && a.every((x, i) => x === b[i]);
    setSigChoice(ok ? 1 : 0);   // 回答済みフラグ代わり
    recordSignalResult(item, ok);
  }

  function nextSignal() {
    if (sigIdx + 1 >= sigQueue.length) { finishSignal(); return; }
    setSigIdx(i => i + 1);
    setSigChoice(null);
    setSigKwPick([]);
  }

  // タイマーのクリーンアップ
  useEffect(() => () => { if (sigTimerRef.current) clearInterval(sigTimerRef.current); }, []);

  // ===== プロセス演習（4ステップ連鎖） =====

  // 未完答（bestSteps < 4）を優先し、1セッション PROC_SESSION_SIZE 問に絞る
  function buildProcessQueue(cases) {
    const pool = PROCESS_PROBLEMS.filter(p => cases.includes(p.case));
    const prog = data.processProgress || {};
    const unfinished = pool.filter(p => (prog[p.id]?.bestSteps || 0) < PROC_STEP_COUNT);
    const finished   = pool.filter(p => (prog[p.id]?.bestSteps || 0) >= PROC_STEP_COUNT);
    const ordered = [...shuffleArray(unfinished), ...shuffleArray(finished)];
    return ordered.slice(0, PROC_SESSION_SIZE).map(p => {
      // Step4 解答の型：正解＋他の型3つをシャッフル
      const wrong = shuffleArray(ANSWER_PATTERNS.filter(x => x.id !== p.patternAnswer)).slice(0, 3);
      const patternChoices = shuffleArray([ANSWER_PATTERNS.find(x => x.id === p.patternAnswer), ...wrong]);

      // Step3 使い分け：選ばなかった誤答キーワードから1語を選び、その使い所を問う
      const distractors = p.keywordPool.filter(k => !p.keywordAnswer.includes(k) && KEYWORD_USAGE[k]);
      const usageTarget = distractors[Math.floor(Math.random() * distractors.length)];
      const others = shuffleArray(Object.keys(KEYWORD_USAGE).filter(k => k !== usageTarget && KEYWORD_USAGE[k] !== KEYWORD_USAGE[usageTarget])).slice(0, 3);
      const usageChoices = shuffleArray([KEYWORD_USAGE[usageTarget], ...others.map(k => KEYWORD_USAGE[k])]);

      return {
        prob: p,
        patternChoices,
        patternCorrect: patternChoices.findIndex(x => x.id === p.patternAnswer),
        usageTarget,
        usageChoices,
        usageCorrect: usageChoices.indexOf(KEYWORD_USAGE[usageTarget]),
        // データ上は正解が先頭に並んでいるため、出題時に必ずシャッフルする
        kwPool:    shuffleArray(p.keywordPool),
        blankPool: shuffleArray(p.blankPool),
      };
    });
  }

  function startProcess() {
    const queue = buildProcessQueue(procCases);
    if (queue.length === 0) return;
    setProcQueue(queue);
    setProcIdx(0);
    setProcStep(1);
    setProcPick(null);
    setProcRevealed(false);
    setProcScore({ correct: 0, total: 0, perfect: 0 });
    setProcResults([]);
    setProcStepFlags([]);
    setProcBlankIdx(0);
    setProcPhase('running');
  }

  // 現在のステップの正誤を判定する
  function judgeProcStep(item, step, pick) {
    const p = item.prob;
    if (step === 1) return pick === p.issueIdx;
    if (step === 2) {
      const a = [...(pick || [])].sort();
      const b = [...p.keywordAnswer].sort();
      return a.length === b.length && a.every((x, i) => x === b[i]);
    }
    if (step === 3) return pick === item.usageCorrect;
    if (step === 4) return pick === item.patternCorrect;
    // step 5: 全空欄が順序どおり一致
    return p.blanks.every((ans, i) => (pick?.[i] || '').trim() === ans);
  }

  // 回答を確定して正誤を表示する
  function revealProcStep() {
    if (procRevealed) return;
    const item = procQueue[procIdx];
    const ok = judgeProcStep(item, procStep, procPick);
    setProcStepFlags(f => [...f, ok]);
    setProcScore(s => ({ ...s, correct: s.correct + (ok ? 1 : 0), total: s.total + 1 }));
    setProcRevealed(true);
  }

  // 次のステップ、または次の問題へ
  function nextProcStep() {
    const item = procQueue[procIdx];
    if (procStep < PROC_STEP_COUNT) {
      setProcStep(s => s + 1);
      setProcPick(null);
      setProcRevealed(false);
      setProcBlankIdx(0);
      return;
    }
    // 1問完了
    const flags = procStepFlags;
    const allOk = flags.length === PROC_STEP_COUNT && flags.every(Boolean);
    setProcResults(r => [...r, { id: item.prob.id, steps: flags }]);
    if (allOk) setProcScore(s => ({ ...s, perfect: s.perfect + 1 }));
    if (procIdx + 1 >= procQueue.length) { setProcPhase('result'); return; }
    setProcIdx(i => i + 1);
    setProcStep(1);
    setProcPick(null);
    setProcRevealed(false);
    setProcStepFlags([]);
    setProcBlankIdx(0);
  }

  // ===== 写経（写し書き／記憶で書く） =====

  // 実施回数の少ない問題を優先して1問選ぶ
  function pickWritingProb(mode) {
    const pool = PROCESS_PROBLEMS.filter(p => wrCases.includes(p.case));
    if (pool.length === 0) return null;
    const prog = data.writingProgress || {};
    const cnt = p => (prog[p.id]?.[mode === 'copy' ? 'copied' : 'recalled'] || 0);
    const min = Math.min(...pool.map(cnt));
    return shuffleArray(pool.filter(p => cnt(p) === min))[0];
  }

  function startWriting(mode) {
    const p = pickWritingProb(mode);
    if (!p) return;
    setWrProb(p);
    setWrText('');
    setWrHint(0);
    setWrResult(null);
    setWrPhase(mode);
  }

  function finishCopy() {
    if (!wrProb) return;
    const ratio = Math.round(lcsLength(wrText.trim(), wrProb.modelAnswer) / wrProb.modelAnswer.length * 100);
    setWrResult({ mode: 'copy', ratio, len: wrText.trim().length, target: wrProb.modelAnswer.length });
    setWrPhase('result');
  }

  function gradeRecall() {
    if (!wrProb) return;
    const g = gradeRecallText(wrProb, wrText);
    setWrResult({ mode: 'recall', ...g, hintsUsed: wrHint });
    setWrPhase('result');
  }

  // 途中終了：現在の問題までの結果で結果画面へ
  function abortProcess() {
    const item = procQueue[procIdx];
    if (item && procStepFlags.length > 0) {
      setProcResults(r => [...r, { id: item.prob.id, steps: procStepFlags }]);
      if (procStepFlags.length === PROC_STEP_COUNT && procStepFlags.every(Boolean)) {
        setProcScore(s => ({ ...s, perfect: s.perfect + 1 }));
      }
    }
    setProcPhase('result');
  }

  function startExam() {
    const problems = buildExamProblems(examConfig);
    setExamProblems(problems);
    setExamIdx(0);
    setExamAnswers([]);
    setExamChoice(null);
    setExamShowExp(false);
    setExamTimeLeft(examConfig.timeLimit ? examConfig.timeLimit * 60 : null);
    setExamPhase('solving');
  }

  function finishExam(answers) {
    if (examTimerRef.current) clearInterval(examTimerRef.current);
    setExamAnswers(answers);
    setExamPhase('result');
    onExamComplete(answers.filter(Boolean).length);
  }

  function handleExamChoice(idx) {
    if (examChoice !== null) return;
    setExamChoice(idx);
    setExamShowExp(true);
  }

  function handleExamNext() {
    const step = examProblems[examIdx]?.steps[0]; // single-step for exam
    const isCorrect = examChoice === examProblems[examIdx].steps[0].correct;
    const newAnswers = [...examAnswers, isCorrect];
    if (examIdx + 1 >= examProblems.length) {
      finishExam(newAnswers);
    } else {
      setExamAnswers(newAnswers);
      setExamIdx(i => i + 1);
      setExamChoice(null);
      setExamShowExp(false);
    }
  }

  // タイマー
  useEffect(() => {
    if (examPhase !== 'solving' || examTimeLeft === null) return;
    if (examTimeLeft <= 0) {
      // タイムアップ: 残り問題を不正解として終了
      const remaining = examProblems.length - examAnswers.length;
      finishExam([...examAnswers, ...Array(remaining).fill(false)]);
      return;
    }
    examTimerRef.current = setInterval(() => setExamTimeLeft(t => t - 1), 1000);
    return () => clearInterval(examTimerRef.current);
  }, [examPhase, examTimeLeft]); // eslint-disable-line

  const filterTypes = [
    { id: 'all', label: 'すべて' },
    { id: 'cvp', label: 'CVP分析' },
    { id: 'npv', label: 'NPV分析' },
    { id: 'ratio', label: '財務比率' },
    { id: 'cashflow', label: 'CF計算' },
  ];
  const caseSelectors = [
    { id: 'case1', label: '事例I', sub: '人事・組織' },
    { id: 'case2', label: '事例II', sub: 'マーケ' },
    { id: 'case3', label: '事例III', sub: '生産' },
    { id: 'case4', label: '事例IV', sub: '財務' },
  ];
  const caseTitles = {
    case1: '事例I 人事・組織', case2: '事例II マーケティング',
    case3: '事例III 生産・技術', case4: '事例IV 財務計算',
  };
  const isCaseStudy = selectedCase !== 'case4';
  const sourceProblems = isCaseStudy
    ? CASE_STUDY_PROBLEMS.filter(p => p.case === selectedCase)
    : FINANCE_PROBLEMS;
  const filtered = sourceProblems.filter(p => {
    if (!isCaseStudy && filterType !== 'all' && p.type !== filterType) return false;
    const diffOk = filterDifficulty === 'all' || (p.difficulty || '基礎') === filterDifficulty;
    return diffOk;
  });

  // ---- List view ----
  if (view === 'list') {
    return (
      <div style={{ padding: '16px 16px 80px' }}>
        {/* Mode toggle */}
        <div style={{ display: 'flex', gap: 8, marginBottom: 16, flexWrap: 'nowrap', overflowX: 'auto', paddingBottom: 4 }}>
          {[
            { id: 'study', label: '✍️ 演習' },
            { id: 'textbook', label: '📖 テキスト' },
            { id: 'analysis', label: '📊 分析' },
            { id: 'exam', label: '🎯 模擬試験' },
            { id: 'drill', label: '⚡ 即トレ' },
            { id: 'signal', label: '🚦 シグナル' },
            { id: 'process', label: '🎯 プロセス' },
            { id: 'writing', label: '✍️ 写経' },
            { id: 'essay', label: '📝 論述' },
          ].map(m => (
            <button
              key={m.id}
              onClick={() => { setTabMode(m.id); setCardSession(null); setExpandedTopic(null); setSigPhase('menu'); setProcPhase('menu'); setWrPhase('menu'); }}
              style={{
                padding: '8px 14px', borderRadius: 20, border: 'none', flexShrink: 0,
                background: tabMode === m.id ? C.accent : C.card,
                color: tabMode === m.id ? '#000' : C.muted,
                fontWeight: tabMode === m.id ? 700 : 400,
                cursor: 'pointer', fontSize: 13,
              }}
            >{m.label}</button>
          ))}
        </div>

        {/* ===== 弱点分析 ===== */}
        {tabMode === 'analysis' && (() => {
          const analysisCase = selectedCase;
          const isCsAnalysis = analysisCase !== 'case4';
          const pool = isCsAnalysis
            ? CASE_STUDY_PROBLEMS.filter(p => p.case === analysisCase)
            : FINANCE_PROBLEMS;
          const typeLabels = isCsAnalysis ? CASE_TYPE_LABELS : FINANCE_TYPE_LABELS;
          const typeColors = isCsAnalysis ? CASE_TYPE_COLORS : FINANCE_TYPE_COLORS;
          const store = isCsAnalysis ? data.caseProgress : data.financeProgress;

          // 型ごとに集計
          const byType = {};
          pool.forEach(p => {
            if (!byType[p.type]) byType[p.type] = { total: 0, sumRate: 0, attempted: 0 };
            byType[p.type].total++;
            const prog = store?.[p.id];
            if (prog && prog.attempts > 0) {
              byType[p.type].sumRate += prog.bestCorrect / p.steps.length;
              byType[p.type].attempted++;
            }
          });

          const rows = Object.entries(byType).map(([type, v]) => ({
            type,
            label: typeLabels[type] || type,
            color: typeColors[type] || C.muted,
            attempted: v.attempted,
            total: v.total,
            rate: v.attempted > 0 ? v.sumRate / v.total : null,
          })).sort((a, b) => {
            if (a.rate === null && b.rate === null) return 0;
            if (a.rate === null) return -1;
            if (b.rate === null) return 1;
            return a.rate - b.rate;
          });

          return (
            <div>
              <div style={{ display: 'flex', gap: 6, marginBottom: 14, flexWrap: 'wrap' }}>
                {caseSelectors.map(cs => (
                  <button
                    key={cs.id}
                    onClick={() => setSelectedCase(cs.id)}
                    style={{
                      padding: '6px 12px', borderRadius: 20, border: 'none',
                      background: selectedCase === cs.id ? C.purple : C.card,
                      color: selectedCase === cs.id ? '#fff' : C.muted,
                      fontWeight: selectedCase === cs.id ? 700 : 400,
                      cursor: 'pointer', fontSize: 12,
                    }}
                  >{cs.label} <span style={{ fontSize: 10, opacity: 0.75 }}>{cs.sub}</span></button>
                ))}
              </div>
              <div style={{ fontSize: 13, color: C.muted, marginBottom: 12 }}>苦手な分野が上に表示されます</div>
              <div style={{ display: 'flex', flexDirection: 'column', gap: 10 }}>
                {rows.map(r => {
                  const pct = r.rate !== null ? Math.round(r.rate * 100) : null;
                  const barColor = pct === null ? '#334155' : pct < 50 ? C.red : pct < 80 ? '#f59e0b' : C.green;
                  return (
                    <div key={r.type} style={{ background: C.card, borderRadius: 12, padding: '12px 14px' }}>
                      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 6 }}>
                        <span style={{ fontSize: 13, fontWeight: 600, color: r.color }}>{r.label}</span>
                        <span style={{ fontSize: 12, color: pct === null ? C.muted : barColor, fontWeight: 700 }}>
                          {pct === null ? '未挑戦' : `${pct}%`}
                        </span>
                      </div>
                      <div style={{ height: 6, background: '#1e293b', borderRadius: 3, overflow: 'hidden' }}>
                        <div style={{
                          height: '100%', width: `${pct ?? 0}%`,
                          background: barColor, borderRadius: 3, transition: 'width 0.5s ease',
                        }} />
                      </div>
                      <div style={{ fontSize: 11, color: C.muted, marginTop: 4 }}>
                        {r.attempted}/{r.total}問 挑戦済み
                      </div>
                    </div>
                  );
                })}
              </div>
            </div>
          );
        })()}

        {/* ===== シグナルワード演習 ===== */}
        {tabMode === 'signal' && (() => {
          const caseLabelsSig = { case1: '事例I', case2: '事例II', case3: '事例III' };
          const caseColorsSig = { case1: '#7c3aed', case2: '#0ea5e9', case3: '#f59e0b' };
          const mastery = data.signalMastery || {};
          const best = data.signalBest || {};

          // ---- 結果画面 ----
          if (sigPhase === 'result') {
            const pct = sigScore.total > 0 ? Math.round(sigScore.correct / sigScore.total * 100) : 0;
            const modeLabel = sigMode === 'attack' ? '60秒タイムアタック' : sigMode === 'highlight' ? '与件文ハイライト' : 'シグナル即答';
            const prevBest = best[sigMode] || 0;
            const isRecord = (sigMode === 'attack' || sigMode === 'highlight') && sigScore.correct > prevBest;
            const bonus = sigScore.maxStreak >= 5 ? 20 : 0;
            const gainXp = sigScore.correct * 3 + bonus;
            const missed = sigResults.filter(r => !r.ok)
              .map(r => SIGNAL_WORDS.find(w => w.id === r.id)).filter(Boolean);

            return (
              <div style={{ padding: '16px 0' }}>
                <div style={{ textAlign: 'center', marginBottom: 20 }}>
                  <div style={{ fontSize: 44, marginBottom: 8 }}>{isRecord ? '🏆' : pct >= 80 ? '🎉' : '🚦'}</div>
                  {isRecord && (
                    <div style={{ fontSize: 15, fontWeight: 700, color: C.gold, marginBottom: 6 }}>
                      自己ベスト更新！（前回 {prevBest}問）
                    </div>
                  )}
                  <div style={{ fontSize: 17, fontWeight: 700, color: C.text, marginBottom: 8 }}>{modeLabel} 完了</div>
                  <div style={{ fontSize: 38, fontWeight: 700, color: C.accent }}>
                    {sigScore.correct} / {sigScore.total}
                  </div>
                  <div style={{ fontSize: 14, color: pct >= 80 ? C.green : pct >= 50 ? '#f59e0b' : C.red, fontWeight: 700, marginBottom: 6 }}>
                    正解率 {pct}%
                  </div>
                  {sigScore.maxStreak >= 2 && (
                    <div style={{ fontSize: 13, color: C.gold, marginBottom: 4 }}>🔥 最大 {sigScore.maxStreak} 連続</div>
                  )}
                  <div style={{ fontSize: 13, color: C.muted }}>
                    ＋{gainXp} XP{bonus > 0 ? `（連続ボーナス +${bonus}）` : ''}
                  </div>
                </div>

                {missed.length > 0 && (
                  <div style={{ marginBottom: 20 }}>
                    <div style={{ fontSize: 12, color: C.red, fontWeight: 700, marginBottom: 8 }}>
                      ✗ 間違えたシグナル（{missed.length}件）
                    </div>
                    {missed.map(w => (
                      <div key={w.id} style={{
                        background: C.card, border: `1px solid ${C.red}33`,
                        borderRadius: 10, padding: '10px 12px', marginBottom: 6,
                      }}>
                        <div style={{ fontSize: 13, color: C.text, fontWeight: 600, marginBottom: 4 }}>{w.signal}</div>
                        <div style={{ fontSize: 12, color: C.green, lineHeight: 1.5 }}>→ {w.direction}</div>
                      </div>
                    ))}
                  </div>
                )}

                <div style={{ display: 'flex', gap: 10 }}>
                  <button onClick={() => { onSignalComplete({ mode: sigMode, correct: sigScore.correct, total: sigScore.total, maxStreak: sigScore.maxStreak, results: sigResults }); startSignal(sigMode); }}
                    style={{
                      flex: 1, padding: '14px', borderRadius: 12, border: `1px solid ${C.accent}`,
                      background: 'transparent', color: C.accent, fontWeight: 700, cursor: 'pointer', fontSize: 14,
                    }}>🔁 もう一度</button>
                  <button onClick={() => { onSignalComplete({ mode: sigMode, correct: sigScore.correct, total: sigScore.total, maxStreak: sigScore.maxStreak, results: sigResults }); setSigPhase('menu'); }}
                    style={{
                      flex: 1, padding: '14px', borderRadius: 12, border: 'none',
                      background: C.accent, color: '#000', fontWeight: 700, cursor: 'pointer', fontSize: 14,
                    }}>結果を記録して終了</button>
                </div>
              </div>
            );
          }

          // ---- 出題中 ----
          if (sigPhase === 'quiz' && sigQueue.length > 0) {
            const item = sigQueue[sigIdx];
            const w = item.word;
            const answered = sigChoice !== null;
            // 即答はキーワード集合の一致で判定済み（sigChoice に 1/0 を格納）
            const isCorrect = answered && (sigMode === 'quiz' ? sigChoice === 1 : sigChoice === item.correct);

            return (
              <div>
                {/* ヘッダー：進捗・連続・残り時間 */}
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 14 }}>
                  <button onClick={finishSignal}
                    style={{ background: 'none', border: 'none', color: C.muted, cursor: 'pointer', fontSize: 12 }}>終了</button>
                  {sigMode === 'attack' ? (
                    <div style={{
                      fontSize: 22, fontWeight: 700, fontFamily: 'monospace',
                      color: sigTimeLeft <= 10 ? C.red : sigTimeLeft <= 30 ? C.orange : C.accent,
                    }}>{sigTimeLeft}s</div>
                  ) : (
                    <div style={{ fontSize: 13, color: C.muted }}>{sigIdx + 1} / {sigQueue.length}問</div>
                  )}
                  <div style={{ fontSize: 12, color: C.gold, fontWeight: 700, minWidth: 60, textAlign: 'right' }}>
                    {sigScore.streak >= 2 ? `🔥${sigScore.streak}` : ''}
                  </div>
                </div>

                {/* コンボゲージ */}
                {sigScore.streak >= 1 && (
                  <div style={{ height: 3, background: C.border, borderRadius: 2, marginBottom: 14, overflow: 'hidden' }}>
                    <div style={{
                      height: '100%', width: `${Math.min(sigScore.streak / 5, 1) * 100}%`,
                      background: `linear-gradient(90deg, ${C.orange}, ${C.gold})`, transition: 'width 0.3s',
                    }} />
                  </div>
                )}

                <div style={{ fontSize: 11, color: caseColorsSig[w.case], fontWeight: 700, marginBottom: 8 }}>
                  {caseLabelsSig[w.case]}
                </div>

                {/* --- ハイライト演習：与件文から該当箇所をタップ --- */}
                {sigMode === 'highlight' ? (
                  <>
                    <div style={{ fontSize: 12, color: C.muted, marginBottom: 10 }}>
                      次の与件文から「課題を示すシグナル」をタップして選べ
                    </div>
                    <div style={{
                      background: C.card, border: `1px solid ${C.border}`, borderRadius: 12,
                      padding: '16px 14px', marginBottom: 14, lineHeight: 2.2,
                    }}>
                      {w.segments.map((seg, i) => {
                        let bg = 'transparent', color = C.text, border = 'transparent';
                        if (answered) {
                          if (i === item.correct) { bg = `${C.green}25`; color = C.green; border = C.green; }
                          else if (i === sigChoice) { bg = `${C.red}25`; color = C.red; border = C.red; }
                          else { color = C.muted; }
                        }
                        return (
                          <span key={i} onClick={() => handleSignalAnswer(i)}
                            style={{
                              background: bg, color, borderBottom: `2px solid ${border}`,
                              padding: '3px 2px', borderRadius: 4,
                              cursor: answered ? 'default' : 'pointer', fontSize: 14,
                              transition: 'all 0.2s',
                            }}>{seg}</span>
                        );
                      })}
                    </div>
                  </>
                ) : (
                  <>
                    {/* --- 即答／タイムアタック：シグナル→方向性の4択 --- */}
                    <div style={{
                      background: `linear-gradient(135deg, ${C.card}, #0d1a2e)`,
                      border: `1px solid ${caseColorsSig[w.case]}44`,
                      borderRadius: 14, padding: '20px 16px', marginBottom: 14, textAlign: 'center',
                    }}>
                      <div style={{ fontSize: 11, color: C.muted, marginBottom: 6 }}>与件文のシグナル</div>
                      <div style={{ fontSize: 16, fontWeight: 700, color: C.text, lineHeight: 1.6 }}>{w.signal}</div>
                    </div>
                    {sigMode === 'quiz' ? (
                      <>
                        {/* 即答：関連するキーワードをすべて選ぶ */}
                        <div style={{ fontSize: 11, color: C.muted, marginBottom: 8 }}>
                          解答に使うキーワードをすべて選べ（{item.kwAnswer.length}個）
                        </div>
                        <div style={{ display: 'flex', flexWrap: 'wrap', gap: 8, marginBottom: 14 }}>
                          {item.kwPool.map(kw => {
                            const sel = sigKwPick.includes(kw);
                            const isAns = item.kwAnswer.includes(kw);
                            let bg = C.card, bd = C.border, color = C.text;
                            if (answered) {
                              if (isAns) { bg = `${C.green}22`; bd = C.green; color = C.green; }
                              else if (sel) { bg = `${C.red}22`; bd = C.red; color = C.red; }
                              else color = C.muted;
                            } else if (sel) { bg = `${C.accent}22`; bd = C.accent; color = C.accent; }
                            return (
                              <button key={kw} disabled={answered}
                                onClick={() => setSigKwPick(cur =>
                                  cur.includes(kw) ? cur.filter(x => x !== kw) : [...cur, kw])}
                                style={{
                                  background: bg, border: `1px solid ${bd}`, color, borderRadius: 20,
                                  padding: '8px 14px', fontSize: 13, cursor: answered ? 'default' : 'pointer',
                                  fontWeight: sel || (answered && isAns) ? 700 : 400, transition: 'all 0.15s',
                                }}>{kw}</button>
                            );
                          })}
                        </div>
                        {!answered && (
                          <button onClick={submitSignalKeywords} disabled={sigKwPick.length === 0}
                            style={{
                              width: '100%', padding: '14px', borderRadius: 12, border: 'none',
                              background: sigKwPick.length > 0 ? C.accent : C.card,
                              color: sigKwPick.length > 0 ? '#000' : C.muted,
                              fontWeight: 700, cursor: sigKwPick.length > 0 ? 'pointer' : 'default',
                              fontSize: 15, marginBottom: 12,
                            }}>決定（{sigKwPick.length}個選択中）</button>
                        )}
                      </>
                    ) : (
                      <>
                        {/* タイムアタック：方向性の4択 */}
                        <div style={{ fontSize: 11, color: C.muted, marginBottom: 8 }}>解答の方向性は？</div>
                        <div style={{ display: 'flex', flexDirection: 'column', gap: 8, marginBottom: 12 }}>
                          {item.choices.map((choice, idx) => {
                            let bg = C.card, border = C.border, color = C.text;
                            if (answered) {
                              if (idx === item.correct) { bg = `${C.green}22`; border = C.green; color = C.green; }
                              else if (idx === sigChoice) { bg = `${C.red}22`; border = C.red; color = C.red; }
                              else { color = C.muted; }
                            }
                            return (
                              <button key={idx} onClick={() => handleSignalAnswer(idx)} disabled={answered}
                                style={{
                                  background: bg, border: `1px solid ${border}`, borderRadius: 10,
                                  padding: '13px 14px', color, textAlign: 'left',
                                  cursor: answered ? 'default' : 'pointer', fontSize: 13, lineHeight: 1.5,
                                  fontWeight: answered && idx === item.correct ? 700 : 400,
                                  transition: 'all 0.2s',
                                }}>{choice}</button>
                            );
                          })}
                        </div>
                      </>
                    )}
                  </>
                )}

                {/* 正誤フィードバック（タイムアタックは自動送りなので簡略表示） */}
                {answered && sigMode !== 'attack' && (
                  <>
                    <div style={{
                      background: isCorrect ? `${C.green}11` : `${C.red}11`,
                      border: `1px solid ${isCorrect ? C.green : C.red}44`,
                      borderRadius: 10, padding: 12, marginBottom: 12,
                    }}>
                      <div style={{ fontSize: 12, fontWeight: 700, color: isCorrect ? C.green : C.red, marginBottom: 6 }}>
                        {isCorrect ? '✓ 正解' : '✗ 不正解'}
                      </div>
                      <div style={{ fontSize: 12, color: C.muted, marginBottom: 3 }}>{w.signal}</div>
                      <div style={{ fontSize: 13, color: C.text, lineHeight: 1.6 }}>→ {w.direction}</div>
                    </div>
                    <PastQaPanel refId={w.id} history={data.aiQaHistory} />
                    <button
                      onClick={() => setAiQaContext({
                        source: 'シグナル',
                        refId: w.id,
                        wasCorrect: isCorrect,
                        questionText: `与件文シグナル: ${w.signal}`,
                        myAnswer:
                          sigMode === 'quiz' ? sigKwPick.join('・')
                          : item.choices ? item.choices[sigChoice]
                          : (w.segments?.[sigChoice] ?? ''),
                        correctAnswer: w.direction,
                        explanation: '',
                      })}
                      style={{
                        background: C.purple + '22', border: `1px solid ${C.purple}44`,
                        color: C.purple, borderRadius: 10, width: '100%',
                        padding: 10, fontSize: 13, marginBottom: 10, cursor: 'pointer',
                      }}
                    >🤖 AIに質問</button>
                    <button onClick={nextSignal} style={{
                      width: '100%', padding: '14px', borderRadius: 12, border: 'none',
                      background: C.accent, color: '#000', fontWeight: 700, cursor: 'pointer', fontSize: 15,
                    }}>{sigIdx + 1 >= sigQueue.length ? '結果を見る' : '次へ →'}</button>
                  </>
                )}
                {answered && sigMode === 'attack' && (
                  <div style={{ textAlign: 'center', fontSize: 14, fontWeight: 700, color: isCorrect ? C.green : C.red }}>
                    {isCorrect ? '✓ 正解！' : `✗ 正解： ${w.direction}`}
                  </div>
                )}
              </div>
            );
          }

          // ---- メニュー ----
          const poolSize = SIGNAL_WORDS.filter(x => sigCases.includes(x.case)).length;
          const masteredCount = SIGNAL_WORDS.filter(x => getSignalStars(mastery[x.id]) >= 3).length;

          return (
            <div>
              <div style={{ fontSize: 18, fontWeight: 700, color: C.text, marginBottom: 2 }}>🚦 シグナルワード演習</div>
              <div style={{ fontSize: 13, color: C.muted, marginBottom: 16 }}>
                与件文の表現 → 解答の方向性を反射で出せるようにする
              </div>

              {/* マスター進捗 */}
              <div style={{
                background: C.card, borderRadius: 12, padding: '14px 16px', marginBottom: 16,
                border: `1px solid ${C.border}`,
              }}>
                <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: 8 }}>
                  <span style={{ fontSize: 12, color: C.muted }}>マスター済み（★★★）</span>
                  <span style={{ fontSize: 13, fontWeight: 700, color: C.gold }}>
                    {masteredCount} / {SIGNAL_WORDS.length}
                  </span>
                </div>
                <div style={{ height: 6, background: C.bg, borderRadius: 3, overflow: 'hidden' }}>
                  <div style={{
                    height: '100%', width: `${(masteredCount / SIGNAL_WORDS.length) * 100}%`,
                    background: `linear-gradient(90deg, ${C.orange}, ${C.gold})`, transition: 'width 0.4s',
                  }} />
                </div>
              </div>

              {/* 事例フィルタ */}
              <div style={{ fontSize: 12, color: C.muted, marginBottom: 8 }}>出題範囲</div>
              <div style={{ display: 'flex', gap: 6, marginBottom: 20, flexWrap: 'wrap' }}>
                {Object.entries(caseLabelsSig).map(([cid, label]) => {
                  const on = sigCases.includes(cid);
                  return (
                    <button key={cid}
                      onClick={() => setSigCases(cs => on ? (cs.length > 1 ? cs.filter(x => x !== cid) : cs) : [...cs, cid])}
                      style={{
                        padding: '7px 14px', borderRadius: 20, border: `1px solid ${on ? caseColorsSig[cid] : C.border}`,
                        background: on ? `${caseColorsSig[cid]}22` : 'transparent',
                        color: on ? caseColorsSig[cid] : C.muted,
                        fontWeight: on ? 700 : 400, cursor: 'pointer', fontSize: 12,
                      }}>{on ? '✓ ' : ''}{label}</button>
                  );
                })}
                <span style={{ fontSize: 11, color: C.muted, alignSelf: 'center', marginLeft: 4 }}>{poolSize}語</span>
              </div>

              {/* モード選択 */}
              {[
                { id: 'quiz', icon: '⚡', title: 'シグナル即答', desc: 'シグナルを見て、解答に使うキーワードをすべて選ぶ（10問）', color: C.accent },
                { id: 'attack', icon: '⏱', title: '60秒タイムアタック', desc: '制限時間内に何問正解できるか。自己ベスト更新を狙う', color: C.orange },
                { id: 'highlight', icon: '🔍', title: '与件文ハイライト演習', desc: '与件文からシグナル箇所を見つけてタップ。本試験に最も近い', color: C.purple },
              ].map(m => (
                <button key={m.id} onClick={() => startSignal(m.id)}
                  style={{
                    display: 'block', width: '100%', textAlign: 'left', marginBottom: 10,
                    background: C.card, border: `1px solid ${m.color}44`, borderRadius: 14,
                    padding: '16px', cursor: 'pointer',
                  }}>
                  <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: 4 }}>
                    <div style={{ fontSize: 15, fontWeight: 700, color: m.color }}>{m.icon} {m.title}</div>
                    {best[m.id] > 0 && (
                      <div style={{ fontSize: 11, color: C.gold, fontWeight: 700 }}>🏆 最高 {best[m.id]}問</div>
                    )}
                  </div>
                  <div style={{ fontSize: 12, color: C.muted, lineHeight: 1.5 }}>{m.desc}</div>
                </button>
              ))}

              {/* 習熟度一覧 */}
              <div style={{ fontSize: 12, color: C.muted, margin: '20px 0 8px' }}>習熟度一覧</div>
              {SIGNAL_WORDS.filter(w => sigCases.includes(w.case)).map(w => {
                const stars = getSignalStars(mastery[w.id]);
                return (
                  <div key={w.id} style={{
                    display: 'flex', alignItems: 'center', gap: 10,
                    background: C.card, borderRadius: 10, padding: '10px 12px', marginBottom: 6,
                    border: `1px solid ${stars >= 3 ? C.gold + '44' : C.border}`,
                  }}>
                    <span style={{ fontSize: 10, color: caseColorsSig[w.case], fontWeight: 700, flexShrink: 0, width: 42 }}>
                      {caseLabelsSig[w.case]}
                    </span>
                    <span style={{ flex: 1, fontSize: 12, color: C.text, lineHeight: 1.4 }}>{w.signal}</span>
                    <StarRating mastery={stars} size={12} />
                  </div>
                );
              })}
            </div>
          );
        })()}

        {/* ===== プロセス演習（4ステップ連鎖） ===== */}
        {tabMode === 'process' && (() => {
          const caseLabelsP = { case1: '事例I', case2: '事例II', case3: '事例III' };
          const caseColorsP = { case1: '#7c3aed', case2: '#0ea5e9', case3: '#f59e0b' };
          const STEP_LABELS = ['課題発見', 'キーワード', '使い分け', '解答の型', '文章化'];
          const progAll = data.processProgress || {};

          // ---- 結果画面 ----
          if (procPhase === 'result') {
            const pct = procScore.total > 0 ? Math.round(procScore.correct / procScore.total * 100) : 0;
            const gainXp = procScore.correct * 5 + procScore.perfect * 20;
            const payload = { correct: procScore.correct, total: procScore.total, perfect: procScore.perfect, results: procResults };
            // ステップ別の正答率（どの思考段階が弱いかを可視化）
            const perStep = [0, 1, 2, 3, 4].map(i => {
              const rows = procResults.filter(r => r.steps.length > i);
              const ok = rows.filter(r => r.steps[i]).length;
              return { ok, total: rows.length };
            });
            return (
              <div style={{ padding: '16px 0' }}>
                <div style={{ textAlign: 'center', marginBottom: 20 }}>
                  <div style={{ fontSize: 44, marginBottom: 8 }}>{pct >= 80 ? '🎉' : '🎯'}</div>
                  <div style={{ fontSize: 17, fontWeight: 700, color: C.text, marginBottom: 8 }}>プロセス演習 完了</div>
                  <div style={{ fontSize: 38, fontWeight: 700, color: C.accent }}>{procScore.correct} / {procScore.total}</div>
                  <div style={{ fontSize: 14, color: pct >= 80 ? C.green : pct >= 50 ? '#f59e0b' : C.red, fontWeight: 700, marginBottom: 6 }}>
                    ステップ正答率 {pct}%
                  </div>
                  {procScore.perfect > 0 && (
                    <div style={{ fontSize: 13, color: C.gold, marginBottom: 4 }}>🏅 全ステップ正解 {procScore.perfect}問</div>
                  )}
                  <div style={{ fontSize: 13, color: C.muted }}>
                    ＋{gainXp} XP{procScore.perfect > 0 ? `（完答ボーナス +${procScore.perfect * 20}）` : ''}
                  </div>
                </div>

                {/* 思考段階別の正答率 */}
                <div style={{ background: C.card, borderRadius: 12, padding: '14px 16px', marginBottom: 20, border: `1px solid ${C.border}` }}>
                  <div style={{ fontSize: 12, color: C.muted, marginBottom: 10 }}>思考段階別の正答率</div>
                  {perStep.map((s, i) => {
                    const p = s.total > 0 ? Math.round(s.ok / s.total * 100) : 0;
                    return (
                      <div key={i} style={{ marginBottom: 8 }}>
                        <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: 12, marginBottom: 3 }}>
                          <span style={{ color: C.text }}>{i + 1}. {STEP_LABELS[i]}</span>
                          <span style={{ color: p >= 80 ? C.green : p >= 50 ? '#f59e0b' : C.red, fontWeight: 700 }}>
                            {s.ok}/{s.total}
                          </span>
                        </div>
                        <div style={{ height: 4, background: C.bg, borderRadius: 2, overflow: 'hidden' }}>
                          <div style={{ height: '100%', width: `${p}%`, background: p >= 80 ? C.green : p >= 50 ? '#f59e0b' : C.red, transition: 'width 0.4s' }} />
                        </div>
                      </div>
                    );
                  })}
                </div>

                <div style={{ display: 'flex', gap: 10 }}>
                  <button onClick={() => { onProcessComplete(payload); startProcess(); }}
                    style={{ flex: 1, padding: '14px', borderRadius: 12, border: `1px solid ${C.accent}`, background: 'transparent', color: C.accent, fontWeight: 700, cursor: 'pointer', fontSize: 14 }}>
                    🔁 もう一度
                  </button>
                  <button onClick={() => { onProcessComplete(payload); setProcPhase('menu'); }}
                    style={{ flex: 1, padding: '14px', borderRadius: 12, border: 'none', background: C.accent, color: '#000', fontWeight: 700, cursor: 'pointer', fontSize: 14 }}>
                    結果を記録して終了
                  </button>
                </div>
              </div>
            );
          }

          // ---- 実行中 ----
          if (procPhase === 'running' && procQueue.length > 0) {
            const item = procQueue[procIdx];
            const p = item.prob;
            const ok = procRevealed && procStepFlags[procStepFlags.length - 1];
            // 回答が確定できる状態か
            const canSubmit =
              procStep === 1 ? procPick !== null :
              procStep === 2 ? (procPick || []).length > 0 :
              procStep === 3 ? procPick !== null :
              procStep === 4 ? procPick !== null :
                               (procPick || []).filter(x => (x || '').trim()).length === p.blanks.length;

            return (
              <div>
                {/* ヘッダー */}
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 12 }}>
                  <button onClick={abortProcess} style={{ background: 'none', border: 'none', color: C.muted, cursor: 'pointer', fontSize: 12 }}>終了</button>
                  <div style={{ fontSize: 13, color: C.muted }}>{procIdx + 1} / {procQueue.length}問</div>
                  <span style={{ fontSize: 10, color: caseColorsP[p.case], fontWeight: 700 }}>{caseLabelsP[p.case]}</span>
                </div>

                {/* ステップインジケータ */}
                <div style={{ display: 'flex', gap: 4, marginBottom: 6 }}>
                  {STEP_LABELS.map((label, i) => {
                    const n = i + 1;
                    const done = n < procStep || (n === procStep && procRevealed);
                    const cur = n === procStep;
                    const flag = procStepFlags[i];
                    const col = done ? (flag ? C.green : C.red) : cur ? C.accent : C.border;
                    return (
                      <div key={i} style={{ flex: 1 }}>
                        <div style={{ height: 4, background: col, borderRadius: 2, transition: 'background 0.3s' }} />
                        <div style={{ fontSize: 9, color: cur ? C.accent : C.muted, textAlign: 'center', marginTop: 4, fontWeight: cur ? 700 : 400 }}>
                          {n}. {label}
                        </div>
                      </div>
                    );
                  })}
                </div>
                <div style={{ fontSize: 15, fontWeight: 700, color: C.text, margin: '14px 0 10px' }}>{p.title}</div>

                {/* ===== Step1 課題発見 ===== */}
                {procStep === 1 && (
                  <>
                    <div style={{ fontSize: 12, color: C.muted, marginBottom: 10 }}>与件文から課題を示す箇所をタップして選べ</div>
                    <div style={{ background: C.card, border: `1px solid ${C.border}`, borderRadius: 12, padding: '16px 14px', marginBottom: 14, lineHeight: 2.2 }}>
                      {p.passage.map((seg, i) => {
                        let bg = 'transparent', color = C.text, bd = 'transparent';
                        if (procRevealed) {
                          if (i === p.issueIdx) { bg = `${C.green}25`; color = C.green; bd = C.green; }
                          else if (i === procPick) { bg = `${C.red}25`; color = C.red; bd = C.red; }
                          else color = C.muted;
                        } else if (i === procPick) { bg = `${C.accent}22`; bd = C.accent; }
                        return (
                          <span key={i} onClick={() => !procRevealed && setProcPick(i)}
                            style={{ background: bg, color, borderBottom: `2px solid ${bd}`, padding: '3px 2px', borderRadius: 4, cursor: procRevealed ? 'default' : 'pointer', fontSize: 14, transition: 'all 0.2s' }}>
                            {seg}
                          </span>
                        );
                      })}
                    </div>
                  </>
                )}

                {/* ===== Step2 キーワード選択 ===== */}
                {procStep === 2 && (
                  <>
                    <div style={{ background: `${C.green}11`, border: `1px solid ${C.green}44`, borderRadius: 10, padding: '10px 12px', marginBottom: 12 }}>
                      <div style={{ fontSize: 11, color: C.green, fontWeight: 700, marginBottom: 3 }}>特定した課題</div>
                      <div style={{ fontSize: 13, color: C.text }}>{p.issueLabel}</div>
                    </div>
                    <div style={{ fontSize: 12, color: C.muted, marginBottom: 10 }}>
                      この課題への解答に使うキーワードをすべて選べ（{p.keywordAnswer.length}個）
                    </div>
                    <div style={{ display: 'flex', flexWrap: 'wrap', gap: 8, marginBottom: 14 }}>
                      {item.kwPool.map(kw => {
                        const sel = (procPick || []).includes(kw);
                        const isAns = p.keywordAnswer.includes(kw);
                        let bg = C.card, bd = C.border, color = C.text;
                        if (procRevealed) {
                          if (isAns) { bg = `${C.green}22`; bd = C.green; color = C.green; }
                          else if (sel) { bg = `${C.red}22`; bd = C.red; color = C.red; }
                          else color = C.muted;
                        } else if (sel) { bg = `${C.accent}22`; bd = C.accent; color = C.accent; }
                        return (
                          <button key={kw} disabled={procRevealed}
                            onClick={() => setProcPick(cur => {
                              const a = cur || [];
                              return a.includes(kw) ? a.filter(x => x !== kw) : [...a, kw];
                            })}
                            style={{ background: bg, border: `1px solid ${bd}`, color, borderRadius: 20, padding: '8px 14px', fontSize: 13, cursor: procRevealed ? 'default' : 'pointer', fontWeight: sel || (procRevealed && isAns) ? 700 : 400 }}>
                            {kw}
                          </button>
                        );
                      })}
                    </div>
                  </>
                )}

                {/* ===== Step3 解答の型 ===== */}
                {procStep === 3 && (
                  <>
                    <div style={{ background: C.card, border: `1px solid ${C.border}`, borderRadius: 12, padding: '16px 14px', marginBottom: 12 }}>
                      <div style={{ fontSize: 11, color: C.muted, marginBottom: 8 }}>この問題では使わなかった語</div>
                      <div style={{ fontSize: 17, fontWeight: 700, color: C.orange, textAlign: 'center' }}>{item.usageTarget}</div>
                    </div>
                    <div style={{ fontSize: 12, color: C.muted, marginBottom: 10 }}>この語はどのような場面で使うか？</div>
                    <div style={{ display: 'flex', flexDirection: 'column', gap: 8, marginBottom: 14 }}>
                      {item.usageChoices.map((usage, idx) => {
                        let bg = C.card, bd = C.border, color = C.text;
                        if (procRevealed) {
                          if (idx === item.usageCorrect) { bg = `${C.green}22`; bd = C.green; color = C.green; }
                          else if (idx === procPick) { bg = `${C.red}22`; bd = C.red; color = C.red; }
                          else color = C.muted;
                        } else if (idx === procPick) { bg = `${C.accent}22`; bd = C.accent; color = C.accent; }
                        return (
                          <button key={idx} disabled={procRevealed} onClick={() => setProcPick(idx)}
                            style={{ background: bg, border: `1px solid ${bd}`, borderRadius: 10, padding: '13px 14px', color, textAlign: 'left', cursor: procRevealed ? 'default' : 'pointer', fontSize: 13, lineHeight: 1.5 }}>
                            {usage}
                          </button>
                        );
                      })}
                    </div>
                  </>
                )}

                {/* ===== Step4 解答の型 ===== */}
                {procStep === 4 && (
                  <>
                    <div style={{ background: `linear-gradient(135deg, ${C.card}, #0d1a2e)`, border: `1px solid ${C.accent}44`, borderRadius: 12, padding: '16px 14px', marginBottom: 12 }}>
                      <div style={{ fontSize: 11, color: C.muted, marginBottom: 6 }}>設問</div>
                      <div style={{ fontSize: 14, color: C.text, lineHeight: 1.7 }}>{p.questionText}</div>
                    </div>
                    <div style={{ fontSize: 12, color: C.muted, marginBottom: 10 }}>この聞かれ方に対する解答の型・文章の形・字数配分は？</div>
                    <div style={{ display: 'flex', flexDirection: 'column', gap: 8, marginBottom: 14 }}>
                      {item.patternChoices.map((pat, idx) => {
                        let bg = C.card, bd = C.border, color = C.text;
                        if (procRevealed) {
                          if (idx === item.patternCorrect) { bg = `${C.green}22`; bd = C.green; color = C.green; }
                          else if (idx === procPick) { bg = `${C.red}22`; bd = C.red; color = C.red; }
                          else color = C.muted;
                        } else if (idx === procPick) { bg = `${C.accent}22`; bd = C.accent; color = C.accent; }
                        return (
                          <button key={pat.id} disabled={procRevealed} onClick={() => setProcPick(idx)}
                            style={{ background: bg, border: `1px solid ${bd}`, borderRadius: 10, padding: '13px 14px', color, textAlign: 'left', cursor: procRevealed ? 'default' : 'pointer', fontSize: 13 }}>
                            <div style={{ fontWeight: 700, marginBottom: 4 }}>{pat.label}</div>
                            <div style={{ fontSize: 12, color: procRevealed && idx !== item.patternCorrect ? C.muted : C.accent, fontFamily: 'monospace', marginBottom: 3 }}>
                              📝 {pat.form}
                            </div>
                            <div style={{ fontSize: 11, color: C.muted }}>📏 {pat.charPlan}　／　設問例: {pat.cue}</div>
                          </button>
                        );
                      })}
                    </div>
                  </>
                )}

                {/* ===== Step5 穴埋め ===== */}
                {procStep === 5 && (
                  <>
                    <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 10 }}>
                      <span style={{ fontSize: 12, color: C.muted }}>解答を組み立てよ</span>
                      {!procRevealed && (
                        <button onClick={() => { setProcFreeInput(v => !v); setProcPick(null); setProcBlankIdx(0); }}
                          style={{ background: 'none', border: `1px solid ${C.purple}44`, color: C.purple, borderRadius: 8, padding: '4px 10px', fontSize: 11, cursor: 'pointer' }}>
                          {procFreeInput ? '🔤 チップ選択に戻す' : '✏️ 手入力に切替'}
                        </button>
                      )}
                    </div>

                    {/* 解答文（空欄を交互に描画） */}
                    <div style={{ background: C.card, border: `1px solid ${C.border}`, borderRadius: 12, padding: '16px 14px', marginBottom: 12, lineHeight: 2.4, fontSize: 14, color: C.text }}>
                      {p.template.map((seg, i) => (
                        <React.Fragment key={i}>
                          <span>{seg}</span>
                          {i < p.blanks.length && (() => {
                            const val = (procPick || [])[i] || '';
                            const isOk = procRevealed && val.trim() === p.blanks[i];
                            if (procFreeInput && !procRevealed) {
                              return (
                                <input value={val}
                                  onChange={e => setProcPick(cur => { const a = [...(cur || [])]; a[i] = e.target.value; return a; })}
                                  style={{ width: 110, background: C.bg, border: `1px solid ${C.accent}66`, borderRadius: 6, color: C.text, fontSize: 13, padding: '3px 6px', margin: '0 3px', outline: 'none' }} />
                              );
                            }
                            return (
                              <span onClick={() => !procRevealed && !procFreeInput && setProcBlankIdx(i)}
                                style={{
                                  display: 'inline-block', minWidth: 84, textAlign: 'center', margin: '0 3px', padding: '2px 8px', borderRadius: 6,
                                  background: procRevealed ? (isOk ? `${C.green}22` : `${C.red}22`) : (procBlankIdx === i ? `${C.accent}22` : C.bg),
                                  border: `1px solid ${procRevealed ? (isOk ? C.green : C.red) : (procBlankIdx === i ? C.accent : C.border)}`,
                                  color: procRevealed ? (isOk ? C.green : C.red) : (val ? C.text : C.muted),
                                  cursor: procRevealed || procFreeInput ? 'default' : 'pointer', fontWeight: val ? 700 : 400,
                                }}>
                                {val || `［${i + 1}］`}
                              </span>
                            );
                          })()}
                        </React.Fragment>
                      ))}
                    </div>

                    {/* チップ選択 */}
                    {!procFreeInput && !procRevealed && (
                      <>
                        <div style={{ fontSize: 11, color: C.muted, marginBottom: 6 }}>
                          空欄［{procBlankIdx + 1}］に入る語を選択
                        </div>
                        <div style={{ display: 'flex', flexWrap: 'wrap', gap: 8, marginBottom: 14 }}>
                          {item.blankPool.map(w => (
                            <button key={w}
                              onClick={() => setProcPick(cur => {
                                const a = [...(cur || [])];
                                a[procBlankIdx] = w;
                                return a;
                              })}
                              style={{ background: C.card, border: `1px solid ${C.border}`, color: C.text, borderRadius: 20, padding: '8px 14px', fontSize: 13, cursor: 'pointer' }}>
                              {w}
                            </button>
                          ))}
                        </div>
                      </>
                    )}
                  </>
                )}

                {/* ===== 正誤フィードバック ===== */}
                {procRevealed && (
                  <div style={{ background: ok ? `${C.green}11` : `${C.red}11`, border: `1px solid ${ok ? C.green : C.red}44`, borderRadius: 10, padding: 12, marginBottom: 12 }}>
                    <div style={{ fontSize: 12, fontWeight: 700, color: ok ? C.green : C.red, marginBottom: 6 }}>
                      {ok ? '✓ 正解' : '✗ 不正解'}
                    </div>
                    {procStep === 1 && <div style={{ fontSize: 13, color: C.text, lineHeight: 1.6 }}>課題は「{p.issueLabel}」。該当箇所は緑で示した部分。</div>}
                    {procStep === 2 && <div style={{ fontSize: 13, color: C.text, lineHeight: 1.6 }}>正解キーワード: {p.keywordAnswer.join('・')}</div>}
                    {procStep === 3 && (
                      <div style={{ fontSize: 13, color: C.text, lineHeight: 1.6 }}>
                        「{item.usageTarget}」は{item.usageChoices[item.usageCorrect]}で使う語。この問題の課題には結び付かない。
                      </div>
                    )}
                    {procStep === 4 && (() => {
                      const pat = ANSWER_PATTERNS.find(x => x.id === p.patternAnswer);
                      return (
                        <div style={{ fontSize: 13, color: C.text, lineHeight: 1.6 }}>
                          <div style={{ marginBottom: 6 }}>正しい型: <b>{pat?.label}</b></div>
                          <div style={{ background: C.bg, borderRadius: 8, padding: '8px 10px', marginBottom: 6 }}>
                            <div style={{ fontSize: 12, color: C.accent, fontFamily: 'monospace', marginBottom: 3 }}>📝 {pat?.form}</div>
                            <div style={{ fontSize: 12, color: C.gold }}>📏 {pat?.charPlan}</div>
                          </div>
                          <div style={{ color: '#c4b5fd' }}>💡 {p.patternHint}</div>
                        </div>
                      );
                    })()}
                    {procStep === 5 && (
                      <div style={{ background: '#0a1a0a', borderRadius: 8, padding: '10px 12px', border: `1px solid ${C.green}44` }}>
                        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 4 }}>
                          <span style={{ fontSize: 11, color: C.green, fontWeight: 700 }}>📄 模範解答</span>
                          <span style={{ fontSize: 11, color: C.muted }}>{p.modelAnswer.length}字 / 100字</span>
                        </div>
                        <div style={{ fontSize: 13, color: '#86efac', lineHeight: 1.8 }}>{p.modelAnswer}</div>
                      </div>
                    )}
                  </div>
                )}

                {/* ===== アクション ===== */}
                {!procRevealed ? (
                  <button onClick={revealProcStep} disabled={!canSubmit}
                    style={{
                      width: '100%', padding: '14px', borderRadius: 12, border: 'none',
                      background: canSubmit ? C.accent : C.card, color: canSubmit ? '#000' : C.muted,
                      fontWeight: 700, cursor: canSubmit ? 'pointer' : 'default', fontSize: 15,
                    }}>
                    決定
                  </button>
                ) : (
                  <>
                    <PastQaPanel refId={`${p.id}_s${procStep}`} history={data.aiQaHistory} />
                    <button
                      onClick={() => setAiQaContext({
                        source: 'プロセス',
                        refId: `${p.id}_s${procStep}`,
                        wasCorrect: !!ok,
                        questionText:
                          procStep === 3 ? `「${item.usageTarget}」はどのような場面で使う語か` :
                          procStep === 4 ? p.questionText :
                                           `${p.title}（${STEP_LABELS[procStep - 1]}）`,
                        myAnswer:
                          procStep === 1 ? (p.passage[procPick] ?? '') :
                          procStep === 2 ? (procPick || []).join('・') :
                          procStep === 3 ? (item.usageChoices[procPick] ?? '') :
                          procStep === 4 ? (item.patternChoices[procPick]?.label ?? '') :
                                           (procPick || []).join('／'),
                        correctAnswer:
                          procStep === 1 ? p.passage[p.issueIdx] :
                          procStep === 2 ? p.keywordAnswer.join('・') :
                          procStep === 3 ? item.usageChoices[item.usageCorrect] :
                          procStep === 4 ? (ANSWER_PATTERNS.find(x => x.id === p.patternAnswer)?.label ?? '') :
                                           p.blanks.join('／'),
                        explanation:
                          procStep === 3 ? `この問題の課題は「${p.issueLabel}」` :
                          procStep === 4 ? p.patternHint :
                          procStep === 5 ? p.modelAnswer : p.issueLabel,
                      })}
                      style={{ background: C.purple + '22', border: `1px solid ${C.purple}44`, color: C.purple, borderRadius: 10, width: '100%', padding: 10, fontSize: 13, marginBottom: 10, cursor: 'pointer' }}>
                      🤖 AIに質問
                    </button>
                    <button onClick={nextProcStep}
                      style={{ width: '100%', padding: '14px', borderRadius: 12, border: 'none', background: C.accent, color: '#000', fontWeight: 700, cursor: 'pointer', fontSize: 15 }}>
                      {procStep < PROC_STEP_COUNT ? `次へ → ${STEP_LABELS[procStep]}` : (procIdx + 1 >= procQueue.length ? '結果を見る' : '次の問題 →')}
                    </button>
                  </>
                )}
              </div>
            );
          }

          // ---- メニュー ----
          const poolP = PROCESS_PROBLEMS.filter(p => procCases.includes(p.case));
          const fullDone = PROCESS_PROBLEMS.filter(p => (progAll[p.id]?.bestSteps || 0) >= PROC_STEP_COUNT).length;

          return (
            <div>
              <div style={{ fontSize: 18, fontWeight: 700, color: C.text, marginBottom: 2 }}>🎯 プロセス演習</div>
              <div style={{ fontSize: 13, color: C.muted, marginBottom: 16, lineHeight: 1.6 }}>
                課題発見 → キーワード想起 → 解答の型 → 文章化。本試験の思考順序を1問で通す
              </div>

              <div style={{ background: C.card, borderRadius: 12, padding: '14px 16px', marginBottom: 16, border: `1px solid ${C.border}` }}>
                <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: 8 }}>
                  <span style={{ fontSize: 12, color: C.muted }}>全5ステップ完答済み</span>
                  <span style={{ fontSize: 13, fontWeight: 700, color: C.gold }}>{fullDone} / {PROCESS_PROBLEMS.length}</span>
                </div>
                <div style={{ height: 6, background: C.bg, borderRadius: 3, overflow: 'hidden' }}>
                  <div style={{ height: '100%', width: `${(fullDone / PROCESS_PROBLEMS.length) * 100}%`, background: `linear-gradient(90deg, ${C.orange}, ${C.gold})`, transition: 'width 0.4s' }} />
                </div>
              </div>

              <div style={{ fontSize: 12, color: C.muted, marginBottom: 8 }}>出題範囲</div>
              <div style={{ display: 'flex', gap: 6, marginBottom: 16, flexWrap: 'wrap' }}>
                {Object.entries(caseLabelsP).map(([cid, label]) => {
                  const on = procCases.includes(cid);
                  return (
                    <button key={cid}
                      onClick={() => setProcCases(cs => on ? (cs.length > 1 ? cs.filter(x => x !== cid) : cs) : [...cs, cid])}
                      style={{
                        padding: '7px 14px', borderRadius: 20, border: `1px solid ${on ? caseColorsP[cid] : C.border}`,
                        background: on ? `${caseColorsP[cid]}22` : 'transparent', color: on ? caseColorsP[cid] : C.muted,
                        fontWeight: on ? 700 : 400, cursor: 'pointer', fontSize: 12,
                      }}>{on ? '✓ ' : ''}{label}</button>
                  );
                })}
                <span style={{ fontSize: 11, color: C.muted, alignSelf: 'center', marginLeft: 4 }}>{poolP.length}問</span>
              </div>

              <button onClick={startProcess}
                style={{ width: '100%', padding: '16px', borderRadius: 14, border: 'none', background: `linear-gradient(135deg, ${C.purple}, ${C.accent})`, color: '#000', fontWeight: 700, fontSize: 16, cursor: 'pointer', marginBottom: 6 }}>
                🎯 プロセス演習を開始（{Math.min(poolP.length, PROC_SESSION_SIZE)}問）
              </button>
              <div style={{ fontSize: 11, color: C.muted, textAlign: 'center', marginBottom: 20 }}>
                未完答の問題から優先的に出題されます
              </div>

              <div style={{ fontSize: 12, color: C.muted, marginBottom: 8 }}>到達ステップ一覧</div>
              {poolP.map(p => {
                const best = progAll[p.id]?.bestSteps || 0;
                return (
                  <div key={p.id} style={{
                    display: 'flex', alignItems: 'center', gap: 10, background: C.card, borderRadius: 10,
                    padding: '10px 12px', marginBottom: 6, border: `1px solid ${best >= 4 ? C.gold + '44' : C.border}`,
                  }}>
                    <span style={{ fontSize: 10, color: caseColorsP[p.case], fontWeight: 700, flexShrink: 0, width: 42 }}>{caseLabelsP[p.case]}</span>
                    <span style={{ flex: 1, fontSize: 12, color: C.text }}>{p.title}</span>
                    <span style={{ display: 'flex', gap: 3, flexShrink: 0 }}>
                      {[0, 1, 2, 3, 4].map(i => (
                        <span key={i} style={{ width: 7, height: 7, borderRadius: '50%', background: i < best ? C.green : '#334155', display: 'inline-block' }} />
                      ))}
                    </span>
                  </div>
                );
              })}
            </div>
          );
        })()}

        {/* ===== 写経（写し書き／記憶で書く） ===== */}
        {tabMode === 'writing' && (() => {
          const caseLabelsW = { case1: '事例I', case2: '事例II', case3: '事例III' };
          const caseColorsW = { case1: '#7c3aed', case2: '#0ea5e9', case3: '#f59e0b' };
          const wProg = data.writingProgress || {};

          // ---- 結果画面 ----
          if (wrPhase === 'result' && wrResult && wrProb) {
            const r = wrResult;
            const xp = r.mode === 'copy'
              ? 10
              : Math.max(0, Math.round(r.coverage / 100 * 30) + (r.lenOk ? 5 : 0) - r.hintsUsed * 5);
            return (
              <div style={{ padding: '16px 0' }}>
                <div style={{ textAlign: 'center', marginBottom: 20 }}>
                  <div style={{ fontSize: 44, marginBottom: 8 }}>{r.mode === 'copy' ? '✍️' : (r.coverage >= 80 ? '🎉' : '📝')}</div>
                  <div style={{ fontSize: 17, fontWeight: 700, color: C.text, marginBottom: 10 }}>
                    {r.mode === 'copy' ? '写し書き完了' : '採点結果'}
                  </div>
                  {r.mode === 'copy' ? (
                    <>
                      <div style={{ fontSize: 38, fontWeight: 700, color: C.accent }}>一致率 {r.ratio}%</div>
                      <div style={{ fontSize: 13, color: C.muted }}>{r.len}字 / 模範 {r.target}字</div>
                    </>
                  ) : (
                    <>
                      <div style={{ fontSize: 38, fontWeight: 700, color: r.coverage >= 80 ? C.green : r.coverage >= 50 ? '#f59e0b' : C.red }}>
                        キーワード {r.coverage}%
                      </div>
                      <div style={{ fontSize: 13, color: r.lenOk ? C.green : '#f59e0b', marginBottom: 4 }}>
                        {r.len}字 / 目安 {r.target}字 {r.lenOk ? '✓ 字数OK' : '△ 字数に開きあり'}
                      </div>
                      {r.hintsUsed > 0 && <div style={{ fontSize: 12, color: C.muted }}>ヒント {r.hintsUsed}段階使用（−{r.hintsUsed * 5} XP）</div>}
                    </>
                  )}
                  <div style={{ fontSize: 13, color: C.gold, marginTop: 6, fontWeight: 700 }}>＋{xp} XP</div>
                </div>

                {r.mode === 'recall' && (
                  <div style={{ background: C.card, borderRadius: 12, padding: '14px 16px', marginBottom: 16, border: `1px solid ${C.border}` }}>
                    <div style={{ fontSize: 12, color: C.muted, marginBottom: 8 }}>必須キーワード</div>
                    <div style={{ display: 'flex', flexWrap: 'wrap', gap: 6 }}>
                      {wrProb.blanks.map(k => {
                        const ok = r.hit.includes(k);
                        return (
                          <span key={k} style={{
                            fontSize: 12, padding: '5px 11px', borderRadius: 20, fontWeight: 700,
                            background: ok ? `${C.green}22` : `${C.red}22`,
                            color: ok ? C.green : C.red, border: `1px solid ${ok ? C.green : C.red}55`,
                          }}>{ok ? '✓ ' : '✗ '}{k}</span>
                        );
                      })}
                    </div>
                  </div>
                )}

                {r.mode === 'recall' && wrText.trim() && (
                  <div style={{ background: C.card, borderRadius: 12, padding: '12px 14px', marginBottom: 12, border: `1px solid ${C.border}` }}>
                    <div style={{ fontSize: 11, color: C.muted, marginBottom: 5 }}>あなたの解答</div>
                    <div style={{ fontSize: 13, color: C.text, lineHeight: 1.8, whiteSpace: 'pre-wrap' }}>{wrText.trim()}</div>
                  </div>
                )}

                <div style={{ background: '#0a1a0a', borderRadius: 12, padding: '14px 16px', marginBottom: 20, border: `1px solid ${C.green}44` }}>
                  <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: 5 }}>
                    <span style={{ fontSize: 11, color: C.green, fontWeight: 700 }}>📄 模範解答</span>
                    <span style={{ fontSize: 11, color: C.muted }}>{wrProb.modelAnswer.length}字</span>
                  </div>
                  <div style={{ fontSize: 13, color: '#86efac', lineHeight: 1.8 }}>{wrProb.modelAnswer}</div>
                </div>

                <div style={{ display: 'flex', gap: 10 }}>
                  <button onClick={() => {
                      onWritingComplete({ mode: r.mode, probId: wrProb.id, coverage: r.coverage || 0, lenOk: !!r.lenOk, hintsUsed: r.hintsUsed || 0, xp });
                      startWriting(r.mode);
                    }}
                    style={{ flex: 1, padding: '14px', borderRadius: 12, border: `1px solid ${C.accent}`, background: 'transparent', color: C.accent, fontWeight: 700, cursor: 'pointer', fontSize: 14 }}>
                    🔁 次の問題
                  </button>
                  <button onClick={() => {
                      onWritingComplete({ mode: r.mode, probId: wrProb.id, coverage: r.coverage || 0, lenOk: !!r.lenOk, hintsUsed: r.hintsUsed || 0, xp });
                      setWrPhase('menu');
                    }}
                    style={{ flex: 1, padding: '14px', borderRadius: 12, border: 'none', background: C.accent, color: '#000', fontWeight: 700, cursor: 'pointer', fontSize: 14 }}>
                    記録して終了
                  </button>
                </div>
              </div>
            );
          }

          // ---- 実行中 ----
          if ((wrPhase === 'copy' || wrPhase === 'recall') && wrProb) {
            const p = wrProb;
            const pat = ANSWER_PATTERNS.find(x => x.id === p.patternAnswer);
            const segs = parseCharPlan(pat?.charPlan);
            const total = segs.reduce((n, x) => n + x.chars, 0) || p.modelAnswer.length;
            const len = wrText.trim().length;
            const ratio = wrPhase === 'copy' && len > 0
              ? Math.round(lcsLength(wrText.trim(), p.modelAnswer) / p.modelAnswer.length * 100) : 0;

            return (
              <div>
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 12 }}>
                  <button onClick={() => setWrPhase('menu')} style={{ background: 'none', border: 'none', color: C.muted, cursor: 'pointer', fontSize: 12 }}>← やめる</button>
                  <div style={{ fontSize: 13, fontWeight: 700, color: C.text }}>{wrPhase === 'copy' ? '✍️ 写し書き' : '🧠 記憶で書く'}</div>
                  <span style={{ fontSize: 10, color: caseColorsW[p.case], fontWeight: 700 }}>{caseLabelsW[p.case]}</span>
                </div>

                <div style={{ background: C.card, borderRadius: 12, padding: '14px 16px', marginBottom: 12, border: `1px solid ${C.border}` }}>
                  <div style={{ fontSize: 11, color: C.muted, marginBottom: 5 }}>設問</div>
                  <div style={{ fontSize: 14, color: C.text, lineHeight: 1.7 }}>{p.questionText}</div>
                </div>

                {/* 写し書きは模範解答を常時表示 */}
                {wrPhase === 'copy' && (
                  <div style={{ background: '#0a1a0a', borderRadius: 12, padding: '14px 16px', marginBottom: 12, border: `1px solid ${C.green}44` }}>
                    <div style={{ fontSize: 11, color: C.green, fontWeight: 700, marginBottom: 5 }}>📄 これを書き写す</div>
                    <div style={{ fontSize: 14, color: '#86efac', lineHeight: 2 }}>{p.modelAnswer}</div>
                  </div>
                )}

                {/* 記憶モードの段階ヒント */}
                {wrPhase === 'recall' && (
                  <div style={{ marginBottom: 12 }}>
                    {wrHint >= 1 && (
                      <div style={{ background: `${C.purple}15`, border: `1px solid ${C.purple}44`, borderRadius: 10, padding: '10px 12px', marginBottom: 6 }}>
                        <span style={{ fontSize: 11, color: C.purple, fontWeight: 700 }}>解答の型　</span>
                        <span style={{ fontSize: 13, color: C.text }}>{pat?.label}</span>
                      </div>
                    )}
                    {wrHint >= 2 && (
                      <div style={{ background: `${C.purple}15`, border: `1px solid ${C.purple}44`, borderRadius: 10, padding: '10px 12px', marginBottom: 6 }}>
                        <div style={{ fontSize: 12, color: C.accent, fontFamily: 'monospace', marginBottom: 3 }}>📝 {pat?.form}</div>
                        <div style={{ fontSize: 12, color: C.gold }}>📏 {pat?.charPlan}</div>
                      </div>
                    )}
                    {wrHint >= 3 && (
                      <div style={{ background: `${C.purple}15`, border: `1px solid ${C.purple}44`, borderRadius: 10, padding: '10px 12px', marginBottom: 6 }}>
                        <div style={{ fontSize: 11, color: C.purple, fontWeight: 700, marginBottom: 5 }}>キーワード</div>
                        <div style={{ display: 'flex', flexWrap: 'wrap', gap: 6 }}>
                          {p.blanks.map(k => (
                            <span key={k} style={{ fontSize: 12, padding: '4px 10px', borderRadius: 20, background: C.card, color: C.text, border: `1px solid ${C.border}` }}>{k}</span>
                          ))}
                        </div>
                      </div>
                    )}
                    {wrHint < 3 && (
                      <button onClick={() => setWrHint(h => h + 1)}
                        style={{ width: '100%', padding: '10px', borderRadius: 10, border: `1px dashed ${C.purple}66`, background: 'transparent', color: C.purple, cursor: 'pointer', fontSize: 12 }}>
                        💡 ヒントを開く（{wrHint + 1}/3 · −5XP）　次: {['解答の型', '文章の形と字数配分', 'キーワード'][wrHint]}
                      </button>
                    )}
                  </div>
                )}

                {/* 字数配分バー */}
                <div style={{ marginBottom: 6 }}>
                  <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: 11, marginBottom: 4 }}>
                    <span style={{ color: C.muted }}>📏 {pat?.charPlan}</span>
                    <span style={{ color: len > 100 ? C.red : len > total ? '#f59e0b' : C.accent, fontWeight: 700 }}>
                      {len} / {total}字{len > 100 ? '（100字超過）' : ''}
                    </span>
                  </div>
                  <div style={{ position: 'relative', height: 10, background: C.bg, borderRadius: 5, overflow: 'hidden', border: `1px solid ${C.border}` }}>
                    <div style={{
                      height: '100%', width: `${Math.min(len / Math.max(total, 1) * 100, 100)}%`,
                      background: len > 100 ? C.red : `linear-gradient(90deg, ${C.purple}, ${C.accent})`, transition: 'width 0.15s',
                    }} />
                    {/* 区画の区切り線 */}
                    {segs.slice(0, -1).map((_, i) => {
                      const cum = segs.slice(0, i + 1).reduce((n, x) => n + x.chars, 0);
                      return (
                        <div key={i} style={{ position: 'absolute', left: `${cum / total * 100}%`, top: 0, bottom: 0, width: 2, background: C.bg }} />
                      );
                    })}
                  </div>
                  <div style={{ display: 'flex', fontSize: 9, color: C.muted, marginTop: 2 }}>
                    {segs.map((sg, i) => (
                      <div key={i} style={{ width: `${sg.chars / total * 100}%`, textAlign: 'center' }}>{sg.label}{sg.chars}</div>
                    ))}
                  </div>
                </div>

                <textarea
                  value={wrText}
                  onChange={e => setWrText(e.target.value)}
                  placeholder={wrPhase === 'copy' ? '上の模範解答を書き写す...' : '設問に対する解答を書く...'}
                  rows={6}
                  style={{
                    width: '100%', padding: '14px', borderRadius: 12, background: C.card,
                    border: `1px solid ${C.border}`, color: C.text, fontSize: 14, lineHeight: 1.9,
                    resize: 'vertical', boxSizing: 'border-box', outline: 'none', marginBottom: 8,
                  }}
                />

                {wrPhase === 'copy' && len > 0 && (
                  <div style={{ fontSize: 12, color: ratio >= 95 ? C.green : C.muted, textAlign: 'right', marginBottom: 8, fontWeight: ratio >= 95 ? 700 : 400 }}>
                    一致率 {ratio}%{ratio >= 95 ? '　✓ ほぼ一致' : ''}
                  </div>
                )}

                <button
                  onClick={wrPhase === 'copy' ? finishCopy : gradeRecall}
                  disabled={len === 0}
                  style={{
                    width: '100%', padding: '16px', borderRadius: 12, border: 'none',
                    background: len === 0 ? C.card : `linear-gradient(135deg, ${C.purple}, ${C.accent})`,
                    color: len === 0 ? C.muted : '#000', fontWeight: 700,
                    cursor: len === 0 ? 'default' : 'pointer', fontSize: 16,
                  }}>
                  {wrPhase === 'copy' ? '完了' : '採点する'}
                </button>
              </div>
            );
          }

          // ---- メニュー ----
          const poolW = PROCESS_PROBLEMS.filter(p => wrCases.includes(p.case));
          const copiedTotal   = poolW.filter(p => (wProg[p.id]?.copied || 0) > 0).length;
          const recalledTotal = poolW.filter(p => (wProg[p.id]?.recalled || 0) > 0).length;

          return (
            <div>
              <div style={{ fontSize: 18, fontWeight: 700, color: C.text, marginBottom: 2 }}>✍️ 写経</div>
              <div style={{ fontSize: 13, color: C.muted, marginBottom: 16, lineHeight: 1.6 }}>
                書き写して型を覚え、記憶だけで書けるようにする
              </div>

              <div style={{ fontSize: 12, color: C.muted, marginBottom: 8 }}>出題範囲</div>
              <div style={{ display: 'flex', gap: 6, marginBottom: 18, flexWrap: 'wrap' }}>
                {Object.entries(caseLabelsW).map(([cid, label]) => {
                  const on = wrCases.includes(cid);
                  return (
                    <button key={cid}
                      onClick={() => setWrCases(cs => on ? (cs.length > 1 ? cs.filter(x => x !== cid) : cs) : [...cs, cid])}
                      style={{
                        padding: '7px 14px', borderRadius: 20, border: `1px solid ${on ? caseColorsW[cid] : C.border}`,
                        background: on ? `${caseColorsW[cid]}22` : 'transparent', color: on ? caseColorsW[cid] : C.muted,
                        fontWeight: on ? 700 : 400, cursor: 'pointer', fontSize: 12,
                      }}>{on ? '✓ ' : ''}{label}</button>
                  );
                })}
                <span style={{ fontSize: 11, color: C.muted, alignSelf: 'center', marginLeft: 4 }}>{poolW.length}問</span>
              </div>

              {[
                { id: 'copy', icon: '✍️', title: '写し書き', color: C.accent,
                  desc: '模範解答を見ながら書き写す。字数配分バーで、どの要素に何字使うかを体に入れる',
                  done: copiedTotal },
                { id: 'recall', icon: '🧠', title: '記憶で書く', color: C.purple,
                  desc: '設問だけを見て解答を書く。手が止まったらヒントを3段階まで開ける',
                  done: recalledTotal },
              ].map(m => (
                <button key={m.id} onClick={() => startWriting(m.id)}
                  style={{ display: 'block', width: '100%', textAlign: 'left', marginBottom: 10, background: C.card, border: `1px solid ${m.color}44`, borderRadius: 14, padding: '16px', cursor: 'pointer' }}>
                  <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: 4 }}>
                    <div style={{ fontSize: 15, fontWeight: 700, color: m.color }}>{m.icon} {m.title}</div>
                    <div style={{ fontSize: 11, color: C.muted }}>{m.done} / {poolW.length}問 実施</div>
                  </div>
                  <div style={{ fontSize: 12, color: C.muted, lineHeight: 1.5 }}>{m.desc}</div>
                </button>
              ))}

              <div style={{ fontSize: 12, color: C.muted, margin: '20px 0 8px' }}>問題別の実施状況</div>
              {poolW.map(p => {
                const g = wProg[p.id] || {};
                return (
                  <div key={p.id} style={{
                    display: 'flex', alignItems: 'center', gap: 10, background: C.card, borderRadius: 10,
                    padding: '10px 12px', marginBottom: 6,
                    border: `1px solid ${(g.bestCoverage || 0) >= 100 ? C.gold + '44' : C.border}`,
                  }}>
                    <span style={{ fontSize: 10, color: caseColorsW[p.case], fontWeight: 700, flexShrink: 0, width: 42 }}>{caseLabelsW[p.case]}</span>
                    <span style={{ flex: 1, fontSize: 12, color: C.text }}>{p.title}</span>
                    <span style={{ fontSize: 10, color: C.muted, flexShrink: 0 }}>
                      ✍️{g.copied || 0} 🧠{g.recalled || 0}
                      {g.bestCoverage != null && <span style={{ color: g.bestCoverage >= 80 ? C.green : C.muted, marginLeft: 6, fontWeight: 700 }}>{g.bestCoverage}%</span>}
                    </span>
                  </div>
                );
              })}
            </div>
          );
        })()}

        {/* ===== テキスト ===== */}
        {tabMode === 'textbook' && (() => {
          const topics = TEXTBOOK_CONTENT[selectedCase] || [];
          if (cardSession) {
            const card = cardSession.cards[cardSession.index];
            return (
              <div>
                <div style={{ display: 'flex', gap: 6, marginBottom: 16, flexWrap: 'wrap' }}>
                  {caseSelectors.map(cs => (
                    <button key={cs.id}
                      onClick={() => { setSelectedCase(cs.id); setCardSession(null); setExpandedTopic(null); }}
                      style={{
                        padding: '6px 12px', borderRadius: 20, border: 'none',
                        background: selectedCase === cs.id ? C.purple : C.card,
                        color: selectedCase === cs.id ? '#fff' : C.muted,
                        fontWeight: selectedCase === cs.id ? 700 : 400,
                        cursor: 'pointer', fontSize: 12,
                      }}
                    >{cs.label} <span style={{ fontSize: 10, opacity: 0.75 }}>{cs.sub}</span></button>
                  ))}
                </div>
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 16 }}>
                  <button onClick={() => setCardSession(null)}
                    style={{ background: 'none', border: 'none', color: C.accent, cursor: 'pointer', fontSize: 14, padding: 0 }}
                  >← テキストに戻る</button>
                  <span style={{ color: C.muted, fontSize: 13 }}>{cardSession.index + 1} / {cardSession.cards.length}</span>
                </div>
                <div style={{ fontSize: 15, fontWeight: 700, color: C.text, marginBottom: 12 }}>
                  {topics.find(t => t.id === cardSession.topicId)?.icon} {topics.find(t => t.id === cardSession.topicId)?.title}
                </div>
                <div onClick={() => setCardSession(s => ({ ...s, flipped: !s.flipped }))}
                  style={{
                    background: cardSession.flipped ? '#1a1040' : C.card,
                    border: `1px solid ${cardSession.flipped ? C.purple : '#334155'}`,
                    borderRadius: 16, padding: 28, minHeight: 160,
                    display: 'flex', flexDirection: 'column', justifyContent: 'center',
                    cursor: 'pointer', transition: 'all 0.2s', marginBottom: 20,
                  }}
                >
                  {!cardSession.flipped ? (
                    <>
                      <div style={{ fontSize: 16, fontWeight: 700, color: C.text, marginBottom: 16, lineHeight: 1.5 }}>{card.front}</div>
                      <div style={{ fontSize: 12, color: C.muted, textAlign: 'center' }}>タップして答えを確認 →</div>
                    </>
                  ) : (
                    <>
                      <div style={{ fontSize: 11, color: C.purple, marginBottom: 8, fontWeight: 600 }}>答え</div>
                      <div style={{ fontSize: 15, color: C.text, lineHeight: 1.7, whiteSpace: 'pre-line' }}>{card.back}</div>
                    </>
                  )}
                </div>
                <div style={{ display: 'flex', gap: 12 }}>
                  <button onClick={() => setCardSession(s => ({ ...s, index: Math.max(0, s.index - 1), flipped: false }))}
                    disabled={cardSession.index === 0}
                    style={{
                      flex: 1, padding: '12px', borderRadius: 12, border: 'none',
                      background: cardSession.index === 0 ? '#1e293b' : C.card,
                      color: cardSession.index === 0 ? C.muted : C.text,
                      cursor: cardSession.index === 0 ? 'default' : 'pointer', fontSize: 14,
                    }}
                  >← 前へ</button>
                  <button onClick={() => setCardSession(s => ({ ...s, index: Math.min(s.cards.length - 1, s.index + 1), flipped: false }))}
                    disabled={cardSession.index === cardSession.cards.length - 1}
                    style={{
                      flex: 1, padding: '12px', borderRadius: 12, border: 'none',
                      background: cardSession.index === cardSession.cards.length - 1 ? '#1e293b' : C.accent,
                      color: cardSession.index === cardSession.cards.length - 1 ? C.muted : '#000',
                      cursor: cardSession.index === cardSession.cards.length - 1 ? 'default' : 'pointer',
                      fontSize: 14, fontWeight: 700,
                    }}
                  >次へ →</button>
                </div>
              </div>
            );
          }
          return (
            <div>
              <div style={{ display: 'flex', gap: 6, marginBottom: 16, flexWrap: 'wrap' }}>
                {caseSelectors.map(cs => (
                  <button key={cs.id}
                    onClick={() => { setSelectedCase(cs.id); setExpandedTopic(null); }}
                    style={{
                      padding: '6px 12px', borderRadius: 20, border: 'none',
                      background: selectedCase === cs.id ? C.purple : C.card,
                      color: selectedCase === cs.id ? '#fff' : C.muted,
                      fontWeight: selectedCase === cs.id ? 700 : 400,
                      cursor: 'pointer', fontSize: 12,
                    }}
                  >{cs.label} <span style={{ fontSize: 10, opacity: 0.75 }}>{cs.sub}</span></button>
                ))}
              </div>
              {topics.map(topic => {
                const isOpen = expandedTopic === topic.id;
                return (
                  <div key={topic.id} style={{
                    background: C.card, borderRadius: 12, marginBottom: 10,
                    border: `1px solid ${isOpen ? C.accent + '44' : '#1e293b'}`,
                    overflow: 'hidden',
                  }}>
                    <button onClick={() => setExpandedTopic(isOpen ? null : topic.id)}
                      style={{
                        width: '100%', background: 'none', border: 'none',
                        padding: '14px 16px', display: 'flex', alignItems: 'flex-start',
                        gap: 12, cursor: 'pointer', textAlign: 'left',
                      }}
                    >
                      <span style={{ fontSize: 22 }}>{topic.icon}</span>
                      <div style={{ flex: 1 }}>
                        <div style={{ fontSize: 14, fontWeight: 700, color: C.text }}>{topic.title}</div>
                        <div style={{ fontSize: 12, color: C.muted, marginTop: 3 }}>{topic.summary}</div>
                      </div>
                      <span style={{ color: C.muted, fontSize: 16, marginTop: 2 }}>{isOpen ? '▲' : '▼'}</span>
                    </button>
                    {isOpen && (
                      <div style={{ padding: '0 16px 16px' }}>
                        <div style={{
                          fontSize: 13, color: '#cbd5e1', lineHeight: 1.8, whiteSpace: 'pre-line',
                          marginBottom: 12, borderTop: '1px solid #1e293b', paddingTop: 12,
                        }}>{topic.body}</div>
                        {topic.mnemonic && (
                          <div style={{
                            background: '#1a1040', borderRadius: 8, padding: '10px 12px',
                            marginBottom: 12, border: `1px solid ${C.purple}44`,
                          }}>
                            <span style={{ fontSize: 11, color: C.purple, fontWeight: 700 }}>💡 覚え方 </span>
                            <span style={{ fontSize: 12, color: '#c4b5fd' }}>{topic.mnemonic}</span>
                          </div>
                        )}
                        <button onClick={() => setCardSession({ topicId: topic.id, cards: topic.cards, index: 0, flipped: false })}
                          style={{
                            width: '100%', padding: '10px', borderRadius: 10,
                            background: C.accent + '22', color: C.accent,
                            cursor: 'pointer', fontSize: 13, fontWeight: 700,
                            border: `1px solid ${C.accent}44`,
                          }}
                        >🃏 カードで確認 ({topic.cards.length}枚) →</button>
                      </div>
                    )}
                  </div>
                );
              })}
            </div>
          );
        })()}

        {/* ===== 模擬試験 ===== */}
        {tabMode === 'exam' && (() => {
          const caseLabels2 = { case1: '事例I 人事・組織', case2: '事例II マーケ', case3: '事例III 生産', case4: '事例IV 財務' };

          // ---- 結果画面 ----
          if (examPhase === 'result') {
            const correct = examAnswers.filter(Boolean).length;
            const total = examAnswers.length;
            const byCase = {};
            examProblems.forEach((p, i) => {
              const cid = p.case || 'case4';
              if (!byCase[cid]) byCase[cid] = { ok: 0, total: 0 };
              byCase[cid].total++;
              if (examAnswers[i]) byCase[cid].ok++;
            });
            return (
              <div style={{ textAlign: 'center', padding: '24px 0' }}>
                <div style={{ fontSize: 40, marginBottom: 12 }}>{correct === total ? '🎉' : '📝'}</div>
                <div style={{ fontSize: 20, fontWeight: 700, color: correct === total ? C.gold : C.text, marginBottom: 8 }}>
                  {correct === total ? '満点！' : '試験終了'}
                </div>
                <div style={{ fontSize: 36, fontWeight: 700, color: C.accent, marginBottom: 4 }}>
                  {correct} / {total}
                </div>
                <div style={{ fontSize: 13, color: C.muted, marginBottom: 20 }}>＋{correct * 10} XP 獲得</div>
                <div style={{ display: 'flex', justifyContent: 'center', flexWrap: 'wrap', gap: 8, marginBottom: 20 }}>
                  {examAnswers.map((ok, i) => (
                    <div key={i} style={{
                      width: 30, height: 30, borderRadius: '50%',
                      background: ok ? C.green : C.red,
                      display: 'flex', alignItems: 'center', justifyContent: 'center',
                      fontSize: 14, color: '#fff', fontWeight: 700,
                    }}>{ok ? '○' : '×'}</div>
                  ))}
                </div>
                <div style={{ background: C.card, borderRadius: 12, padding: '14px 16px', marginBottom: 20, textAlign: 'left' }}>
                  {Object.entries(byCase).map(([cid, v]) => (
                    <div key={cid} style={{ display: 'flex', justifyContent: 'space-between', marginBottom: 6 }}>
                      <span style={{ fontSize: 13, color: C.text }}>{caseLabels2[cid]}</span>
                      <span style={{ fontSize: 13, fontWeight: 700, color: v.ok === v.total ? C.gold : C.accent }}>
                        {v.ok}/{v.total}
                      </span>
                    </div>
                  ))}
                </div>
                <div style={{ display: 'flex', gap: 10, justifyContent: 'center' }}>
                  <button onClick={() => setExamPhase('setup')} style={{
                    padding: '12px 20px', borderRadius: 10, border: `1px solid ${C.accent}`,
                    background: 'transparent', color: C.accent, fontWeight: 700, cursor: 'pointer', fontSize: 14,
                  }}>もう一度</button>
                  <button onClick={() => setTabMode('study')} style={{
                    padding: '12px 20px', borderRadius: 10, border: 'none',
                    background: C.accent, color: '#000', fontWeight: 700, cursor: 'pointer', fontSize: 14,
                  }}>終了</button>
                </div>
              </div>
            );
          }

          // ---- 試験中 ----
          if (examPhase === 'solving' && examProblems.length > 0) {
            const ep = examProblems[examIdx];
            const estep = ep.steps[0];
            const mins = examTimeLeft !== null ? Math.floor(examTimeLeft / 60) : null;
            const secs = examTimeLeft !== null ? examTimeLeft % 60 : null;
            const timeWarn = examTimeLeft !== null && examTimeLeft <= 600;
            return (
              <div>
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 16 }}>
                  <div style={{ fontSize: 13, color: C.muted }}>問題 {examIdx + 1}/{examProblems.length}</div>
                  {examTimeLeft !== null && (
                    <div style={{ fontSize: 15, fontWeight: 700, color: timeWarn ? C.red : C.gold }}>
                      ⏱ {String(mins).padStart(2,'0')}:{String(secs).padStart(2,'0')}
                    </div>
                  )}
                  <button onClick={() => { if (examTimerRef.current) clearInterval(examTimerRef.current); setExamPhase('setup'); }}
                    style={{ background: 'none', border: 'none', color: C.muted, cursor: 'pointer', fontSize: 12 }}>退出</button>
                </div>
                <div style={{ background: C.card, borderRadius: 12, padding: 16, marginBottom: 12 }}>
                  <div style={{ fontSize: 12, color: C.muted, marginBottom: 6 }}>{ep.title}</div>
                  <div style={{ fontSize: 14, color: C.text, lineHeight: 1.6 }}>{estep.question}</div>
                </div>
                <div style={{ display: 'flex', flexDirection: 'column', gap: 8, marginBottom: 14 }}>
                  {estep.choices.map((choice, idx) => {
                    let bg = C.card, border = C.border, color = C.text;
                    if (examChoice !== null) {
                      if (idx === estep.correct) { bg = '#0a2010'; border = C.green; color = C.green; }
                      else if (idx === examChoice && examChoice !== estep.correct) { bg = '#200a0a'; border = C.red; color = C.red; }
                    } else if (examChoice === idx) {
                      bg = `${C.accent}22`; border = C.accent; color = C.accent;
                    }
                    return (
                      <button key={idx} onClick={() => handleExamChoice(idx)} style={{
                        background: bg, border: `1px solid ${border}`, borderRadius: 10,
                        padding: '12px 14px', color, textAlign: 'left', cursor: examChoice !== null ? 'default' : 'pointer',
                        fontSize: 13, lineHeight: 1.5,
                      }}>
                        <span style={{ fontWeight: 700, marginRight: 8 }}>
                          {['A','B','C','D'][idx]}
                        </span>{choice}
                      </button>
                    );
                  })}
                </div>
                {examShowExp && (
                  <div style={{ background: '#0d1a10', border: `1px solid ${C.green}44`, borderRadius: 10, padding: 12, marginBottom: 14, fontSize: 13, color: '#a7f3d0', lineHeight: 1.6 }}>
                    {estep.explanation}
                  </div>
                )}
                {examShowExp && (
                  <>
                    <PastQaPanel refId={`${ep.id}_${estep.id}`} history={data.aiQaHistory} />
                    <button
                      onClick={() => setAiQaContext({
                        source: '模擬試験',
                        refId: `${ep.id}_${estep.id}`,
                        wasCorrect: examChoice === estep.correct,
                        questionText: estep.question,
                        myAnswer: estep.choices[examChoice],
                        correctAnswer: estep.choices[estep.correct],
                        explanation: estep.explanation,
                      })}
                      style={{
                        background: C.purple + '22', border: `1px solid ${C.purple}44`,
                        color: C.purple, borderRadius: 10, width: '100%',
                        padding: 10, fontSize: 13, marginBottom: 14, cursor: 'pointer',
                      }}
                    >🤖 AIに質問</button>
                  </>
                )}
                {examChoice !== null && (
                  <button onClick={handleExamNext} style={{
                    width: '100%', padding: '14px', borderRadius: 12, border: 'none',
                    background: C.accent, color: '#000', fontWeight: 700, cursor: 'pointer', fontSize: 15,
                  }}>
                    {examIdx + 1 < examProblems.length ? '次の問題 →' : '結果を見る'}
                  </button>
                )}
              </div>
            );
          }

          // ---- セットアップ画面 ----
          return (
            <div>
              <div style={{ fontSize: 15, fontWeight: 700, color: C.text, marginBottom: 4 }}>模擬試験モード</div>
              <div style={{ fontSize: 13, color: C.muted, marginBottom: 20 }}>問題をランダムに出題します</div>

              <div style={{ background: C.card, borderRadius: 12, padding: '14px 16px', marginBottom: 14 }}>
                <div style={{ fontSize: 12, color: C.muted, marginBottom: 10 }}>出題する事例</div>
                <div style={{ display: 'flex', flexWrap: 'wrap', gap: 8 }}>
                  {[
                    { id: 'case1', label: '事例I' }, { id: 'case2', label: '事例II' },
                    { id: 'case3', label: '事例III' }, { id: 'case4', label: '事例IV' },
                  ].map(c => {
                    const on = examConfig.cases.includes(c.id);
                    return (
                      <button key={c.id} onClick={() => setExamConfig(cfg => ({
                        ...cfg,
                        cases: on
                          ? cfg.cases.filter(x => x !== c.id)
                          : [...cfg.cases, c.id],
                      }))} style={{
                        padding: '8px 14px', borderRadius: 20, border: `1px solid ${on ? C.accent : C.border}`,
                        background: on ? `${C.accent}22` : C.bg,
                        color: on ? C.accent : C.muted, fontWeight: on ? 700 : 400,
                        cursor: 'pointer', fontSize: 13,
                      }}>{on ? '✓ ' : ''}{c.label}</button>
                    );
                  })}
                </div>
              </div>

              <div style={{ background: C.card, borderRadius: 12, padding: '14px 16px', marginBottom: 14 }}>
                <div style={{ fontSize: 12, color: C.muted, marginBottom: 10 }}>各事例から何問出題するか</div>
                <div style={{ display: 'flex', gap: 8 }}>
                  {[{ v: 2, label: '2問' }, { v: 3, label: '3問' }, { v: 'all', label: '全問' }].map(opt => (
                    <button key={opt.v} onClick={() => setExamConfig(cfg => ({ ...cfg, perCase: opt.v }))} style={{
                      flex: 1, padding: '10px', borderRadius: 10, border: `1px solid ${examConfig.perCase === opt.v ? C.accent : C.border}`,
                      background: examConfig.perCase === opt.v ? `${C.accent}22` : C.bg,
                      color: examConfig.perCase === opt.v ? C.accent : C.muted,
                      fontWeight: examConfig.perCase === opt.v ? 700 : 400,
                      cursor: 'pointer', fontSize: 13,
                    }}>{opt.label}</button>
                  ))}
                </div>
              </div>

              <div style={{ background: C.card, borderRadius: 12, padding: '14px 16px', marginBottom: 20 }}>
                <div style={{ fontSize: 12, color: C.muted, marginBottom: 10 }}>制限時間</div>
                <div style={{ display: 'flex', gap: 8 }}>
                  {[{ v: null, label: 'なし' }, { v: 40, label: '40分' }, { v: 80, label: '80分' }].map(opt => (
                    <button key={String(opt.v)} onClick={() => setExamConfig(cfg => ({ ...cfg, timeLimit: opt.v }))} style={{
                      flex: 1, padding: '10px', borderRadius: 10, border: `1px solid ${examConfig.timeLimit === opt.v ? C.gold : C.border}`,
                      background: examConfig.timeLimit === opt.v ? `${C.gold}22` : C.bg,
                      color: examConfig.timeLimit === opt.v ? C.gold : C.muted,
                      fontWeight: examConfig.timeLimit === opt.v ? 700 : 400,
                      cursor: 'pointer', fontSize: 13,
                    }}>{opt.label}</button>
                  ))}
                </div>
              </div>

              <button
                onClick={startExam}
                disabled={examConfig.cases.length === 0}
                style={{
                  width: '100%', padding: '16px', borderRadius: 12, border: 'none',
                  background: examConfig.cases.length === 0 ? C.card : `linear-gradient(135deg, ${C.purple}, ${C.accent})`,
                  color: examConfig.cases.length === 0 ? C.muted : '#000',
                  fontWeight: 700, cursor: examConfig.cases.length === 0 ? 'default' : 'pointer',
                  fontSize: 16,
                }}
              >🎯 試験開始</button>
            </div>
          );
        })()}

        {/* ===== 即トレ ===== */}
        {tabMode === 'drill' && (() => {
          const weakCount = (() => {
            const allProbs = drillConfig.cases.flatMap(caseId =>
              caseId === 'case4' ? FINANCE_PROBLEMS : CASE_STUDY_PROBLEMS.filter(p => p.case === caseId)
            );
            const store = { ...data.caseProgress, ...data.financeProgress };
            return allProbs.filter(p => {
              const prog = store[p.id];
              return prog && prog.attempts > 0 && prog.bestCorrect < p.steps.length;
            }).length;
          })();

          // ---- クリア画面 ----
          if (drillPhase === 'clear') {
            return (
              <div style={{ textAlign: 'center', padding: '32px 0' }}>
                <div style={{ fontSize: 48, marginBottom: 12 }}>🎉</div>
                <div style={{ fontSize: 20, fontWeight: 700, color: C.gold, marginBottom: 8 }}>3連続正解クリア！</div>
                <div style={{ fontSize: 36, fontWeight: 700, color: C.accent, marginBottom: 4 }}>
                  {drillScore.correct} / {drillScore.total}
                </div>
                <div style={{ fontSize: 13, color: C.muted, marginBottom: 24 }}>＋{drillScore.correct * 5} XP 獲得</div>
                <div style={{ display: 'flex', gap: 10, justifyContent: 'center' }}>
                  <button onClick={() => { setDrillPhase('setup'); }} style={{
                    padding: '12px 20px', borderRadius: 10, border: `1px solid ${C.accent}`,
                    background: 'transparent', color: C.accent, fontWeight: 700, cursor: 'pointer', fontSize: 14,
                  }}>⚡ もう一度</button>
                  <button onClick={() => { onDrillComplete(drillScore.correct); setDrillPhase('setup'); setTabMode('study'); }} style={{
                    padding: '12px 20px', borderRadius: 10, border: 'none',
                    background: C.accent, color: '#000', fontWeight: 700, cursor: 'pointer', fontSize: 14,
                  }}>終了</button>
                </div>
              </div>
            );
          }

          // ---- 結果画面 ----
          if (drillPhase === 'result') {
            const pct = drillScore.total > 0 ? Math.round(drillScore.correct / drillScore.total * 100) : 0;
            return (
              <div style={{ textAlign: 'center', padding: '32px 0' }}>
                <div style={{ fontSize: 40, marginBottom: 12 }}>⚡</div>
                <div style={{ fontSize: 20, fontWeight: 700, color: C.text, marginBottom: 8 }}>即トレ完了！</div>
                <div style={{ fontSize: 36, fontWeight: 700, color: C.accent, marginBottom: 4 }}>
                  {drillScore.correct} / {drillScore.total}
                </div>
                <div style={{ fontSize: 15, color: pct >= 80 ? C.green : pct >= 50 ? '#f59e0b' : C.red, fontWeight: 700, marginBottom: 4 }}>
                  正解率 {pct}%
                </div>
                <div style={{ fontSize: 13, color: C.muted, marginBottom: 24 }}>＋{drillScore.correct * 5} XP 獲得</div>
                <div style={{ display: 'flex', gap: 10, justifyContent: 'center' }}>
                  <button onClick={() => setDrillPhase('setup')} style={{
                    padding: '12px 20px', borderRadius: 10, border: `1px solid ${C.accent}`,
                    background: 'transparent', color: C.accent, fontWeight: 700, cursor: 'pointer', fontSize: 14,
                  }}>⚡ もう一度</button>
                  <button onClick={() => { onDrillComplete(drillScore.correct); setDrillPhase('setup'); setTabMode('study'); }} style={{
                    padding: '12px 20px', borderRadius: 10, border: 'none',
                    background: C.accent, color: '#000', fontWeight: 700, cursor: 'pointer', fontSize: 14,
                  }}>終了</button>
                </div>
              </div>
            );
          }

          // ---- ドリル中 ----
          if (drillPhase === 'drilling' && drillQueue.length > 0) {
            const item = drillQueue[drillIdx];
            const step = item.step;
            return (
              <div>
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 12 }}>
                  <button onClick={() => setDrillPhase('result')}
                    style={{ background: 'none', border: 'none', color: C.muted, cursor: 'pointer', fontSize: 12 }}>終了</button>
                  <div style={{ fontSize: 13, color: C.muted }}>
                    {drillIdx + 1}/{drillQueue.length}問
                    {drillScore.streak >= 2 && (
                      <span style={{ marginLeft: 8, color: C.gold, fontWeight: 700 }}>🔥 {drillScore.streak}連続</span>
                    )}
                  </div>
                  <div style={{ width: 40 }} />
                </div>
                <div style={{ background: C.card, borderRadius: 10, padding: '10px 14px', marginBottom: 12 }}>
                  <div style={{ fontSize: 11, color: C.muted, marginBottom: 4 }}>{item.problem.title}</div>
                  <div style={{ fontSize: 14, color: C.text, lineHeight: 1.6 }}>{step.question}</div>
                </div>
                <div style={{ display: 'flex', flexDirection: 'column', gap: 8, marginBottom: 12 }}>
                  {step.choices.map((choice, idx) => {
                    let bg = C.card, border = C.border, color = C.text;
                    if (drillChoice !== null) {
                      if (idx === step.correct) { bg = C.green + '22'; border = C.green; color = C.green; }
                      else if (idx === drillChoice) { bg = C.red + '22'; border = C.red; color = C.red; }
                      else { color = C.muted; }
                    }
                    return (
                      <button key={idx} onClick={() => handleDrillAnswer(idx)}
                        disabled={drillChoice !== null}
                        style={{
                          background: bg, border: `1px solid ${border}`, borderRadius: 10,
                          padding: '12px 14px', color, textAlign: 'left',
                          cursor: drillChoice === null ? 'pointer' : 'default',
                          fontSize: 13, lineHeight: 1.5,
                          fontWeight: idx === step.correct && drillChoice !== null ? 700 : 400,
                          transition: 'all 0.2s',
                        }}
                      >{choice}</button>
                    );
                  })}
                </div>
                {drillShowExp && (
                  <div style={{
                    background: drillChoice === step.correct ? C.green + '11' : C.red + '11',
                    border: `1px solid ${drillChoice === step.correct ? C.green + '44' : C.red + '44'}`,
                    borderRadius: 10, padding: 12, marginBottom: 12, fontSize: 13, color: C.text, lineHeight: 1.6,
                  }}>
                    <div style={{ fontSize: 11, fontWeight: 700, color: drillChoice === step.correct ? C.green : C.red, marginBottom: 4 }}>
                      {drillChoice === step.correct ? '✓ 正解' : '✗ 不正解'}
                    </div>
                    {step.explanation}
                  </div>
                )}
                {drillShowExp && (
                  <>
                    <PastQaPanel refId={`${item.problem.id}_${step.id}`} history={data.aiQaHistory} />
                    <button
                      onClick={() => setAiQaContext({
                        source: '即トレ',
                        refId: `${item.problem.id}_${step.id}`,
                        wasCorrect: drillChoice === step.correct,
                        questionText: step.question,
                        myAnswer: step.choices[drillChoice],
                        correctAnswer: step.choices[step.correct],
                        explanation: step.explanation,
                      })}
                      style={{
                        background: C.purple + '22', border: `1px solid ${C.purple}44`,
                        color: C.purple, borderRadius: 10, width: '100%',
                        padding: 10, fontSize: 13, marginBottom: 12, cursor: 'pointer',
                      }}
                    >🤖 AIに質問</button>
                  </>
                )}
                {drillChoice !== null && (
                  <button onClick={nextDrillQuestion} style={{
                    width: '100%', padding: '14px', borderRadius: 12, border: 'none',
                    background: C.accent, color: '#000', fontWeight: 700, cursor: 'pointer', fontSize: 15,
                  }}>
                    {drillScore.streak >= 2 && drillChoice === step.correct
                      ? `次の問題 → (あと1問で3連続クリア！)`
                      : drillIdx + 1 >= drillQueue.length ? '結果を見る' : '次の問題 →'}
                  </button>
                )}
              </div>
            );
          }

          // ---- セットアップ ----
          return (
            <div>
              <div style={{ fontSize: 15, fontWeight: 700, color: C.text, marginBottom: 4 }}>⚡ 即トレモード</div>
              <div style={{ fontSize: 13, color: C.muted, marginBottom: 20 }}>ランダムに10問出題。3連続正解でクリア！</div>

              <div style={{ background: C.card, borderRadius: 12, padding: '14px 16px', marginBottom: 14 }}>
                <div style={{ fontSize: 12, color: C.muted, marginBottom: 10 }}>出題範囲</div>
                <div style={{ display: 'flex', gap: 8 }}>
                  {[{ v: 'weak', label: '苦手のみ' }, { v: 'all', label: '全問' }].map(opt => (
                    <button key={opt.v} onClick={() => setDrillConfig(c => ({ ...c, scope: opt.v }))}
                      style={{
                        flex: 1, padding: '10px', borderRadius: 10,
                        border: `1px solid ${drillConfig.scope === opt.v ? C.accent : C.border}`,
                        background: drillConfig.scope === opt.v ? `${C.accent}22` : C.bg,
                        color: drillConfig.scope === opt.v ? C.accent : C.muted,
                        fontWeight: drillConfig.scope === opt.v ? 700 : 400,
                        cursor: 'pointer', fontSize: 13,
                      }}
                    >{opt.label}</button>
                  ))}
                </div>
                {drillConfig.scope === 'weak' && weakCount === 0 && (
                  <div style={{ fontSize: 11, color: C.muted, marginTop: 8 }}>苦手問題がまだありません。全問モードで開始します</div>
                )}
              </div>

              <div style={{ background: C.card, borderRadius: 12, padding: '14px 16px', marginBottom: 20 }}>
                <div style={{ fontSize: 12, color: C.muted, marginBottom: 10 }}>事例</div>
                <div style={{ display: 'flex', flexWrap: 'wrap', gap: 8 }}>
                  {[
                    { id: 'case1', label: '事例I' }, { id: 'case2', label: '事例II' },
                    { id: 'case3', label: '事例III' }, { id: 'case4', label: '事例IV' },
                  ].map(c => {
                    const on = drillConfig.cases.includes(c.id);
                    return (
                      <button key={c.id} onClick={() => setDrillConfig(cfg => ({
                        ...cfg,
                        cases: on ? cfg.cases.filter(x => x !== c.id) : [...cfg.cases, c.id],
                      }))} style={{
                        padding: '8px 14px', borderRadius: 20,
                        border: `1px solid ${on ? C.accent : C.border}`,
                        background: on ? `${C.accent}22` : C.bg,
                        color: on ? C.accent : C.muted, fontWeight: on ? 700 : 400,
                        cursor: 'pointer', fontSize: 13,
                      }}>{on ? '✓ ' : ''}{c.label}</button>
                    );
                  })}
                </div>
              </div>

              <button onClick={startDrill} disabled={drillConfig.cases.length === 0}
                style={{
                  width: '100%', padding: '16px', borderRadius: 12, border: 'none',
                  background: drillConfig.cases.length === 0 ? C.card : `linear-gradient(135deg, ${C.purple}, ${C.accent})`,
                  color: drillConfig.cases.length === 0 ? C.muted : '#000',
                  fontWeight: 700, cursor: drillConfig.cases.length === 0 ? 'default' : 'pointer', fontSize: 16,
                }}
              >⚡ 即トレ開始</button>
            </div>
          );
        })()}

        {/* ===== 論述（Gemini採点） ===== */}
        {tabMode === 'essay' && (() => {
          const apiKey = data.geminiApiKey || '';

          // API key 未設定画面
          if (!apiKey) {
            return (
              <div style={{ textAlign: 'center', padding: '40px 0' }}>
                <div style={{ fontSize: 40, marginBottom: 16 }}>🔑</div>
                <div style={{ fontSize: 16, fontWeight: 700, color: C.text, marginBottom: 8 }}>Gemini APIキーを設定してください</div>
                <div style={{ fontSize: 13, color: C.muted, marginBottom: 24 }}>
                  Google AI Studio（無料）でAPIキーを取得できます
                </div>
                <input
                  type="text"
                  value={essayApiInput}
                  onChange={e => setEssayApiInput(e.target.value)}
                  placeholder="AIza......"
                  style={{
                    width: '100%', padding: '12px 14px', borderRadius: 10,
                    background: C.card, border: `1px solid ${C.border}`,
                    color: C.text, fontSize: 13, marginBottom: 12, boxSizing: 'border-box',
                    outline: 'none',
                  }}
                />
                <button
                  onClick={() => { if (essayApiInput.trim()) onSaveApiKey(essayApiInput.trim()); }}
                  disabled={!essayApiInput.trim()}
                  style={{
                    width: '100%', padding: '14px', borderRadius: 12, border: 'none',
                    background: essayApiInput.trim() ? `linear-gradient(135deg, ${C.purple}, ${C.accent})` : C.card,
                    color: essayApiInput.trim() ? '#000' : C.muted,
                    fontWeight: 700, cursor: essayApiInput.trim() ? 'pointer' : 'default', fontSize: 15,
                  }}
                >保存する</button>
              </div>
            );
          }

          // フィードバック画面
          if (essayFeedback) {
            const score = essayFeedback.score ?? 0;
            const scoreColor = score >= 8 ? C.green : score >= 5 ? '#f59e0b' : C.red;
            return (
              <div>
                <div style={{ background: C.card, borderRadius: 16, padding: 20, marginBottom: 16 }}>
                  <div style={{ fontSize: 13, color: C.muted, marginBottom: 6 }}>{essayProblem.title}</div>
                  <div style={{ fontSize: 14, color: C.text, lineHeight: 1.6 }}>{essayProblem.question}</div>
                </div>
                <div style={{ background: C.card, borderRadius: 16, padding: 20, marginBottom: 16, textAlign: 'center' }}>
                  <div style={{ fontSize: 13, color: C.muted, marginBottom: 8 }}>AI採点結果</div>
                  <div style={{ fontSize: 52, fontWeight: 900, color: scoreColor }}>{score}</div>
                  <div style={{ fontSize: 14, color: C.muted }}>/ 10点</div>
                  <div style={{ fontSize: 13, color: C.gold, marginTop: 8, fontWeight: 700 }}>+{score * 3} XP</div>
                </div>
                {essayFeedback.good && (
                  <div style={{ background: '#0d2d1a', borderRadius: 12, padding: '14px 16px', marginBottom: 12, border: `1px solid ${C.green}44` }}>
                    <div style={{ fontSize: 12, color: C.green, fontWeight: 700, marginBottom: 6 }}>✓ 良かった点</div>
                    <div style={{ fontSize: 13, color: C.text, lineHeight: 1.6 }}>{essayFeedback.good}</div>
                  </div>
                )}
                {essayFeedback.improve && (
                  <div style={{ background: '#2d1a0d', borderRadius: 12, padding: '14px 16px', marginBottom: 12, border: `1px solid ${C.orange}44` }}>
                    <div style={{ fontSize: 12, color: C.orange, fontWeight: 700, marginBottom: 6 }}>△ 改善すべき点</div>
                    <div style={{ fontSize: 13, color: C.text, lineHeight: 1.6 }}>{essayFeedback.improve}</div>
                  </div>
                )}
                {essayFeedback.hint && (
                  <div style={{ background: '#1a1040', borderRadius: 12, padding: '14px 16px', marginBottom: 12, border: `1px solid ${C.purple}44` }}>
                    <div style={{ fontSize: 12, color: C.purple, fontWeight: 700, marginBottom: 6 }}>💡 解答のポイント</div>
                    <div style={{ fontSize: 13, color: '#c4b5fd', lineHeight: 1.6 }}>{essayFeedback.hint}</div>
                  </div>
                )}
                {essayProblem?.modelAnswer && (
                  <div style={{ background: '#0a1a0a', borderRadius: 12, padding: '14px 16px', marginBottom: 20, border: `1px solid ${C.green}44` }}>
                    <div style={{ fontSize: 12, color: C.green, fontWeight: 700, marginBottom: 6 }}>📄 模範解答</div>
                    <div style={{ fontSize: 13, color: '#86efac', lineHeight: 1.8, whiteSpace: 'pre-line' }}>{essayProblem.modelAnswer}</div>
                  </div>
                )}
                <div style={{ display: 'flex', gap: 10 }}>
                  <button
                    onClick={() => { setEssayFeedback(null); setEssayAnswer(''); setEssayProblem(null); }}
                    style={{
                      flex: 1, padding: '14px', borderRadius: 12, border: 'none',
                      background: C.card, color: C.muted, cursor: 'pointer', fontSize: 14,
                    }}
                  >問題一覧へ</button>
                  <button
                    onClick={() => { setEssayFeedback(null); }}
                    style={{
                      flex: 1, padding: '14px', borderRadius: 12, border: 'none',
                      background: `linear-gradient(135deg, ${C.purple}, ${C.accent})`,
                      color: '#000', fontWeight: 700, cursor: 'pointer', fontSize: 14,
                    }}
                  >もう一度解く</button>
                </div>
                <div style={{ marginTop: 16, textAlign: 'right' }}>
                  <button
                    onClick={() => onSaveApiKey('')}
                    style={{ background: 'none', border: 'none', color: C.muted, cursor: 'pointer', fontSize: 12 }}
                  >🔑 APIキーを変更</button>
                </div>
              </div>
            );
          }

          // 解答入力画面
          if (essayProblem) {
            return (
              <div>
                <button
                  onClick={() => { setEssayProblem(null); setEssayAnswer(''); }}
                  style={{ background: 'none', border: 'none', color: C.accent, cursor: 'pointer', fontSize: 14, padding: 0, marginBottom: 16 }}
                >← 問題一覧へ</button>
                <div style={{ background: C.card, borderRadius: 12, padding: '16px', marginBottom: 16 }}>
                  <div style={{ fontSize: 12, color: C.muted, marginBottom: 6 }}>{essayProblem.icon} {essayProblem.title}</div>
                  <div style={{ fontSize: 14, color: C.text, lineHeight: 1.7 }}>{essayProblem.question}</div>
                </div>
                <textarea
                  value={essayAnswer}
                  onChange={e => setEssayAnswer(e.target.value)}
                  placeholder="ここに解答を記入してください..."
                  rows={8}
                  style={{
                    width: '100%', padding: '14px', borderRadius: 12,
                    background: C.card, border: `1px solid ${C.border}`,
                    color: C.text, fontSize: 14, lineHeight: 1.7,
                    resize: 'vertical', boxSizing: 'border-box', outline: 'none',
                    marginBottom: 8,
                  }}
                />
                <div style={{ fontSize: 12, color: C.muted, marginBottom: 16, textAlign: 'right' }}>{essayAnswer.length}字</div>
                <button
                  onClick={gradeEssay}
                  disabled={essayLoading || !essayAnswer.trim()}
                  style={{
                    width: '100%', padding: '16px', borderRadius: 12, border: 'none',
                    background: (essayLoading || !essayAnswer.trim()) ? C.card : `linear-gradient(135deg, ${C.purple}, ${C.accent})`,
                    color: (essayLoading || !essayAnswer.trim()) ? C.muted : '#000',
                    fontWeight: 700, cursor: (essayLoading || !essayAnswer.trim()) ? 'default' : 'pointer', fontSize: 16,
                  }}
                >{essayLoading ? '採点中...' : '📝 AIに採点してもらう'}</button>
              </div>
            );
          }

          // 問題一覧 / 履歴切り替え
          const caseProblemMap = { case1: '事例I', case2: '事例II', case3: '事例III', case4: '事例IV' };
          const caseColors = { case1: '#7c3aed', case2: '#0ea5e9', case3: '#f59e0b', case4: '#10b981' };
          const history = data.essayHistory || [];

          return (
            <div>
              {/* 一覧 / 履歴 トグル */}
              <div style={{ display: 'flex', gap: 8, marginBottom: 16 }}>
                {[{ id: 'list', label: '📋 問題一覧' }, { id: 'history', label: `📜 解答履歴 (${history.length})` }].map(v => (
                  <button key={v.id} onClick={() => setEssayView(v.id)} style={{
                    flex: 1, padding: '8px 0', borderRadius: 20, border: 'none',
                    background: essayView === v.id ? C.accent : C.card,
                    color: essayView === v.id ? '#000' : C.muted,
                    fontWeight: essayView === v.id ? 700 : 400,
                    cursor: 'pointer', fontSize: 12,
                  }}>{v.label}</button>
                ))}
              </div>

              {/* ===== 問題一覧 ===== */}
              {essayView === 'list' && (
                <div>
                  {Object.entries(caseProblemMap).map(([caseId, caseLabel]) => {
                    const probs = ESSAY_PROBLEMS.filter(p => p.case === caseId);
                    return (
                      <div key={caseId} style={{ marginBottom: 20 }}>
                        <div style={{ fontSize: 13, fontWeight: 700, color: caseColors[caseId] || C.purple, marginBottom: 8 }}>{caseLabel}</div>
                        {probs.map(p => {
                          const attempts = history.filter(h => h.problemId === p.id);
                          const bestScore = attempts.length ? Math.max(...attempts.map(h => h.score)) : null;
                          return (
                            <button
                              key={p.id}
                              onClick={() => { setEssayProblem(p); setEssayAnswer(''); setEssayFeedback(null); }}
                              style={{
                                display: 'block', width: '100%', textAlign: 'left',
                                background: C.card, border: `1px solid ${C.border}`,
                                borderRadius: 12, padding: '14px 16px', marginBottom: 8,
                                cursor: 'pointer',
                              }}
                            >
                              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                                <div style={{ fontSize: 14, fontWeight: 600, color: C.text }}>{p.icon} {p.title}</div>
                                {bestScore !== null && (
                                  <div style={{
                                    fontSize: 12, fontWeight: 700, padding: '2px 8px', borderRadius: 8,
                                    background: bestScore >= 8 ? `${C.green}22` : bestScore >= 5 ? '#f59e0b22' : `${C.red}22`,
                                    color: bestScore >= 8 ? C.green : bestScore >= 5 ? '#f59e0b' : C.red,
                                  }}>最高 {bestScore}/10</div>
                                )}
                              </div>
                              <div style={{ fontSize: 12, color: C.muted, marginTop: 4, lineHeight: 1.5 }}>{p.question}</div>
                            </button>
                          );
                        })}
                      </div>
                    );
                  })}
                  <div style={{ marginTop: 8, textAlign: 'right' }}>
                    <button onClick={() => onSaveApiKey('')} style={{ background: 'none', border: 'none', color: C.muted, cursor: 'pointer', fontSize: 12 }}>🔑 APIキーを変更</button>
                  </div>
                </div>
              )}

              {/* ===== 解答履歴 ===== */}
              {essayView === 'history' && (
                history.length === 0 ? (
                  <div style={{ padding: '60px 0', textAlign: 'center', color: C.muted }}>
                    <div style={{ fontSize: 40, marginBottom: 12 }}>📝</div>
                    <div>まだ解答履歴がありません</div>
                  </div>
                ) : (
                  <div>
                    {[...history].reverse().map(h => {
                      const scoreColor = h.score >= 8 ? C.green : h.score >= 5 ? '#f59e0b' : C.red;
                      return (
                        <HistoryEssayCard key={h.id} item={h} scoreColor={scoreColor} caseColors={caseColors} caseProblemMap={caseProblemMap} />
                      );
                    })}
                  </div>
                )
              )}
            </div>
          );
        })()}

        {/* ===== 演習（既存） ===== */}
        {tabMode === 'study' && <>
        <div style={{ fontSize: 18, fontWeight: 700, color: C.text, marginBottom: 2 }}>
          {caseTitles[selectedCase]}
        </div>
        <div style={{ fontSize: 13, color: C.muted, marginBottom: 12 }}>ステップ別選択問題</div>

        {/* Case selector */}
        <div style={{ display: 'flex', gap: 6, marginBottom: 14, flexWrap: 'wrap' }}>
          {caseSelectors.map(cs => (
            <button
              key={cs.id}
              onClick={() => { setSelectedCase(cs.id); setFilterType('all'); setFilterDifficulty('all'); }}
              style={{
                padding: '6px 12px', borderRadius: 20, border: 'none',
                background: selectedCase === cs.id ? C.purple : C.card,
                color: selectedCase === cs.id ? '#fff' : C.muted,
                fontWeight: selectedCase === cs.id ? 700 : 400,
                cursor: 'pointer', fontSize: 12,
              }}
            >{cs.label} <span style={{ fontSize: 10, opacity: 0.75 }}>{cs.sub}</span></button>
          ))}
        </div>

        {/* Type filter (case4 only) */}
        {!isCaseStudy && (
        <div style={{ display: 'flex', gap: 6, marginBottom: 8, flexWrap: 'wrap' }}>
          {filterTypes.map(ft => (
            <button
              key={ft.id}
              onClick={() => setFilterType(ft.id)}
              style={{
                padding: '6px 12px', borderRadius: 20, border: 'none',
                background: filterType === ft.id ? C.accent : C.card,
                color: filterType === ft.id ? '#000' : C.muted,
                fontWeight: filterType === ft.id ? 700 : 400,
                cursor: 'pointer', fontSize: 12,
              }}
            >{ft.label}</button>
          ))}
        </div>
        )}

        {/* Difficulty filter */}
        <div style={{ display: 'flex', gap: 6, marginBottom: 16 }}>
          {[
            { id: 'all', label: 'すべて' },
            { id: '基礎', label: '⭐ 基礎' },
            { id: '応用', label: '⭐⭐ 応用' },
          ].map(df => (
            <button
              key={df.id}
              onClick={() => setFilterDifficulty(df.id)}
              style={{
                padding: '5px 12px', borderRadius: 20, border: 'none',
                background: filterDifficulty === df.id ? C.gold : C.card,
                color: filterDifficulty === df.id ? '#000' : C.muted,
                fontWeight: filterDifficulty === df.id ? 700 : 400,
                cursor: 'pointer', fontSize: 12,
              }}
            >{df.label}</button>
          ))}
        </div>

        {/* Problem cards */}
        <div style={{ display: 'flex', flexDirection: 'column', gap: 10 }}>
          {filtered.map(p => {
            const prog = getProblemProgress(p.id, isCaseStudy);
            const typeColor = (isCaseStudy ? CASE_TYPE_COLORS : FINANCE_TYPE_COLORS)[p.type] || C.muted;
            const typeLabel = (isCaseStudy ? CASE_TYPE_LABELS : FINANCE_TYPE_LABELS)[p.type];
            return (
              <div
                key={p.id}
                onClick={() => startProblem(p)}
                style={{
                  background: prog.completed ? '#0a1f0a' : C.card,
                  border: `1px solid ${prog.completed ? C.green + '66' : C.border}`,
                  borderRadius: 14, padding: '14px 16px',
                  cursor: 'pointer', display: 'flex', alignItems: 'center', gap: 12,
                }}
              >
                <div style={{ fontSize: 26 }}>{p.icon}</div>
                <div style={{ flex: 1, minWidth: 0 }}>
                  <div style={{ display: 'flex', alignItems: 'center', gap: 6, marginBottom: 4 }}>
                    <span style={{
                      fontSize: 10, fontWeight: 700, color: typeColor,
                      background: typeColor + '22', borderRadius: 4, padding: '2px 6px',
                    }}>{typeLabel}</span>
                    {p.difficulty === '応用' && (
                      <span style={{
                        fontSize: 10, fontWeight: 700, color: C.gold,
                        background: C.gold + '22', borderRadius: 4, padding: '2px 6px',
                      }}>⭐⭐ 応用</span>
                    )}
                    {data.reviewSchedule?.[p.id]?.nextDate <= todayStr() && (
                      <span style={{
                        fontSize: 10, fontWeight: 700, color: C.orange,
                        background: C.orange + '22', borderRadius: 4, padding: '2px 6px',
                      }}>🔔 要復習</span>
                    )}
                  </div>
                  <div style={{ fontSize: 14, fontWeight: 600, color: C.text }}>{p.title}</div>
                  <div style={{ fontSize: 11, color: C.muted, marginTop: 2 }}>
                    {p.steps.length}ステップ · ＋{p.xp} XP
                  </div>
                </div>
                <div style={{ textAlign: 'right', flexShrink: 0 }}>
                  <StarRating mastery={getMastery(prog, p.steps.length)} size={13} />
                  <div style={{ marginTop: 4 }}>
                    {prog.completed ? (
                      <div style={{ fontSize: 20, color: C.green }}>✓</div>
                    ) : prog.attempts > 0 ? (
                      <div style={{ fontSize: 12, color: C.muted }}>
                        {prog.bestCorrect}/{p.steps.length}
                      </div>
                    ) : (
                      <div style={{ width: 20, height: 20, borderRadius: '50%', border: `2px solid ${C.border}`, margin: '0 auto' }} />
                    )}
                  </div>
                </div>
              </div>
            );
          })}
        </div>
        </>}

        {aiQaContext && (
          <AiQuestionModal
            context={aiQaContext}
            apiKey={data.geminiApiKey || ''}
            onSave={(qa) => { onSaveAiQa({ ...aiQaContext, ...qa }); setAiQaContext(null); }}
            onClose={() => setAiQaContext(null)}
          />
        )}
      </div>
    );
  }

  const step = activeProblem?.steps[currentStep];
  const totalSteps = activeProblem?.steps.length || 0;

  // ---- Completion screen ----
  if (solverDone) {
    const correctCount = stepResults.filter(Boolean).length;
    const perfect = correctCount === totalSteps;
    return (
      <div style={{ padding: '16px 16px 80px' }}>
        <button
          onClick={() => { setView('list'); resetSolver(); setActiveProblem(null); }}
          style={{ background: 'none', border: 'none', color: C.accent, cursor: 'pointer', fontSize: 22, padding: 0, marginBottom: 20 }}
        >←</button>
        <div style={{
          textAlign: 'center', padding: '32px 20px',
          background: C.card, borderRadius: 16, border: `1px solid ${C.border}`,
        }}>
          <div style={{ fontSize: 48, marginBottom: 12 }}>{perfect ? '🎉' : '📝'}</div>
          <div style={{ fontSize: 20, fontWeight: 700, color: perfect ? C.gold : C.text, marginBottom: 8 }}>
            {perfect ? '全問正解！' : '結果'}
          </div>
          <div style={{ fontSize: 36, fontWeight: 700, color: perfect ? C.gold : C.accent, marginBottom: 4 }}>
            {correctCount} / {totalSteps}
          </div>
          <div style={{ fontSize: 13, color: C.muted, marginBottom: 24 }}>
            {perfect ? `＋${activeProblem.xp} XP 獲得！` : `＋${correctCount * activeProblem.partialXp} XP 獲得`}
          </div>
          <div style={{ display: 'flex', justifyContent: 'center', gap: 8, marginBottom: 28 }}>
            {stepResults.map((ok, i) => (
              <div key={i} style={{
                width: 34, height: 34, borderRadius: '50%',
                background: ok ? C.green : C.red,
                display: 'flex', alignItems: 'center', justifyContent: 'center',
                fontSize: 16, color: '#fff', fontWeight: 700,
              }}>{ok ? '✓' : '✗'}</div>
            ))}
          </div>
          <div style={{ display: 'flex', gap: 10, justifyContent: 'center' }}>
            <button
              onClick={() => startProblem(activeProblem)}
              style={{
                padding: '12px 20px', borderRadius: 10, border: `1px solid ${C.accent}`,
                background: 'transparent', color: C.accent,
                fontWeight: 700, cursor: 'pointer', fontSize: 14,
              }}
            >もう一度</button>
            <button
              onClick={() => { setView('list'); resetSolver(); setActiveProblem(null); }}
              style={{
                padding: '12px 20px', borderRadius: 10, border: 'none',
                background: C.accent, color: '#000',
                fontWeight: 700, cursor: 'pointer', fontSize: 14,
              }}
            >問題一覧へ</button>
          </div>
        </div>

        {aiQaContext && (
          <AiQuestionModal
            context={aiQaContext}
            apiKey={data.geminiApiKey || ''}
            onSave={(qa) => { onSaveAiQa({ ...aiQaContext, ...qa }); setAiQaContext(null); }}
            onClose={() => setAiQaContext(null)}
          />
        )}
      </div>
    );
  }

  // ---- Solver view ----
  return (
    <div style={{ padding: '16px 16px 80px' }}>
      {/* Header */}
      <div style={{ display: 'flex', alignItems: 'center', gap: 12, marginBottom: 16 }}>
        <button
          onClick={() => { setView('list'); resetSolver(); setActiveProblem(null); }}
          style={{ background: 'none', border: 'none', color: C.accent, cursor: 'pointer', fontSize: 22, padding: 0 }}
        >←</button>
        <div style={{ flex: 1 }}>
          <div style={{ fontSize: 14, fontWeight: 700, color: C.text }}>{activeProblem?.title}</div>
          <div style={{ fontSize: 12, color: C.muted }}>Step {currentStep + 1} / {totalSteps}</div>
        </div>
      </div>

      {/* Progress bar */}
      <div style={{ height: 4, background: C.border, borderRadius: 2, marginBottom: 16 }}>
        <div style={{
          height: '100%', width: `${(currentStep / totalSteps) * 100}%`,
          background: C.accent, borderRadius: 2, transition: 'width 0.3s',
        }} />
      </div>

      {/* Problem intro */}
      <div style={{
        background: C.purple + '11', border: `1px solid ${C.purple}33`,
        borderRadius: 12, padding: 14, marginBottom: 16,
        fontSize: 13, color: C.text, lineHeight: 1.7,
      }}>
        <div style={{ fontSize: 11, color: C.purple, fontWeight: 700, marginBottom: 6 }}>問題文</div>
        {activeProblem?.intro}
      </div>

      {/* Step question */}
      <div style={{
        background: C.card, border: `1px solid ${C.accent}44`,
        borderRadius: 12, padding: 16, marginBottom: 16,
      }}>
        <div style={{ fontSize: 14, fontWeight: 600, color: C.text, lineHeight: 1.7 }}>
          {step?.question}
        </div>
      </div>

      {/* Choices */}
      <div style={{ display: 'flex', flexDirection: 'column', gap: 8, marginBottom: 16 }}>
        {step?.choices.map((choice, idx) => {
          let bg = C.card, border = C.border, color = C.text;
          if (selectedChoice !== null) {
            if (idx === step.correct) {
              bg = C.green + '22'; border = C.green; color = C.green;
            } else if (idx === selectedChoice) {
              bg = C.red + '22'; border = C.red; color = C.red;
            } else {
              color = C.muted;
            }
          }
          return (
            <button
              key={idx}
              onClick={() => handleChoiceSelect(idx)}
              disabled={selectedChoice !== null}
              style={{
                background: bg, border: `1px solid ${border}`,
                borderRadius: 10, padding: '12px 14px',
                color, textAlign: 'left',
                cursor: selectedChoice === null ? 'pointer' : 'default',
                fontSize: 13, lineHeight: 1.5,
                fontWeight: idx === step.correct && selectedChoice !== null ? 700 : 400,
                transition: 'all 0.2s',
              }}
            >{choice}</button>
          );
        })}
      </div>

      {/* Explanation */}
      {showExplanation && (
        <div style={{
          background: selectedChoice === step.correct ? C.green + '11' : C.red + '11',
          border: `1px solid ${selectedChoice === step.correct ? C.green + '44' : C.red + '44'}`,
          borderRadius: 12, padding: 14, marginBottom: 16,
          fontSize: 13, color: C.text, lineHeight: 1.7,
        }}>
          <div style={{
            fontSize: 11, fontWeight: 700, marginBottom: 6,
            color: selectedChoice === step.correct ? C.green : C.red,
          }}>
            {selectedChoice === step.correct ? '✓ 正解！' : '✗ 不正解'}
          </div>
          {step?.explanation}
        </div>
      )}

      {/* AIに質問 */}
      {showExplanation && (
        <>
          <PastQaPanel refId={`${activeProblem.id}_${step.id}`} history={data.aiQaHistory} />
          <button
            onClick={() => setAiQaContext({
              source: '演習',
              refId: `${activeProblem.id}_${step.id}`,
              wasCorrect: selectedChoice === step.correct,
              questionText: step.question,
              myAnswer: step.choices[selectedChoice],
              correctAnswer: step.choices[step.correct],
              explanation: step.explanation,
            })}
            style={{
              background: C.purple + '22', border: `1px solid ${C.purple}44`,
              color: C.purple, borderRadius: 10, width: '100%',
              padding: 10, fontSize: 13, marginBottom: 16, cursor: 'pointer',
            }}
          >🤖 AIに質問</button>
        </>
      )}

      {/* Next button */}
      {showExplanation && (
        <button
          onClick={handleNext}
          style={{
            width: '100%', padding: 14,
            background: `linear-gradient(135deg, ${C.purple}, ${C.accent})`,
            border: 'none', borderRadius: 12,
            color: '#fff', fontWeight: 700, fontSize: 15, cursor: 'pointer',
          }}
        >
          {currentStep + 1 >= totalSteps ? '結果を見る →' : '次へ →'}
        </button>
      )}

      {aiQaContext && (
        <AiQuestionModal
          context={aiQaContext}
          apiKey={data.geminiApiKey || ''}
          onSave={(qa) => { onSaveAiQa({ ...aiQaContext, ...qa }); setAiQaContext(null); }}
          onClose={() => setAiQaContext(null)}
        />
      )}
    </div>
  );
}

// ============================================================
// BottomNav
// ============================================================

function BottomNav({ active, onChange, remainingCount }) {
  const tabs = [
    { id: 'quest',      label: 'クエスト', icon: '⚔️' },
    { id: 'procedure',  label: '手順',     icon: '📋' },
    { id: 'reflection', label: '振り返り', icon: '📝' },
    { id: 'history',    label: '履歴',     icon: '📜' },
    { id: 'finance',    label: '演習',     icon: '📚' },
  ];

  return (
    <div style={{
      position: 'fixed', bottom: 0, left: 0, right: 0,
      background: '#0d1117', borderTop: `1px solid ${C.border}`,
      display: 'flex', height: 60,
      maxWidth: 480, margin: '0 auto',
    }}>
      {tabs.map(tab => (
        <button
          key={tab.id}
          onClick={() => onChange(tab.id)}
          style={{
            flex: 1, display: 'flex', flexDirection: 'column',
            alignItems: 'center', justifyContent: 'center', gap: 2,
            background: 'none', border: 'none', cursor: 'pointer',
            color: active === tab.id ? C.accent : C.muted,
            borderTop: active === tab.id ? `2px solid ${C.accent}` : '2px solid transparent',
          }}
        >
          <div style={{ position: 'relative', display: 'inline-flex' }}>
            <span style={{ fontSize: 18 }}>{tab.icon}</span>
            {tab.id === 'quest' && remainingCount > 0 && (
              <div style={{
                position: 'absolute', top: -4, right: -8,
                background: C.red, borderRadius: '50%',
                minWidth: 16, height: 16, padding: '0 2px',
                fontSize: 10, fontWeight: 700, color: '#fff',
                display: 'flex', alignItems: 'center', justifyContent: 'center',
              }}>
                {remainingCount}
              </div>
            )}
          </div>
          <span style={{ fontSize: 9, fontWeight: active === tab.id ? 700 : 400 }}>
            {tab.label}
          </span>
        </button>
      ))}
    </div>
  );
}

// ============================================================
// LoginGreetingModal
// ============================================================

function LoginGreetingModal({ streak, onClose }) {
  const hour = new Date().getHours();
  const greeting =
    hour >= 5 && hour < 11 ? 'おはようございます！ ☀️' :
    hour >= 11 && hour < 17 ? 'こんにちは！ 🌤️' :
    hour >= 17 && hour < 21 ? 'こんばんは！ 🌙' : 'お疲れ様！ 🌙';

  const streakMsg =
    streak === 0 ? '久しぶり！また頑張ろう！' :
    streak === 1 ? '昨日に続いて来たね！いいね！' :
    streak < 3   ? `${streak}日連続！いいリズム！` :
    streak < 7   ? `${streak}日連続！習慣になってきた！` :
    streak < 14  ? '1週間以上！本物の受験生！' :
    streak < 30  ? '2週間以上！絶好調！' :
                   '1ヶ月連続！合格目指して最後まで！';

  const today = new Date();
  const dateStr = today.toLocaleDateString('ja-JP', { year: 'numeric', month: 'long', day: 'numeric', weekday: 'short' });

  return (
    <div style={{
      position: 'fixed', inset: 0, background: 'rgba(0,0,0,0.85)',
      display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 3000,
    }} onClick={onClose}>
      <div onClick={(e) => e.stopPropagation()} style={{
        background: 'linear-gradient(135deg, #0d1a2e, #1a1040)',
        border: `2px solid ${C.gold}`,
        borderRadius: 24, padding: '36px 32px',
        textAlign: 'center', minWidth: 290, maxWidth: 340,
        boxShadow: `0 0 60px ${C.gold}33`,
      }}>
        <div style={{ fontSize: 22, fontWeight: 700, color: C.text, marginBottom: 20 }}>{greeting}</div>
        {streak > 0 && (
          <div style={{
            fontSize: 32, fontWeight: 700, marginBottom: 8,
            background: `linear-gradient(135deg, ${C.orange}, ${C.gold})`,
            WebkitBackgroundClip: 'text', WebkitTextFillColor: 'transparent',
          }}>🔥 {streak}日連続！</div>
        )}
        <div style={{ fontSize: 16, color: C.accent, fontWeight: 600, marginBottom: 20 }}>{streakMsg}</div>
        <div style={{ fontSize: 12, color: C.muted, marginBottom: 28 }}>{dateStr}</div>
        <button onClick={onClose} style={{
          width: '100%', padding: '14px 0', borderRadius: 14, border: 'none',
          background: `linear-gradient(135deg, ${C.purple}, ${C.accent})`,
          color: '#000', fontWeight: 700, fontSize: 16, cursor: 'pointer',
        }}>よし、始めよう！ →</button>
      </div>
    </div>
  );
}

// ============================================================
// StampAnimation
// ============================================================

function StampAnimation({ type, onClose }) {
  useEffect(() => {
    const t = setTimeout(onClose, 2200);
    return () => clearTimeout(t);
  }, [onClose]);

  const isEvolved = type === 'evolved';
  const emoji = isEvolved ? '🌟' : '⭐';
  const label = isEvolved ? 'スタンプ進化！' : '今日のスタンプ獲得！';

  return (
    <div onClick={onClose} style={{
      position: 'fixed', inset: 0, background: 'rgba(0,0,0,0.75)',
      display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center',
      zIndex: 2500,
    }}>
      <style>{`
        @keyframes stampPress {
          0%   { transform: scale(2.2); opacity: 0; }
          40%  { transform: scale(0.85); opacity: 1; }
          65%  { transform: scale(1.1); }
          100% { transform: scale(1.0); opacity: 1; }
        }
        @keyframes stampLabel {
          0%   { opacity: 0; transform: translateY(10px); }
          60%  { opacity: 0; transform: translateY(10px); }
          100% { opacity: 1; transform: translateY(0); }
        }
      `}</style>
      <div style={{
        fontSize: 90,
        animation: 'stampPress 0.55s cubic-bezier(0.22,1,0.36,1) forwards',
        filter: isEvolved ? 'drop-shadow(0 0 20px #ffd700)' : 'drop-shadow(0 0 16px #10b981)',
      }}>{emoji}</div>
      <div style={{
        fontSize: 20, fontWeight: 700, marginTop: 16,
        color: isEvolved ? C.gold : C.green,
        animation: 'stampLabel 0.8s ease forwards',
      }}>{label}</div>
      <div style={{ fontSize: 12, color: C.muted, marginTop: 8, animation: 'stampLabel 1s ease forwards' }}>
        タップで閉じる
      </div>
    </div>
  );
}

// ============================================================
// MonthlyStampCalendar
// ============================================================

function MonthlyStampCalendar({ stampCalendar }) {
  const now = new Date();
  const [viewYear,  setViewYear]  = useState(now.getFullYear());
  const [viewMonth, setViewMonth] = useState(now.getMonth()); // 0-based

  const todayStr2 = `${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}-${String(now.getDate()).padStart(2,'0')}`;
  const monthLabel = new Date(viewYear, viewMonth, 1).toLocaleDateString('ja-JP', { year: 'numeric', month: 'long' });
  const daysInMonth = new Date(viewYear, viewMonth + 1, 0).getDate();
  const firstDow    = new Date(viewYear, viewMonth, 1).getDay(); // 0=Sun

  function prevMonth() {
    if (viewMonth === 0) { setViewYear(y => y - 1); setViewMonth(11); }
    else setViewMonth(m => m - 1);
  }
  function nextMonth() {
    const isCurrentMonth = viewYear === now.getFullYear() && viewMonth === now.getMonth();
    if (isCurrentMonth) return;
    if (viewMonth === 11) { setViewYear(y => y + 1); setViewMonth(0); }
    else setViewMonth(m => m + 1);
  }

  const isCurrentMonth = viewYear === now.getFullYear() && viewMonth === now.getMonth();

  const cells = [];
  for (let i = 0; i < firstDow; i++) cells.push(null);
  for (let d = 1; d <= daysInMonth; d++) cells.push(d);

  return (
    <div style={{ marginBottom: 20 }}>
      {/* Header */}
      <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: 10 }}>
        <button onClick={prevMonth} style={{ background: 'none', border: 'none', color: C.muted, cursor: 'pointer', fontSize: 18, padding: '0 8px' }}>◀</button>
        <div style={{ fontSize: 13, fontWeight: 700, color: C.text }}>📅 {monthLabel}</div>
        <button onClick={nextMonth} style={{
          background: 'none', border: 'none',
          color: isCurrentMonth ? '#333' : C.muted,
          cursor: isCurrentMonth ? 'default' : 'pointer', fontSize: 18, padding: '0 8px',
        }}>▶</button>
      </div>
      {/* Day-of-week headers */}
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(7,1fr)', gap: 3, marginBottom: 3 }}>
        {['日','月','火','水','木','金','土'].map((d, i) => (
          <div key={d} style={{
            fontSize: 10, textAlign: 'center', color: i === 0 ? '#f87171' : i === 6 ? '#60a5fa' : C.muted,
            fontWeight: 700,
          }}>{d}</div>
        ))}
      </div>
      {/* Date cells */}
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(7,1fr)', gap: 3 }}>
        {cells.map((day, idx) => {
          if (!day) return <div key={`e${idx}`} />;
          const dateKey = `${viewYear}-${String(viewMonth+1).padStart(2,'0')}-${String(day).padStart(2,'0')}`;
          const isToday = dateKey === todayStr2;
          const stamp   = (stampCalendar || {})[dateKey]; // 1 or 2
          const isFuture = !isToday && new Date(viewYear, viewMonth, day) > now;

          return (
            <div key={dateKey} style={{
              aspectRatio: '1', display: 'flex', flexDirection: 'column',
              alignItems: 'center', justifyContent: 'center',
              borderRadius: 8,
              background: stamp === 2 ? `${C.gold}22` : stamp === 1 ? `${C.green}22` : 'transparent',
              border: isToday && !stamp ? `1.5px solid ${C.accent}` : isToday && stamp ? `1.5px solid ${stamp === 2 ? C.gold : C.green}` : '1.5px solid transparent',
              boxShadow: isToday && stamp ? `0 0 8px ${stamp === 2 ? C.gold : C.green}66` : 'none',
              opacity: isFuture ? 0.2 : 1,
            }}>
              {stamp ? (
                <div style={{ fontSize: 16, lineHeight: 1 }}>{stamp === 2 ? '🌟' : '⭐'}</div>
              ) : (
                <div style={{ fontSize: 11, color: isToday ? C.accent : C.muted, fontWeight: isToday ? 700 : 400 }}>{day}</div>
              )}
            </div>
          );
        })}
      </div>
    </div>
  );
}

// ============================================================
// App
// ============================================================

export default function App() {
  const [tab,      setTab]      = useState('quest');
  const [data,     setData]     = useState(() => applyDateReset(loadData()));
  const [reward,   setReward]   = useState(null);
  const [particles, setParticles] = useState(null);
  const [levelUp,  setLevelUp]  = useState(null);
  const [pendingProblem, setPendingProblem] = useState(null);
  const [showGreeting, setShowGreeting] = useState(false);
  const [showStamp, setShowStamp] = useState(null); // null | 'basic' | 'evolved'

  useEffect(() => {
    if (loadData().lastDate !== todayStr()) setShowGreeting(true);
  }, []);

  function commit(newData) {
    setData(newData);
    saveData(newData);
  }

  function buildHistoryItem(icon, name, xp, elapsed) {
    const item = { icon, name, xp, time: formatDateTime() };
    if (elapsed != null && elapsed > 0) item.elapsed = elapsed;
    return item;
  }

  function applyXpGain(base, xp, historyItem) {
    const today     = todayStr();
    const weekStart = getWeekStart();
    const dayIdx    = getDayIndex();
    let d = { ...base };

    if (d.weekStart !== weekStart) {
      const currentWeekXp = (d.weeklyXpData || []).reduce((a, b) => a + b, 0);
      if (currentWeekXp > 0) {
        const wh = [...(d.weeklyXpHistory || []), currentWeekXp];
        d.weeklyXpHistory = wh.slice(-8);
      }
      d.weeklyData   = [0, 0, 0, 0, 0, 0, 0];
      d.weeklyXpData = [0, 0, 0, 0, 0, 0, 0];
      d.weekStart    = weekStart;
    }
    if (d.lastDate !== today) {
      const yesterday = new Date();
      yesterday.setDate(yesterday.getDate() - 1);
      d.streak = d.lastDate === localDateStr(yesterday) ? (d.streak || 0) + 1 : 0;
      d.completedToday = [];
    }

    d.xp         = (d.xp || 0) + xp;
    d.totalTasks = (d.totalTasks || 0) + 1;
    d.lastDate   = today;

    const weekly = [...(d.weeklyData || [0, 0, 0, 0, 0, 0, 0])];
    weekly[dayIdx] = (weekly[dayIdx] || 0) + 1;
    d.weeklyData = weekly;

    const xpData = [...(d.weeklyXpData || [0, 0, 0, 0, 0, 0, 0])];
    xpData[dayIdx] = (xpData[dayIdx] || 0) + xp;
    d.weeklyXpData = xpData;

    const hist = [...(d.history || []), historyItem];
    d.history = hist.length > 40 ? hist.slice(-40) : hist;

    const prevDay = (d.dailyLog || {})[today] || { tasks: 0, xp: 0 };
    d.dailyLog = { ...(d.dailyLog || {}), [today]: { tasks: prevDay.tasks + 1, xp: prevDay.xp + xp } };

    return d;
  }

  function handleCompleteQuest(quest, elapsed) {
    if (data.completedToday.includes(quest.id)) return;
    const today = todayStr();
    const prevLevel = getLevel(data.xp);
    const hi = buildHistoryItem(quest.icon, quest.name, quest.xp, elapsed);
    let d = applyXpGain(data, quest.xp, hi);
    d.completedToday = [...(d.completedToday || []), quest.id];

    // スタンプ: その日最初のタスク完了 → 基本スタンプ
    const cal = d.stampCalendar || {};
    if (data.completedToday.length === 0 && !cal[today]) {
      d.stampCalendar = { ...cal, [today]: 1 };
      setTimeout(() => setShowStamp('basic'), 3200);
    }

    const missions = getDailyMissions(today);
    const allMissionsDone = missions.every(id => d.completedToday.includes(id));
    let bonusXp = 0;
    if (allMissionsDone && d.dailyMissionBonus !== today) {
      d.dailyMissionBonus = today;
      bonusXp = 150;
      d.xp = (d.xp || 0) + bonusXp;
      // スタンプ進化
      d.stampCalendar = { ...(d.stampCalendar || {}), [today]: 2 };
      setTimeout(() => setShowStamp('evolved'), 5200);
    }

    commit(d);
    const newLevel = getLevel(d.xp);
    if (newLevel.lv > prevLevel.lv) setLevelUp(newLevel);

    if (bonusXp > 0) {
      setTimeout(() => {
        setReward({ icon: '🎯', title: 'デイリーミッション達成！', xp: bonusXp, message: '3つのミッションをクリア！' });
        setParticles(bonusXp);
      }, 1600);
    }

    setReward({ icon: quest.icon, title: quest.name, xp: quest.xp, message: 'クエスト完了！' });
    setParticles(quest.xp);
  }

  function handleCompleteCase(caseItem) {
    const xp        = 100;
    const prevLevel = getLevel(data.xp);
    const hi = buildHistoryItem('🎯', `${caseItem.full} クリア`, xp);
    const d  = applyXpGain(data, xp, hi);
    commit(d);
    const newLevel = getLevel(d.xp);
    if (newLevel.lv > prevLevel.lv) setLevelUp(newLevel);
    setReward({ icon: '🎯', title: `${caseItem.full} クリア！`, xp, message: '手順ガイド完了！' });
    setParticles(xp);
    navigator.vibrate?.([100, 50, 100]);
  }

  function handleEssayComplete(score) {
    const xp = score * 3;
    if (xp <= 0) return;
    const prevLevel = getLevel(data.xp);
    const hi = buildHistoryItem('📝', `論述採点 ${score}/10点`, xp);
    const d = applyXpGain(data, xp, hi);
    commit(d);
    const newLevel = getLevel(d.xp);
    if (newLevel.lv > prevLevel.lv) setLevelUp(newLevel);
    setReward({ icon: '📝', title: '論述採点完了！', xp, message: `${score}/10点` });
    setParticles(xp);
  }

  function handleSaveApiKey(key) {
    const d = { ...data, geminiApiKey: key };
    commit(d);
  }

  function handleSaveEssayHistory(entry) {
    const d = { ...data, essayHistory: [...(data.essayHistory || []), entry] };
    commit(d);
  }

  function handleSaveAiQa(entry) {
    const item = {
      ...entry,
      id: Date.now(),
      memo: '',
      date: new Date().toLocaleDateString('ja-JP', { month: 'numeric', day: 'numeric', hour: '2-digit', minute: '2-digit' }),
    };
    commit({ ...data, aiQaHistory: [...(data.aiQaHistory || []), item] });
  }

  function handleUpdateAiQaMemo(id, memo) {
    commit({ ...data, aiQaHistory: (data.aiQaHistory || []).map(x => x.id === id ? { ...x, memo } : x) });
  }

  function handleDeleteAiQa(id) {
    commit({ ...data, aiQaHistory: (data.aiQaHistory || []).filter(x => x.id !== id) });
  }

  // シグナルワード演習：マスタリー更新＋ベストスコア更新＋XP付与
  function handleSignalComplete({ mode, correct, total, maxStreak, results }) {
    let d = { ...data };

    // 1問ごとのマスタリー（連続正解でstreakが伸び、間違えると0に戻る）
    const mastery = { ...(d.signalMastery || {}) };
    (results || []).forEach(r => {
      const prev = mastery[r.id] || { correct: 0, wrong: 0, streak: 0 };
      mastery[r.id] = r.ok
        ? { correct: prev.correct + 1, wrong: prev.wrong, streak: prev.streak + 1 }
        : { correct: prev.correct, wrong: prev.wrong + 1, streak: 0 };
    });
    d.signalMastery = mastery;

    // ベストスコア更新
    const best = { ...(d.signalBest || {}) };
    let newRecord = false;
    if (mode === 'attack' || mode === 'highlight') {
      if (correct > (best[mode] || 0)) { best[mode] = correct; newRecord = true; }
      d.signalBest = best;
    }

    // XP：1正解3XP＋最大連続ボーナス（連続5以上で+20XP）
    const bonus = maxStreak >= 5 ? 20 : 0;
    const xp = correct * 3 + bonus;
    if (xp <= 0) { commit(d); return; }

    const modeLabel = mode === 'attack' ? '60秒タイムアタック' : mode === 'highlight' ? 'ハイライト演習' : 'シグナル即答';
    const prevLevel = getLevel(d.xp);
    const hi = buildHistoryItem('🚦', `${modeLabel} ${correct}/${total}`, xp);
    d = applyXpGain(d, xp, hi);
    commit(d);
    const newLevel = getLevel(d.xp);
    if (newLevel.lv > prevLevel.lv) setLevelUp(newLevel);
    setReward({
      icon: newRecord ? '🏆' : '🚦',
      title: newRecord ? `自己ベスト更新！ ${modeLabel}` : `${modeLabel}完了！`,
      xp,
      message: bonus > 0 ? `${correct}/${total}正解・${maxStreak}連続ボーナス！` : `${correct}/${total}正解`,
    });
    setParticles(xp);
  }

  // プロセス演習：到達ステップの更新＋XP付与
  function handleProcessComplete({ correct, total, perfect, results }) {
    let d = { ...data };
    const prog = { ...(d.processProgress || {}) };
    (results || []).forEach(r => {
      const okCount = r.steps.filter(Boolean).length;
      const prev = prog[r.id] || { attempts: 0, bestSteps: 0 };
      prog[r.id] = { attempts: prev.attempts + 1, bestSteps: Math.max(prev.bestSteps, okCount) };
    });
    d.processProgress = prog;

    // XP：1ステップ正解5XP ＋ 全4ステップ正解の問題ごとに +20XP
    const xp = correct * 5 + perfect * 20;
    if (xp <= 0) { commit(d); return; }

    const prevLevel = getLevel(d.xp);
    const hi = buildHistoryItem('🎯', `プロセス演習 ${correct}/${total}ステップ`, xp);
    d = applyXpGain(d, xp, hi);
    commit(d);
    const newLevel = getLevel(d.xp);
    if (newLevel.lv > prevLevel.lv) setLevelUp(newLevel);
    setReward({
      icon: perfect > 0 ? '🏅' : '🎯',
      title: 'プロセス演習完了！',
      xp,
      message: perfect > 0 ? `${correct}/${total}ステップ・完答${perfect}問！` : `${correct}/${total}ステップ正解`,
    });
    setParticles(xp);
  }

  // 写経：実施回数と最高網羅率を更新＋XP付与
  function handleWritingComplete({ mode, probId, coverage, hintsUsed, xp }) {
    let d = { ...data };
    const prog = { ...(d.writingProgress || {}) };
    const prev = prog[probId] || { copied: 0, recalled: 0, bestCoverage: null };
    prog[probId] = mode === 'copy'
      ? { ...prev, copied: prev.copied + 1 }
      : { ...prev, recalled: prev.recalled + 1, bestCoverage: Math.max(prev.bestCoverage ?? 0, coverage) };
    d.writingProgress = prog;

    if (!xp || xp <= 0) { commit(d); return; }

    const label = mode === 'copy' ? '写し書き' : '記憶で書く';
    const prevLevel = getLevel(d.xp);
    const msg = mode === 'copy' ? '書き写し完了' : `キーワード${coverage}%`;
    const hi = buildHistoryItem('✍️', `${label} ${msg}`, xp);
    d = applyXpGain(d, xp, hi);
    commit(d);
    const newLevel = getLevel(d.xp);
    if (newLevel.lv > prevLevel.lv) setLevelUp(newLevel);
    setReward({
      icon: '✍️',
      title: `${label}完了！`,
      xp,
      message: hintsUsed > 0 ? `${msg}・ヒント${hintsUsed}段階` : msg,
    });
    setParticles(xp);
  }

  function handleDrillComplete(correctCount) {
    const xp = correctCount * 5;
    if (xp <= 0) return;
    const prevLevel = getLevel(data.xp);
    const hi = buildHistoryItem('⚡', `即トレ ${correctCount}問正解`, xp);
    const d = applyXpGain(data, xp, hi);
    commit(d);
    const newLevel = getLevel(d.xp);
    if (newLevel.lv > prevLevel.lv) setLevelUp(newLevel);
    setReward({ icon: '⚡', title: '即トレ完了！', xp, message: `${correctCount}問正解` });
    setParticles(xp);
  }

  function handleExamComplete(correctCount) {
    const xp = correctCount * 10;
    if (xp <= 0) return;
    const prevLevel = getLevel(data.xp);
    const hi = buildHistoryItem('🎯', `模擬試験 ${correctCount}問正解`, xp);
    const d = applyXpGain(data, xp, hi);
    commit(d);
    const newLevel = getLevel(d.xp);
    if (newLevel.lv > prevLevel.lv) setLevelUp(newLevel);
    setReward({ icon: '🎯', title: '模擬試験完了！', xp, message: `${correctCount}問正解` });
    setParticles(xp);
  }

  function handleFinanceComplete(problemId, correctCount, totalCount) {
    const problem = FINANCE_PROBLEMS.find(p => p.id === problemId);
    const prev = data.financeProgress?.[problemId] || { attempts: 0, bestCorrect: 0, completed: false };
    const newBest = Math.max(prev.bestCorrect, correctCount);
    const nowCompleted = newBest === totalCount;
    const alreadyCompleted = prev.completed;
    const today = todayStr();

    let d = {
      ...data,
      financeProgress: {
        ...data.financeProgress,
        [problemId]: { attempts: prev.attempts + 1, bestCorrect: newBest, completed: nowCompleted },
      },
    };

    // 間隔反復スケジュール更新
    const rate = correctCount / totalCount;
    const prevSched = d.reviewSchedule?.[problemId] || { interval: 1, wrongStreak: 0 };
    if (rate >= 0.8) {
      const ni = Math.min((prevSched.interval || 1) * 2, 30);
      d.reviewSchedule = { ...(d.reviewSchedule || {}), [problemId]: { nextDate: addDays(today, ni), interval: ni, wrongStreak: 0 } };
    } else {
      const ws = (prevSched.wrongStreak || 0) + 1;
      const ni = ws <= 1 ? 1 : ws === 2 ? 3 : 7;
      d.reviewSchedule = { ...(d.reviewSchedule || {}), [problemId]: { nextDate: addDays(today, ni), interval: ni, wrongStreak: ws } };
    }

    let xpAwarded = 0;
    if (nowCompleted && !alreadyCompleted) {
      xpAwarded = problem.xp;
    } else if (!alreadyCompleted && correctCount > 0) {
      xpAwarded = correctCount * problem.partialXp;
    }

    if (xpAwarded > 0) {
      const hi = buildHistoryItem(problem.icon, `${problem.title} クリア`, xpAwarded);
      d = applyXpGain(d, xpAwarded, hi);
      commit(d);
      setReward({
        icon: problem.icon, title: problem.title, xp: xpAwarded,
        message: nowCompleted ? '全問正解！' : `${correctCount}/${totalCount} 正解`,
      });
      setParticles(xpAwarded);
    } else {
      commit(d);
    }
  }

  function handleCaseStudyComplete(problemId, correctCount, totalCount) {
    const problem = CASE_STUDY_PROBLEMS.find(p => p.id === problemId);
    const prev = data.caseProgress?.[problemId] || { attempts: 0, bestCorrect: 0, completed: false };
    const newBest = Math.max(prev.bestCorrect, correctCount);
    const nowCompleted = newBest === totalCount;
    const alreadyCompleted = prev.completed;
    const today = todayStr();

    let d = {
      ...data,
      caseProgress: {
        ...data.caseProgress,
        [problemId]: { attempts: prev.attempts + 1, bestCorrect: newBest, completed: nowCompleted },
      },
    };

    // 間隔反復スケジュール更新
    const rate = correctCount / totalCount;
    const prevSched = d.reviewSchedule?.[problemId] || { interval: 1, wrongStreak: 0 };
    if (rate >= 0.8) {
      const ni = Math.min((prevSched.interval || 1) * 2, 30);
      d.reviewSchedule = { ...(d.reviewSchedule || {}), [problemId]: { nextDate: addDays(today, ni), interval: ni, wrongStreak: 0 } };
    } else {
      const ws = (prevSched.wrongStreak || 0) + 1;
      const ni = ws <= 1 ? 1 : ws === 2 ? 3 : 7;
      d.reviewSchedule = { ...(d.reviewSchedule || {}), [problemId]: { nextDate: addDays(today, ni), interval: ni, wrongStreak: ws } };
    }

    let xpAwarded = 0;
    if (nowCompleted && !alreadyCompleted) {
      xpAwarded = problem.xp;
    } else if (!alreadyCompleted && correctCount > 0) {
      xpAwarded = correctCount * problem.partialXp;
    }

    if (xpAwarded > 0) {
      const hi = buildHistoryItem(problem.icon, `${problem.title} クリア`, xpAwarded);
      d = applyXpGain(d, xpAwarded, hi);
      commit(d);
      setReward({
        icon: problem.icon, title: problem.title, xp: xpAwarded,
        message: nowCompleted ? '全問正解！' : `${correctCount}/${totalCount} 正解`,
      });
      setParticles(xpAwarded);
    } else {
      commit(d);
    }
  }

  function handleSaveNote(note, deleteId) {
    let notes = [...(data.notes || [])];
    if (deleteId) {
      notes = notes.filter(n => n.id !== deleteId);
    } else if (note) {
      notes = [...notes, note];
    }
    commit({ ...data, notes });
  }

  function handleUpdateProcedure(updates) {
    commit({ ...data, ...updates });
  }

  const remainingQuests = QUESTS.filter(q => !data.completedToday.includes(q.id)).length;

  return (
    <div style={{
      minHeight: '100vh', background: C.bg, color: C.text,
      fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif',
      maxWidth: 480, margin: '0 auto', position: 'relative',
    }}>
      {/* Header */}
      <div style={{
        background: '#0d1117', borderBottom: `1px solid ${C.border}`,
        padding: '14px 16px',
        display: 'flex', alignItems: 'center', justifyContent: 'space-between',
        position: 'sticky', top: 0, zIndex: 100,
      }}>
        <div style={{ fontSize: 17, fontWeight: 700, color: C.accent }}>⚔️ 診断士クエスト</div>
        <div style={{ fontSize: 15, color: C.gold, fontWeight: 700 }}>{data.xp} XP</div>
      </div>

      {tab === 'quest' && (
        <QuestTab
          data={data}
          onCompleteQuest={handleCompleteQuest}
          onNavigate={(tabId, problemId) => {
            setTab(tabId);
            if (problemId) setPendingProblem(problemId);
          }}
        />
      )}
      {tab === 'procedure' && (
        <ProcedureTab
          data={data}
          onCompleteCase={handleCompleteCase}
          onNavigate={setTab}
          onUpdateProcedure={handleUpdateProcedure}
        />
      )}
      {tab === 'reflection' && (
        <ReflectionTab
          data={data}
          onSaveNote={handleSaveNote}
          aiQaHistory={data.aiQaHistory || []}
          onUpdateMemo={handleUpdateAiQaMemo}
          onDeleteQa={handleDeleteAiQa}
        />
      )}
      {tab === 'history' && (
        <HistoryTab data={data} />
      )}
      {tab === 'finance' && (
        <FinanceTab
          data={data}
          onFinanceComplete={handleFinanceComplete}
          onCaseStudyComplete={handleCaseStudyComplete}
          onExamComplete={handleExamComplete}
          onDrillComplete={handleDrillComplete}
          onEssayComplete={handleEssayComplete}
          onSaveApiKey={handleSaveApiKey}
          onSaveEssayHistory={handleSaveEssayHistory}
          onSignalComplete={handleSignalComplete}
          onProcessComplete={handleProcessComplete}
          onWritingComplete={handleWritingComplete}
          onSaveAiQa={handleSaveAiQa}
          pendingProblem={pendingProblem}
          onClearPending={() => setPendingProblem(null)}
        />
      )}

      <BottomNav active={tab} onChange={setTab} remainingCount={remainingQuests} />

      {reward   && <RewardPopup  reward={reward}  onClose={() => setReward(null)}   />}
      {particles && <XPParticles xp={particles}   onDone={() => setParticles(null)} />}
      {levelUp  && <LevelUpModal level={levelUp}  onClose={() => setLevelUp(null)}  />}
      {showGreeting && <LoginGreetingModal streak={data.streak || 0} onClose={() => setShowGreeting(false)} />}
      {showStamp    && <StampAnimation type={showStamp} onClose={() => setShowStamp(null)} />}
    </div>
  );
}
